export default "   assert deployment.description == result.description\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_resolve_update_passthrough_without_provider_data() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentUpdateRequest(description=\\\"new description\\\")\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=_FakeDb([]),\\n        payload=payload,\\n    )\\n\\n    assert resolved.spec is not None\\n    assert resolved.spec.description == \\\"new description\\\"\\n    assert resolved.provider_data is None\\n    assert mapper.util_flow_version_patch(payload) == FlowVersionPatch()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_resolve_update_preserves_explicit_null_description() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentUpdateRequest(description=None)\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=_FakeDb([]),\\n        payload=payload,\\n    )\\n\\n    assert resolved.spec is not None\\n    assert resolved.spec.description is None\\n    assert \\\"description\\\" in resolved.spec.model_fields_set\\n    assert resolved.provider_data is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_resolve_update_null_description_does_not_set_name() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentUpdateRequest(description=None, provider_data={\\\"llm\\\": TEST_WXO_LLM})\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=_FakeDb([]),\\n        payload=payload,\\n    )\\n\\n    assert resolved.spec is not None\\n    assert resolved.spec.description is None\\n    assert \\\"description\\\" in resolved.spec.model_fields_set\\n    assert \\\"name\\\" not in resolved.spec.model_fields_set\\n    provider_data = resolved.provider_data or {}\\n    assert provider_data[\\\"llm\\\"] == TEST_WXO_LLM\\n    assert provider_data[\\\"operations\\\"] == []\\n    assert provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"] is None\\n    assert provider_data[\\\"connections\\\"] == {\\\"raw_payloads\\\": None}\\n\\n\\ndef test_watsonx_mapper_flow_version_patch_without_provider_data_is_empty() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentUpdateRequest(description=\\\"new description\\\")\\n\\n    patch = mapper.util_flow_version_patch(payload)\\n\\n    assert patch.add_flow_version_ids == []\\n    assert patch.remove_flow_version_ids == []\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_resolve_update_rejects_explicit_null_provider_data() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentUpdateRequest(description=\\\"new description\\\", provider_data=None)\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await mapper.resolve_deployment_update(\\n            user_id=uuid4(),\\n            deployment_db_id=uuid4(),\\n            db=_FakeDb([]),\\n            payload=payload,\\n        )\\n\\n    assert exc_info.value.status_code == 422\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        mapper.util_flow_version_patch(payload)\\n    assert exc_info.value.status_code == 422\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_translates_create_bind_into_raw_tool_payload() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    flow_id = uuid4()\\n    project_id = uuid4()\\n    payload = DeploymentCreateRequest(\\n        provider_id=uuid4(),\\n        description=\\\"\\\",\\n        type=\\\"agent\\\",\\n        provider_data={\\n            \\\"display_name\\\": \\\"create-deploy\\\",\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"add_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"app_ids\\\": [\\\"app-one\\\"],\\n                }\\n            ],\\n        },\\n    )\\n    row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=flow_id,\\n        flow_name=\\\"Flow A\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n    )\\n\\n    resolved = await mapper.resolve_deployment_create(\\n        user_id=uuid4(),\\n        project_id=project_id,\\n        db=_FakeDb([row]),\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert resolved.spec.name is None\\n    assert provider_data[\\\"display_name\\\"] == \\\"create-deploy\\\"\\n    assert provider_data[\\\"llm\\\"] == TEST_WXO_LLM\\n    raw_tool_name = provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"][0][\\\"name\\\"]\\n    raw_provider_data = provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"][0][\\\"provider_data\\\"]\\n    assert raw_provider_data[\\\"project_id\\\"] == str(project_id)\\n    assert raw_provider_data[\\\"source_ref\\\"] == str(flow_version_id)\\n    assert raw_provider_data[\\\"tool_display_name\\\"] == \\\"Flow A\\\"\\n    assert raw_provider_data[\\\"tool_name\\\"].startswith(\\\"langflow_Flow_A_\\\")\\n    assert raw_tool_name == \\\"Flow A\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"name_of_raw\\\"] == raw_provider_data[\\\"tool_name\\\"]\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"flow_data\\\", \\\"expected_detail\\\"),\\n    [\\n        (\\n            {\\\"nodes\\\": [{\\\"data\\\": {\\\"type\\\": \\\"ChatOutput\\\"}}], \\\"edges\\\": []},\\n            \\\"Add one Chat Input ('ChatInput') node\\\",\\n        ),\\n        (\\n            {\\n                \\\"nodes\\\": [\\n                    {\\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\"}},\\n                    {\\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\"}},\\n                    {\\\"data\\\": {\\\"type\\\": \\\"ChatOutput\\\"}},\\n                ],\\n                \\\"edges\\\": [],\\n            },\\n            \\\"Remove extra Chat Input ('ChatInput') nodes\\\",\\n        ),\\n        (\\n            {\\\"nodes\\\": [{\\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\"}}], \\\"edges\\\": []},\\n            \\\"Add at least one Chat Output ('ChatOutput') node\\\",\\n        ),\\n    ],\\n)\\nasync def test_watsonx_mapper_rejects_ineligible_flow_before_building_create_payload(\\n    flow_data: dict,\\n    expected_detail: str,\\n) -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    payload = DeploymentCreateRequest(\\n        provider_id=uuid4(),\\n        description=\\\"\\\",\\n        type=\\\"agent\\\",\\n        provider_data={\\n            \\\"display_name\\\": \\\"create-deploy\\\",\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"add_flows\\\": [{\\\"flow_version_id\\\": str(flow_version_id), \\\"app_ids\\\": []}],\\n        },\\n    )\\n    row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_data=flow_data,\\n        flow_id=uuid4(),\\n        flow_name=\\\"Ineligible Flow\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[],\\n    )\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await mapper.resolve_deployment_create(\\n            user_id=uuid4(),\\n            project_id=uuid4(),\\n            db=_FakeDb([row]),\\n            payload=payload,\\n        )\\n\\n    assert exc_info.value.status_code == 422\\n    assert \\\"Ineligible Flow\\\" in exc_info.value.detail\\n    assert str(flow_version_id) in exc_info.value.detail\\n    assert expected_detail in exc_info.value.detail\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_translates_create_bind_with_tool_display_name_override() -> None:\\n    \\\"\\\"\\\"Create bind should generate a technical name from the tool_display_name override.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    flow_id = uuid4()\\n    project_id = uuid4()\\n    payload = DeploymentCreateRequest(\\n        provider_id=uuid4(),\\n        description=\\\"\\\",\\n        type=\\\"agent\\\",\\n        provider_data={\\n            \\\"display_name\\\": \\\"create-deploy\\\",\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"add_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"tool_display_name\\\": \\\"My Create Tool\\\",\\n                    \\\"app_ids\\\": [\\\"app-one\\\"],\\n                }\\n            ],\\n        },\\n    )\\n    row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=flow_id,\\n        flow_name=\\\"Flow A\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n    )\\n\\n    resolved = await mapper.resolve_deployment_create(\\n        user_id=uuid4(),\\n        project_id=project_id,\\n        db=_FakeDb([row]),\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert resolved.spec.name is None\\n    assert provider_data[\\\"display_name\\\"] == \\\"create-deploy\\\"\\n    raw_tool_name = provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"][0][\\\"name\\\"]\\n    raw_provider_data = provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"][0][\\\"provider_data\\\"]\\n    assert raw_provider_data[\\\"tool_display_name\\\"] == \\\"My Create Tool\\\"\\n    assert raw_provider_data[\\\"tool_name\\\"].startswith(\\\"langflow_My_Create_Tool_\\\")\\n    assert raw_tool_name == \\\"Flow A\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"op\\\"] == \\\"bind\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"name_of_raw\\\"] == raw_provider_data[\\\"tool_name\\\"]\\n    assert all(op[\\\"op\\\"] != \\\"rename_tool\\\" for op in provider_data[\\\"operations\\\"])\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_maps_create_adapter_payload_validation_errors_to_500(monkeypatch) -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    flow_id = uuid4()\\n    payload = DeploymentCreateRequest(\\n        provider_id=uuid4(),\\n        description=\\\"\\\",\\n        type=\\\"agent\\\",\\n        provider_data={\\n            \\\"display_name\\\": \\\"create-deploy\\\",\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"add_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"app_ids\\\": [\\\"app-one\\\"],\\n                }\\n            ],\\n        },\\n    )\\n    row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=flow_id,\\n        flow_name=\\\"Flow A\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n    )\\n\\n    fake_validation_error = SimpleNamespace(errors=lambda: [{\\\"msg\\\": \\\"simulated adapter validation failure\\\"}])\\n\\n    original_parse = PayloadSlot.parse\\n\\n    def _parse_with_deployment_create_failure(_self, _raw):\\n        if _self.adapter_model.__name__ == \\\"WatsonxDeploymentCreatePayload\\\":\\n            raise AdapterPayloadValidationError(\\n                model_name=\\\"WatsonxDeploymentCreatePayload\\\",\\n                error=fake_validation_error,  # type: ignore[arg-type]\\n            )\\n        return original_parse(_self, _raw)\\n\\n    monkeypatch.setattr(PayloadSlot, \\\"parse\\\", _parse_with_deployment_create_failure)\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await mapper.resolve_deployment_create(\\n            user_id=uuid4(),\\n            project_id=uuid4(),\\n            db=_FakeDb([row]),\\n            payload=payload,\\n        )\\n    assert exc_info.value.status_code == 500\\n    assert (\\n        exc_info.value.detail\\n        == \\\"Unexpected result while building the deployment_create provider payload (watsonx Orchestrate): \\\"\\n        \\\"Invalid payload.\\\"\\n    )\\n\\n\\nasync def test_watsonx_mapper_create_reports_missing_llm_field_name() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentCreateRequest(\\n        provider_id=uuid4(),\\n        description=\\\"\\\",\\n        type=\\\"agent\\\",\\n        provider_data={\\n            \\\"display_name\\\": \\\"create-deploy\\\",\\n            \\\"connections\\\": [],\\n            \\\"add_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(uuid4()),\\n                    \\\"app_ids\\\": [\\\"app-one\\\"],\\n                }\\n            ],\\n        },\\n    )\\n\\n    with pytest.raises(HTTPException) as exc:\\n        await mapper.resolve_deployment_create(\\n            user_id=uuid4(),\\n            project_id=uuid4(),\\n            db=_FakeDb([]),\\n            payload=payload,\\n        )\\n\\n    assert exc.value.status_code == 422\\n    assert (\\n        exc.value.detail\\n        == \\\"Invalid provider_data for watsonx Orchestrate: provider_data.llm is required for new agent creation.\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_create_reports_unknown_field_name() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentCreateRequest(\\n        provider_id=uuid4(),\\n        description=\\\"\\\",\\n        type=\\\"agent\\\",\\n        provider_data={\\n            \\\"display_name\\\": \\\"create-deploy\\\",\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"resource_name_prefix\\\": \\\"lf_test_\\\",\\n            \\\"upsert_tools\\\": [\\n                {\\n                    \\\"tool_id\\\": \\\"existing-tool\\\",\\n                    \\\"add_app_ids\\\": [],\\n                }\\n            ],\\n        },\\n    )\\n\\n    with pytest.raises(HTTPException) as exc:\\n        await mapper.resolve_deployment_create(\\n            user_id=uuid4(),\\n            project_id=uuid4(),\\n            db=_FakeDb([]),\\n            payload=payload,\\n        )\\n\\n    assert exc.value.status_code == 422\\n    assert (\\n        exc.value.detail\\n        == \\\"Invalid provider_data for watsonx Orchestrate: Invalid field 'resource_name_prefix'. Please remove it.\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_create_skips_empty_bind_operations_but_keeps_raw_tools() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    flow_id = uuid4()\\n    project_id = uuid4()\\n    row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=flow_id,\\n        flow_name=\\\"Flow A\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n    )\\n    payload = DeploymentCreateRequest(\\n        provider_id=uuid4(),\\n        description=\\\"\\\",\\n        type=\\\"agent\\\",\\n        provider_data={\\n            \\\"display_name\\\": \\\"create-deploy\\\",\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"add_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"app_ids\\\": [],\\n                }\\n            ],\\n        },\\n    )\\n\\n    resolved = await mapper.resolve_deployment_create(\\n        user_id=uuid4(),\\n        project_id=project_id,\\n        db=_FakeDb([row]),\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"llm\\\"] == TEST_WXO_LLM\\n    assert provider_data[\\\"operations\\\"] == []\\n    assert len(provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"]) == 1\\n    raw_tool_name = provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"][0][\\\"name\\\"]\\n    raw_provider_data = provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"][0][\\\"provider_data\\\"]\\n    assert raw_provider_data[\\\"project_id\\\"] == str(project_id)\\n    assert raw_provider_data[\\\"source_ref\\\"] == str(flow_version_id)\\n    assert raw_provider_data[\\\"tool_display_name\\\"] == \\\"Flow A\\\"\\n    assert raw_provider_data[\\\"tool_name\\\"].startswith(\\\"langflow_Flow_A_\\\")\\n    assert raw_tool_name == \\\"Flow A\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_translates_flow_version_bind_into_raw_tool_payload() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    flow_id = uuid4()\\n    project_id = uuid4()\\n    row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_number=1,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=flow_id,\\n        flow_name=\\\"Flow A\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n        project_id=project_id,\\n    )\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"upsert_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"add_app_ids\\\": [\\\"app-one\\\"],\\n                    \\\"remove_app_ids\\\": [],\\n                }\\n            ],\\n        }\\n    )\\n\\n    db = _MultiQueryFakeDb(flow_rows=[row], attachment_rows=[])\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"llm\\\"] == TEST_WXO_LLM\\n    raw_tool_name = provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"][0][\\\"name\\\"]\\n    raw_provider_data = provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"][0][\\\"provider_data\\\"]\\n    assert raw_provider_data[\\\"project_id\\\"] == str(project_id)\\n    assert raw_provider_data[\\\"source_ref\\\"] == str(flow_version_id)\\n    assert raw_provider_data[\\\"tool_display_name\\\"] == \\\"Flow A\\\"\\n    assert raw_provider_data[\\\"tool_name\\\"].startswith(\\\"langflow_Flow_A_\\\")\\n    assert raw_tool_name == \\\"Flow A\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"name_of_raw\\\"] == raw_provider_data[\\\"tool_name\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_skips_empty_bind_operations_but_keeps_raw_tools() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id_unbound = uuid4()\\n    flow_version_id_bound = uuid4()\\n    project_id = uuid4()\\n    row_unbound = SimpleNamespace(\\n        flow_version_id=flow_version_id_unbound,\\n        flow_version_number=1,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=uuid4(),\\n        flow_name=\\\"Flow Unbound\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n        project_id=project_id,\\n    )\\n    row_bound = SimpleNamespace(\\n        flow_version_id=flow_version_id_bound,\\n        flow_version_number=2,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=uuid4(),\\n        flow_name=\\\"Flow Bound\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n        project_id=project_id,\\n    )\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"upsert_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id_unbound),\\n                    \\\"add_app_ids\\\": [],\\n                    \\\"remove_app_ids\\\": [],\\n                },\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id_bound),\\n                    \\\"add_app_ids\\\": [\\\"app-one\\\"],\\n                    \\\"remove_app_ids\\\": [],\\n                },\\n            ],\\n        }\\n    )\\n    db = _MultiQueryFakeDb(flow_rows=[row_unbound, row_bound], attachment_rows=[])\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert len(provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"]) == 2\\n    raw_payload_by_source_ref = {\\n        item[\\\"provider_data\\\"][\\\"source_ref\\\"]: item for item in provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"]\\n    }\\n    assert set(raw_payload_by_source_ref) == {str(flow_version_id_bound), str(flow_version_id_unbound)}\\n    assert len(provider_data[\\\"operations\\\"]) == 1\\n    assert (\\n        provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"name_of_raw\\\"]\\n        == raw_payload_by_source_ref[str(flow_version_id_bound)][\\\"provider_data\\\"][\\\"tool_name\\\"]\\n    )\\n    assert provider_data[\\\"operations\\\"][0][\\\"app_ids\\\"] == [\\\"app-one\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_translates_llm_only_update_payload() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentUpdateRequest(provider_data={\\\"llm\\\": TEST_WXO_LLM})\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=_FakeDb([]),\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"llm\\\"] == TEST_WXO_LLM\\n    assert \\\"display_name\\\" not in provider_data\\n    assert provider_data[\\\"operations\\\"] == []\\n    assert provider_data[\\\"tools\\\"].get(\\\"raw_payloads\\\") is None\\n    assert provider_data[\\\"connections\\\"].get(\\\"raw_payloads\\\") is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_translates_unbind_and_remove_via_attachment_snapshot_ids() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id_unbind = uuid4()\\n    flow_version_id_remove = uuid4()\\n    deployment_db_id = uuid4()\\n    user_id = uuid4()\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"upsert_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id_unbind),\\n                    \\\"add_app_ids\\\": [],\\n                    \\\"remove_app_ids\\\": [\\\"app-one\\\"],\\n                },\\n            ],\\n            \\\"remove_flows\\\": [str(flow_version_id_remove)],\\n        }\\n    )\\n    db = _FakeDb(\\n        [\\n            SimpleNamespace(\\n                flow_version_id=flow_version_id_unbind,\\n                provider_snapshot_id=\\\"tool-1\\\",\\n            ),\\n            SimpleNamespace(\\n                flow_version_id=flow_version_id_remove,\\n                provider_snapshot_id=\\\"tool-2\\\",\\n            ),\\n        ]\\n    )\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=user_id,\\n        deployment_db_id=deployment_db_id,\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"tool-1\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"source_ref\\\"] == str(flow_version_id_unbind)\\n    assert provider_data[\\\"operations\\\"][1][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"tool-2\\\"\\n    assert provider_data[\\\"operations\\\"][1][\\\"tool\\\"][\\\"source_ref\\\"] == str(flow_version_id_remove)\\n\\n\\ndef test_watsonx_update_result_data_preserves_provider_owned_strings() -> None:\\n    flow_version_id = uuid4()\\n    data = WatsonxApiDeploymentUpdateResultData.from_provider_result(\\n        {\\n            \\\"name\\\": \\\"agent_technical_name\\\",\\n            \\\"display_name\\\": \\\"Agent Display Name\\\",\\n            \\\"created_app_ids\\\": [\\\"  app-one  \\\", \\\"app-two\\\"],\\n            \\\"created_tools\\\": [\\n                {\\\"flow_version_id\\\": str(flow_version_id), \\\"tool_id\\\": \\\"tool-1\\\"},\\n            ],\\n            \\\"ignored_key\\\": True,\\n        }\\n    )\\n\\n    assert data.name == \\\"agent_technical_name\\\"\\n    assert data.display_name == \\\"Agent Display Name\\\"\\n    assert data.created_app_ids == [\\\"  app-one  \\\", \\\"app-two\\\"]\\n    assert data.created_tools is not None\\n    assert data.created_tools[0].flow_version_id == flow_version_id\\n    assert data.created_tools[0].tool_id == \\\"tool-1\\\"\\n\\n\\ndef test_watsonx_mapper_shapes_update_response_from_result_schema() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    timestamp = datetime.now(tz=timezone.utc)\\n    deployment_id = uuid4()\\n    provider_account_id = uuid4()\\n    deployment_row = SimpleNamespace(\\n        id=deployment_id,\\n        deployment_provider_account_id=provider_account_id,\\n        resource_key=\\\"agent-123\\\",\\n        display_name=\\\"WXO Deployment\\\",\\n        description=\\\"updated\\\",\\n        deployment_type=DeploymentType.AGENT,\\n        created_at=timestamp,\\n        updated_at=timestamp,\\n    )\\n    new_flow_version_id = uuid4()\\n    result = DeploymentUpdateResult(\\n        id=\\\"provider-id\\\",\\n        provider_result={\\n            \\\"name\\\": \\\"agent_technical_name\\\",\\n            \\\"display_name\\\": \\\"Provider Label\\\",\\n            \\\"created_app_ids\\\": [\\\"created-app-1\\\"],\\n            \\\"created_snapshot_bindings\\\": [\\n                {\\\"source_ref\\\": str(new_flow_version_id), \\\"tool_id\\\": \\\"new-tool-1\\\", \\\"created\\\": True}\\n            ],\\n        },\\n    )\\n\\n    shaped = mapper.shape_deployment_update_result(result, deployment_row, provider_key=\\\"watsonx-orchestrate\\\")\\n\\n    assert shaped.id == deployment_id\\n    assert shaped.provider_id == provider_account_id\\n    assert shaped.provider_key == \\\"watsonx-orchestrate\\\"\\n    assert shaped.resource_key == \\\"agent-123\\\"\\n    assert shaped.provider_data == {\\n        \\\"name\\\": \\\"agent_technical_name\\\",\\n        \\\"display_name\\\": \\\"Provider Label\\\",\\n        \\\"created_app_ids\\\": [\\\"created-app-1\\\"],\\n        \\\"created_tools\\\": [\\n            {\\\"flow_version_id\\\": str(new_flow_version_id), \\\"tool_id\\\": \\\"new-tool-1\\\"},\\n        ],\\n    }\\n\\n\\ndef test_watsonx_mapper_shapes_update_response_with_provider_display_name() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    timestamp = datetime.now(tz=timezone.utc)\\n    deployment_row = SimpleNamespace(\\n        id=uuid4(),\\n        deployment_provider_account_id=uuid4(),\\n        resource_key=\\\"agent-123\\\",\\n        display_name=\\\"Stale DB Label\\\",\\n        description=\\\"updated\\\",\\n        deployment_type=DeploymentType.AGENT,\\n        created_at=timestamp,\\n        updated_at=timestamp,\\n    )\\n    result = DeploymentUpdateResult(\\n        id=\\\"provider-id\\\",\\n        provider_result={\\n            \\\"name\\\": \\\"agent_technical_name\\\",\\n            \\\"display_name\\\": \\\"Provider Label\\\",\\n            \\\"description\\\": \\\"Provider description\\\",\\n            \\\"created_app_ids\\\": [],\\n            \\\"created_snapshot_bindings\\\": [],\\n        },\\n    )\\n\\n    shaped = mapper.shape_deployment_update_result(result, deployment_row, provider_key=\\\"watsonx-orchestrate\\\")\\n\\n    assert shaped.provider_data[\\\"display_name\\\"] == \\\"Provider Label\\\"\\n\\n\\ndef test_watsonx_mapper_resolves_kwargs_for_metadata_update_from_adapter_result() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    description = \\\"x\\\" * 501\\n    result = DeploymentUpdateResult(\\n        id=\\\"provider-id\\\",\\n        provider_result={\\n            \\\"name\\\": \\\"agent_technical_name\\\",\\n            \\\"display_name\\\": \\\"Provider Label\\\",\\n            \\\"description\\\": description,\\n        },\\n    )\\n\\n    metadata = mapper.resolve_kwargs_for_metadata_update(result)\\n\\n    assert metadata == {\\n        \\\"display_name\\\": \\\"Provider Label\\\",\\n        \\\"description\\\": description,\\n    }\\n\\n\\ndef test_watsonx_mapper_update_response_rejects_non_uuid_source_ref() -> None:\\n    \\\"\\\"\\\"Non-UUID source_ref in created_snapshot_bindings raises HTTP 500.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    timestamp = datetime.now(tz=timezone.utc)\\n    provider_account_id = uuid4()\\n    deployment_row = SimpleNamespace(\\n        id=uuid4(),\\n        deployment_provider_account_id=provider_account_id,\\n        resource_key=\\\"agent-123\\\",\\n        display_name=\\\"WXO Deployment\\\",\\n        description=\\\"updated\\\",\\n        deployment_type=DeploymentType.AGENT,\\n        created_at=timestamp,\\n        updated_at=timestamp,\\n    )\\n    result = DeploymentUpdateResult(\\n        id=\\\"provider-id\\\",\\n        provider_result={\\n            \\\"name\\\": \\\"agent_technical_name\\\",\\n            \\\"display_name\\\": \\\"Provider Label\\\",\\n            \\\"created_app_ids\\\": [],\\n            \\\"created_snapshot_bindings\\\": [\\n                {\\\"source_ref\\\": \\\"not-a-uuid\\\", \\\"tool_id\\\": \\\"tool-1\\\", \\\"created\\\": True},\\n            ],\\n        },\\n    )\\n\\n    with pytest.raises(HTTPException) as exc:\\n        mapper.shape_deployment_update_result(result, deployment_row, provider_key=\\\"watsonx-orchestrate\\\")\\n    assert exc.value.status_code == 500\\n    assert \\\"non-UUID source_ref\\\" in exc.value.detail\\n\\n\\ndef test_watsonx_mapper_shapes_create_response_with_provider_names() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    timestamp = datetime.now(tz=timezone.utc)\\n    provider_account_id = uuid4()\\n    flow_version_id = uuid4()\\n    deployment_row = SimpleNamespace(\\n        id=uuid4(),\\n        deployment_provider_account_id=provider_account_id,\\n        resource_key=\\\"agent-123\\\",\\n        display_name=\\\"WXO Deployment\\\",\\n        description=\\\"created\\\",\\n        deployment_type=DeploymentType.AGENT,\\n        created_at=timestamp,\\n        updated_at=timestamp,\\n    )\\n    result = DeploymentCreateResult(\\n        id=\\\"provider-id\\\",\\n        type=DeploymentType.AGENT,\\n        name=\\\"agent_technical_name\\\",\\n        description=\\\"created\\\",\\n        provider_result={\\n            \\\"display_name\\\": \\\"WXO Deployment\\\",\\n            \\\"app_ids\\\": [\\\"created-app-1\\\"],\\n            \\\"tools_with_refs\\\": [\\n                {\\\"source_ref\\\": str(flow_version_id), \\\"tool_id\\\": \\\"new-tool-1\\\"},\\n            ],\\n        },\\n    )\\n\\n    shaped = mapper.shape_deployment_create_result(result, deployment_row, provider_key=\\\"watsonx-orchestrate\\\")\\n\\n    assert shaped.provider_data == {\\n        \\\"name\\\": \\\"agent_technical_name\\\",\\n        \\\"display_name\\\": \\\"WXO Deployment\\\",\\n        \\\"created_app_ids\\\": [\\\"created-app-1\\\"],\\n        \\\"created_tools\\\": [\\n            {\\\"flow_version_id\\\": str(flow_version_id), \\\"tool_id\\\": \\\"new-tool-1\\\"},\\n        ],\\n    }\\n\\n\\ndef test_watsonx_mapper_create_response_rejects_non_uuid_source_ref_in_created_tools() -> None:\\n    \\\"\\\"\\\"Create result must reject non-UUID source_ref in created tools.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    timestamp = datetime.now(tz=timezone.utc)\\n    provider_account_id = uuid4()\\n    deployment_row = SimpleNamespace(\\n        id=uuid4(),\\n        deployment_provider_account_id=provider_account_id,\\n        resource_key=\\\"agent-123\\\",\\n        display_name=\\\"WXO Deployment\\\",\\n        description=\\\"updated\\\",\\n        deployment_type=DeploymentType.AGENT,\\n        created_at=timestamp,\\n        updated_at=timestamp,\\n    )\\n    result = DeploymentCreateResult(\\n        id=\\\"provider-id\\\",\\n        type=DeploymentType.AGENT,\\n        name=\\\"agent_technical_name\\\",\\n        description=\\\"updated\\\",\\n        provider_result={\\n            \\\"display_name\\\": \\\"WXO Deployment\\\",\\n            \\\"app_ids\\\": [],\\n            \\\"tools_with_refs\\\": [\\n                {\\\"source_ref\\\": \\\"not-a-uuid\\\", \\\"tool_id\\\": \\\"orphan-tool\\\"},\\n            ],\\n        },\\n    )\\n\\n    with pytest.raises(HTTPException) as exc:\\n        mapper.shape_deployment_create_result(result, deployment_row, provider_key=\\\"watsonx-orchestrate\\\")\\n    assert exc.value.status_code == 500\\n    assert \\\"orphan-tool\\\" in exc.value.detail\\n    assert \\\"non-UUID source_ref\\\" in exc.value.detail\\n\\n\\ndef test_watsonx_mapper_shapes_llm_list_result() -> None:\\n    \\\"\\\"\\\"Duplicates are intentionally passed through; deduplication is a client concern.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    result = DeploymentListLlmsResult(\\n        provider_result={\\n            \\\"models\\\": [\\n                {\\\"model_name\\\": \\\"granite-3.1-8b\\\"},\\n                {\\\"model_name\\\": \\\"granite-3.3-8b\\\"},\\n                {\\\"model_name\\\": \\\"granite-3.1-8b\\\"},\\n            ]\\n        },\\n    )\\n\\n    shaped = mapper.shape_llm_list_result(result)\\n    assert shaped.provider_data == {\\n        \\\"models\\\": [\\n            {\\\"model_name\\\": \\\"granite-3.1-8b\\\"},\\n            {\\\"model_name\\\": \\\"granite-3.3-8b\\\"},\\n            {\\\"model_name\\\": \\\"granite-3.1-8b\\\"},\\n        ]\\n    }\\n\\n\\ndef test_watsonx_mapper_llm_list_result_raises_for_missing_provider_payload() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    result = DeploymentListLlmsResult(provider_result=None)\\n\\n    with pytest.raises(HTTPException) as exc:\\n        mapper.shape_llm_list_result(result)\\n    assert exc.value.status_code == 500\\n    assert \\\"Empty result while listing available models\\\" in exc.value.detail\\n\\n\\ndef test_watsonx_mapper_exposes_reconciliation_resolvers() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    add_id = uuid4()\\n    unbind_only_id = uuid4()\\n    remove_id = uuid4()\\n    patch = mapper.util_flow_version_patch(\\n        DeploymentUpdateRequest(\\n            provider_data={\\n                \\\"llm\\\": TEST_WXO_LLM,\\n                \\\"connections\\\": [],\\n                \\\"upsert_flows\\\": [\\n                    {\\n                        \\\"flow_version_id\\\": str(add_id),\\n                        \\\"add_app_ids\\\": [\\\"app-one\\\"],\\n                        \\\"remove_app_ids\\\": [],\\n                    },\\n                    {\\n                        \\\"flow_version_id\\\": str(unbind_only_id),\\n                        \\\"add_app_ids\\\": [],\\n                        \\\"remove_app_ids\\\": [\\\"app-one\\\"],\\n                    },\\n                ],\\n                \\\"remove_flows\\\": [str(remove_id)],\\n            }\\n        )\\n    )\\n    assert isinstance(patch, FlowVersionPatch)\\n    add_ids, remove_ids = patch.add_flow_version_ids, patch.remove_flow_version_ids\\n    assert add_ids == [add_id]\\n    assert remove_ids == [remove_id]\\n\\n    create_bindings = mapper.util_create_snapshot_bindings(\\n        result=DeploymentCreateResult(\\n            id=\\\"provider-id\\\",\\n            type=DeploymentType.AGENT,\\n            name=\\\"agent_technical_name\\\",\\n            description=\\\"created\\\",\\n            provider_result={\\n                \\\"display_name\\\": \\\"Agent Display Name\\\",\\n                \\\"tools_with_refs\\\": [{\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"snap-1\\\"}],\\n            },\\n        ),\\n    )\\n    assert isinstance(create_bindings, CreateSnapshotBindings)\\n    assert create_bindings.to_source_ref_map() == {\\\"fv-1\\\": \\\"snap-1\\\"}\\n\\n    created_ids = mapper.util_created_snapshot_ids(\\n        result=DeploymentUpdateResult(\\n            id=\\\"provider-id\\\",\\n            provider_result={\\n                \\\"name\\\": \\\"agent_technical_name\\\",\\n                \\\"display_name\\\": \\\"Provider Label\\\",\\n                \\\"created_snapshot_ids\\\": [\\\"snap-1\\\"],\\n                \\\"added_snapshot_bindings\\\": [{\\\"source_ref\\\": str(add_id), \\\"tool_id\\\": \\\"snap-1\\\", \\\"created\\\": True}],\\n            },\\n        ),\\n    )\\n    assert isinstance(created_ids, CreatedSnapshotIds)\\n    assert created_ids.ids == [\\\"snap-1\\\"]\\n    update_bindings = mapper.util_update_snapshot_bindings(\\n        result=DeploymentUpdateResult(\\n            id=\\\"provider-id\\\",\\n            provider_result={\\n                \\\"name\\\": \\\"agent_technical_name\\\",\\n                \\\"display_name\\\": \\\"Provider Label\\\",\\n                \\\"added_snapshot_bindings\\\": [{\\\"source_ref\\\": str(add_id), \\\"tool_id\\\": \\\"snap-1\\\", \\\"created\\\": True}],\\n            },\\n        ),\\n    )\\n    assert isinstance(update_bindings, UpdateSnapshotBindings)\\n    assert update_bindings.to_source_ref_map() == {str(add_id): \\\"snap-1\\\"}\\n\\n\\ndef test_wxo_mapper_provider_account_response_includes_tenant_id() -> None:\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    timestamp = datetime.now(tz=timezone.utc)\\n    account = SimpleNamespace(\\n        id=uuid4(),\\n        name=\\\"staging\\\",\\n        provider_tenant_id=\\\"tenant-1\\\",\\n        provider_key=\\\"watsonx-orchestrate\\\",\\n        provider_url=\\\"https://provider.example\\\",\\n        created_at=timestamp,\\n        updated_at=timestamp,\\n    )\\n\\n    shaped = mapper.resolve_provider_account_response(account)\\n\\n    assert shaped.id == account.id\\n    assert shaped.name == \\\"staging\\\"\\n    assert shaped.provider_key == \\\"watsonx-orchestrate\\\"\\n    assert shaped.provider_data == {\\n        \\\"url\\\": \\\"https://provider.example\\\",\\n        \\\"tenant_id\\\": \\\"tenant-1\\\",\\n    }\\n\\n\\ndef test_watsonx_mapper_trusts_top_level_deployment_id() -> None:\\n    \\\"\\\"\\\"WXO mapper inherits base behavior: trust result.deployment_id directly.\\\"\\\"\\\"\\n    from lfx.services.adapters.deployment.schema import ExecutionStatusResult\\n\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    result = ExecutionStatusResult(\\n        execution_id=\\\"e-1\\\",\\n        deployment_id=\\\"agent-1\\\",\\n        provider_result={\\\"agent_id\\\": \\\"agent-1\\\", \\\"status\\\": \\\"accepted\\\"},\\n    )\\n    assert mapper.util_resource_key_from_execution(result) == \\\"agent-1\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# resolve_verify_credentials_for_create\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_wxo_mapper_verify_credentials_create_filters_non_credential_fields() -> None:\\n    \\\"\\\"\\\"WXO mapper forwards only credential fields to adapter verification.\\\"\\\"\\\"\\n    from langflow.api.v1.schemas.deployments import DeploymentProviderAccountCreateRequest\\n    from lfx.services.adapters.deployment.schema import VerifyCredentials\\n\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentProviderAccountCreateRequest(\\n        name=\\\"test-account\\\",\\n        provider_key=\\\"watsonx-orchestrate\\\",\\n        provider_data={\\n            \\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com\\\",\\n            \\\"tenant_id\\\": \\\"tenant-123\\\",\\n            \\\"api_key\\\": \\\"my-secret-key\\\",  # pragma: allowlist secret\\n        },\\n    )\\n    result = mapper.resolve_verify_credentials_for_create(payload=payload)\\n    assert isinstance(result, VerifyCredentials)\\n    assert result.base_url == \\\"https://api.us-south.wxo.cloud.ibm.com/\\\"\\n    assert result.provider_data is not None\\n    assert result.provider_data[\\\"api_key\\\"] == \\\"my-secret-key\\\"  # pragma: allowlist secret\\n    assert \\\"tenant_id\\\" not in result.provider_data\\n\\n\\ndef test_wxo_mapper_verify_credentials_create_accepts_missing_tenant() -> None:\\n    \\\"\\\"\\\"Verify-credentials path only parses; tenant validation is deferred to resolve_provider_account_create.\\\"\\\"\\\"\\n    from langflow.api.v1.schemas.deployments import DeploymentProviderAccountCreateRequest\\n    from lfx.services.adapters.deployment.schema import VerifyCredentials\\n\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentProviderAccountCreateRequest(\\n        name=\\\"test-account\\\",\\n        provider_key=\\\"watsonx-orchestrate\\\",\\n        provider_data={\\n            \\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com\\\",\\n            \\\"api_key\\\": \\\"my-secret-key\\\",  # pragma: allowlist secret\\n        },\\n    )\\n\\n    result = mapper.resolve_verify_credentials_for_create(payload=payload)\\n    assert isinstance(result, VerifyCredentials)\\n    assert result.base_url == \\\"https://api.us-south.wxo.cloud.ibm.com/\\\"\\n\\n\\ndef test_wxo_mapper_provider_account_create_requires_tenant() -> None:\\n    \\\"\\\"\\\"Create path rejects payloads with no explicit or URL-derived tenant.\\\"\\\"\\\"\\n    from langflow.api.v1.schemas.deployments import DeploymentProviderAccountCreateRequest\\n\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentProviderAccountCreateRequest(\\n        name=\\\"test-account\\\",\\n        provider_key=\\\"watsonx-orchestrate\\\",\\n        provider_data={\\n            \\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com\\\",\\n            \\\"api_key\\\": \\\"my-secret-key\\\",  # pragma: allowlist secret\\n        },\\n    )\\n\\n    with pytest.raises(ValueError, match=r\\\"provider_data\\\\.tenant_id is required\\\"):\\n        mapper.resolve_provider_account_create(payload=payload, user_id=\\\"user-1\\\")\\n\\n\\ndef test_wxo_mapper_resolve_credentials_returns_api_key() -> None:\\n    \\\"\\\"\\\"WXO mapper extracts api_key from provider_data for DB storage.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    result = mapper.resolve_credentials(provider_data={\\\"api_key\\\": \\\"my-key\\\"})  # pragma: allowlist secret\\n    assert result == {\\\"api_key\\\": \\\"my-key\\\"}  # pragma: allowlist secret\\n\\n\\ndef test_wxo_mapper_resolve_credentials_rejects_tenant_metadata() -> None:\\n    \\\"\\\"\\\"Update-path credential extraction rejects non-credential fields.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    with pytest.raises(HTTPException) as exc_info:\\n        mapper.resolve_credentials(\\n            provider_data={\\n                \\\"tenant_id\\\": \\\"tenant-123\\\",\\n                \\\"api_key\\\": \\\"my-key\\\",  # pragma: allowlist secret\\n            }\\n        )\\n    assert exc_info.value.status_code == 422\\n    assert \\\"tenant_id\\\" in exc_info.value.detail\\n\\n\\ndef test_wxo_mapper_verify_credentials_create_rejects_unknown_fields() -> None:\\n    \\\"\\\"\\\"Mapper rejects unexpected provider_data keys.\\\"\\\"\\\"\\n    from langflow.api.v1.schemas.deployments import DeploymentProviderAccountCreateRequest\\n\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentProviderAccountCreateRequest(\\n        name=\\\"test-account\\\",\\n        provider_key=\\\"watsonx-orchestrate\\\",\\n        provider_data={\\n            \\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com\\\",\\n            \\\"tenant_id\\\": \\\"tenant-123\\\",\\n            \\\"api_key\\\": \\\"my-secret-key\\\",  # pragma: allowlist secret\\n            \\\"unexpected\\\": \\\"field\\\",\\n        },\\n    )\\n    with pytest.raises(HTTPException) as exc_info:\\n        mapper.resolve_verify_credentials_for_create(payload=payload)\\n    assert exc_info.value.status_code == 422\\n    assert \\\"Invalid field 'unexpected'\\\" in exc_info.value.detail\\n\\n\\ndef test_wxo_mapper_resolve_credentials_strips_whitespace() -> None:\\n    \\\"\\\"\\\"WXO mapper strips whitespace from api_key.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    result = mapper.resolve_credentials(provider_data={\\\"api_key\\\": \\\"  my-key  \\\"})  # pragma: allowlist secret\\n    assert result == {\\\"api_key\\\": \\\"my-key\\\"}  # pragma: allowlist secret\\n\\n\\ndef test_wxo_mapper_resolve_credentials_rejects_empty() -> None:\\n    \\\"\\\"\\\"WXO mapper rejects empty api_key in provider_data.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    with pytest.raises(HTTPException) as exc_info:\\n        mapper.resolve_credentials(provider_data={\\\"api_key\\\": \\\"\\\"})\\n    assert exc_info.value.status_code == 422\\n    assert \\\"api_key\\\" in exc_info.value.detail\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        mapper.resolve_credentials(provider_data={\\\"api_key\\\": \\\"   \\\"})\\n    assert exc_info.value.status_code == 422\\n    assert \\\"api_key\\\" in exc_info.value.detail\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        mapper.resolve_credentials(provider_data={})\\n    assert exc_info.value.status_code == 422\\n    assert \\\"api_key\\\" in exc_info.value.detail\\n\\n\\ndef test_wxo_mapper_provider_account_create_assembles_model() -> None:\\n    from langflow.api.v1.schemas.deployments import DeploymentProviderAccountCreateRequest\\n\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentProviderAccountCreateRequest(\\n        name=\\\"test-account\\\",\\n        provider_key=\\\"watsonx-orchestrate\\\",\\n        provider_data={\\n            \\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com/instances/tenant-123\\\",\\n            \\\"tenant_id\\\": \\\"tenant-123\\\",\\n            \\\"api_key\\\": \\\"my-secret-key\\\",  # pragma: allowlist secret\\n        },\\n    )\\n    result = mapper.resolve_provider_account_create(payload=payload, user_id=uuid4())\\n    assert result.name == \\\"test-account\\\"\\n    assert result.provider_url == \\\"https://api.us-south.wxo.cloud.ibm.com/instances/tenant-123\\\"\\n    assert result.provider_tenant_id == \\\"tenant-123\\\"\\n    assert result.api_key == \\\"my-secret-key\\\"  # pragma: allowlist secret\\n\\n\\ndef test_wxo_mapper_provider_account_create_uses_url_tenant_fallback() -> None:\\n    from langflow.api.v1.schemas.deployments import DeploymentProviderAccountCreateRequest\\n\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentProviderAccountCreateRequest(\\n        name=\\\"test-account\\\",\\n        provider_key=\\\"watsonx-orchestrate\\\",\\n        provider_data={\\n            \\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com/instances/tenant-123\\\",\\n            \\\"api_key\\\": \\\"my-secret-key\\\",  # pragma: allowlist secret\\n        },\\n    )\\n\\n    result = mapper.resolve_provider_account_create(payload=payload, user_id=uuid4())\\n    assert result.provider_tenant_id == \\\"tenant-123\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# resolve_provider_account_update (WXO override)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _make_wxo_existing_account():\\n    \\\"\\\"\\\"Build a minimal fake existing WXO DeploymentProviderAccount.\\\"\\\"\\\"\\n    return SimpleNamespace(\\n        provider_url=\\\"https://api.us-south.wxo.cloud.ibm.com/instances/30000000-0000-0000-0000-000000000001\\\",\\n        provider_tenant_id=\\\"30000000-0000-0000-0000-000000000001\\\",\\n        provider_key=\\\"watsonx-orchestrate\\\",\\n    )\\n\\n\\ndef test_wxo_mapper_update_allows_name_changes_only_for_non_credential_fields() -> None:\\n    \\\"\\\"\\\"Provider-account update keeps URL/tenant immutable.\\\"\\\"\\\"\\n    from langflow.api.v1.schemas.deployments import DeploymentProviderAccountUpdateRequest\\n\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentProviderAccountUpdateRequest(name=\\\"renamed\\\")\\n    result = mapper.resolve_provider_account_update(\\n        payload=payload,\\n        existing_account=_make_wxo_existing_account(),\\n    )\\n    assert \\\"provider_tenant_id\\\" not in result\\n    assert \\\"provider_url\\\" not in result\\n    assert result[\\\"name\\\"] == \\\"renamed\\\"\\n\\n\\ndef test_wxo_mapper_resolve_verify_credentials_rejects_extra_fields() -> None:\\n    \\\"\\\"\\\"WXO slot uses extra='forbid' so unexpected credential fields are rejected.\\\"\\\"\\\"\\n    from langflow.services.adapters.deployment.watsonx_orchestrate.payloads import PAYLOAD_SCHEMAS\\n    from lfx.services.adapters.payload import AdapterPayloadValidationError\\n\\n    slot = PAYLOAD_SCHEMAS.verify_credentials\\n    assert slot is not None\\n    with pytest.raises(AdapterPayloadValidationError):\\n        slot.parse({\\\"api_key\\\": \\\"ok\\\", \\\"unexpected\\\": \\\"field\\\"})  # pragma: allowlist secret\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_create_preserves_env_var_source_in_connection_payloads() -> None:\\n    \\\"\\\"\\\"Connections with credentials should preserve source.\\n\\n    Preserve raw-vs-variable semantics all the way to the adapter payload.\\n    \\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    flow_id = uuid4()\\n    project_id = uuid4()\\n    payload = DeploymentCreateRequest(\\n        provider_id=uuid4(),\\n        description=\\\"\\\",\\n        type=\\\"agent\\\",\\n        provider_data={\\n            \\\"display_name\\\": \\\"deploy-with-vars\\\",\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [\\n                {\\n                    \\\"app_id\\\": \\\"app-new\\\",\\n                    \\\"credentials\\\": [\\n                        {\\n                            \\\"key\\\": \\\"RAW_TOKEN\\\",\\n                            \\\"value\\\": \\\"literal-secret\\\",\\n                            \\\"source\\\": \\\"raw\\\",\\n                        },  # pragma: allowlist secret\\n                        {\\\"key\\\": \\\"VAR_REF\\\", \\\"value\\\": \\\"MY_GLOBAL_VAR\\\", \\\"source\\\": \\\"variable\\\"},\\n                    ],\\n                }\\n            ],\\n            \\\"add_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"app_ids\\\": [\\\"app-new\\\"],\\n                }\\n            ],\\n        },\\n    )\\n    row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=flow_id,\\n        flow_name=\\\"Flow B\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[],\\n    )\\n\\n    resolved = await mapper.resolve_deployment_create(\\n        user_id=uuid4(),\\n        project_id=project_id,\\n        db=_FakeDb([row]),\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    conn_raw_payloads = provider_data[\\\"connections\\\"][\\\"raw_payloads\\\"]\\n    assert conn_raw_payloads is not None\\n    assert len(conn_raw_payloads) == 1\\n\\n    env_vars = conn_raw_payloads[0][\\\"environment_variables\\\"]\\n    assert env_vars[\\\"RAW_TOKEN\\\"][\\\"value\\\"] == \\\"literal-secret\\\"  # pragma: allowlist secret\\n    assert env_vars[\\\"RAW_TOKEN\\\"][\\\"source\\\"] == \\\"raw\\\"\\n    assert env_vars[\\\"VAR_REF\\\"][\\\"value\\\"] == \\\"MY_GLOBAL_VAR\\\"\\n    assert env_vars[\\\"VAR_REF\\\"][\\\"source\\\"] == \\\"variable\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Smart bind: reuse existing tool when attachment exists\\n# ---------------------------------------------------------------------------\\n\\n\\nclass _MultiQueryFakeDb:\\n    \\\"\\\"\\\"Fake DB that dispatches rows based on the queried table.\\n\\n    Routes ``flow_version_deployment_attachment`` queries to\\n    ``attachment_rows`` and everything else (flow artifact queries)\\n    to ``flow_rows``.  This avoids fragile call-order coupling.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, flow_rows, attachment_rows=None):\\n        self._flow_rows = flow_rows\\n        self._attachment_rows = attachment_rows if attachment_rows is not None else []\\n\\n    async def exec(self, statement):\\n        if \\\"flow_version_deployment_attachment\\\" in str(statement):\\n            return _FakeExecResult(self._attachment_rows)\\n        return _FakeExecResult(self._flow_rows)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_bind_reuses_existing_tool_when_attachment_exists() -> None:\\n    \\\"\\\"\\\"Bind reuses existing tool when flow_version already has an attachment.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    flow_id = uuid4()\\n    project_id = uuid4()\\n\\n    flow_row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_number=1,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=flow_id,\\n        flow_name=\\\"Flow A\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n        project_id=project_id,\\n    )\\n    attachment_row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        provider_snapshot_id=\\\"existing-tool-id\\\",\\n    )\\n\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"upsert_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"add_app_ids\\\": [\\\"app-one\\\"],\\n                    \\\"remove_app_ids\\\": [],\\n                }\\n            ],\\n        }\\n    )\\n\\n    db = _MultiQueryFakeDb(flow_rows=[flow_row], attachment_rows=[attachment_row])\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"operations\\\"][0][\\\"op\\\"] == \\\"bind\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"tool_id_with_ref\\\"][\\\"tool_id\\\"] == \\\"existing-tool-id\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"tool_id_with_ref\\\"][\\\"source_ref\\\"] == str(flow_version_id)\\n    assert provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"] is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_bind_creates_new_tool_when_no_attachment() -> None:\\n    \\\"\\\"\\\"When no attachment exists for a flow_version, bind should use name_of_raw.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    project_id = uuid4()\\n\\n    flow_row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_number=1,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=uuid4(),\\n        flow_name=\\\"Flow B\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n        project_id=project_id,\\n    )\\n\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"upsert_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"add_app_ids\\\": [\\\"app-one\\\"],\\n                    \\\"remove_app_ids\\\": [],\\n                }\\n            ],\\n        }\\n    )\\n\\n    db = _MultiQueryFakeDb(flow_rows=[flow_row], attachment_rows=[])\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    raw_payload = provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"][0]\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"name_of_raw\\\"] == raw_payload[\\\"provider_data\\\"][\\\"tool_name\\\"]\\n    assert raw_payload[\\\"provider_data\\\"][\\\"source_ref\\\"] == str(flow_version_id)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_bind_reuse_with_empty_app_ids_emits_attach_tool() -> None:\\n    \\\"\\\"\\\"Bind with empty app_ids for an existing tool should emit attach_tool.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    project_id = uuid4()\\n\\n    flow_row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_number=1,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=uuid4(),\\n        flow_name=\\\"Flow C\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n        project_id=project_id,\\n    )\\n    attachment_row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        provider_snapshot_id=\\\"existing-tool-id\\\",\\n    )\\n\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"upsert_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"add_app_ids\\\": [],\\n                    \\\"remove_app_ids\\\": [],\\n                }\\n            ],\\n        }\\n    )\\n\\n    db = _MultiQueryFakeDb(flow_rows=[flow_row], attachment_rows=[attachment_row])\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"operations\\\"][0][\\\"op\\\"] == \\\"attach_tool\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"existing-tool-id\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_upsert_flow_with_tool_display_name_emits_rename_for_existing_attachment() -> None:\\n    \\\"\\\"\\\"tool_display_name on upsert_flows should become rename_tool for existing attachments.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    project_id = uuid4()\\n\\n    flow_row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_number=1,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=uuid4(),\\n        flow_name=\\\"Flow C\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n        project_id=project_id,\\n    )\\n    attachment_row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        provider_snapshot_id=\\\"existing-tool-id\\\",\\n    )\\n\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"upsert_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"add_app_ids\\\": [],\\n                    \\\"remove_app_ids\\\": [],\\n                    \\\"tool_display_name\\\": \\\"My Better Tool\\\",\\n                }\\n            ],\\n        }\\n    )\\n\\n    db = _MultiQueryFakeDb(flow_rows=[flow_row], attachment_rows=[attachment_row])\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"operations\\\"][0][\\\"op\\\"] == \\\"attach_tool\\\"\\n    assert provider_data[\\\"operations\\\"][1][\\\"op\\\"] == \\\"rename_tool\\\"\\n    assert provider_data[\\\"operations\\\"][1][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"existing-tool-id\\\"\\n    assert provider_data[\\\"operations\\\"][1][\\\"tool_display_name\\\"] == \\\"My Better Tool\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_upsert_flow_with_add_remove_and_tool_display_name_emits_bind_unbind_rename() -> None:\\n    \\\"\\\"\\\"upsert_flows with add/remove + tool_display_name should emit bind, unbind, and rename.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    project_id = uuid4()\\n\\n    flow_row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_number=1,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=uuid4(),\\n        flow_name=\\\"Flow D\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n        project_id=project_id,\\n    )\\n    attachment_row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        provider_snapshot_id=\\\"existing-tool-id\\\",\\n    )\\n\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"upsert_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"add_app_ids\\\": [\\\"app-add-1\\\", \\\"app-add-2\\\"],\\n                    \\\"remove_app_ids\\\": [\\\"app-remove-1\\\"],\\n                    \\\"tool_display_name\\\": \\\"My Mixed Tool\\\",\\n                }\\n            ],\\n        }\\n    )\\n\\n    db = _MultiQueryFakeDb(flow_rows=[flow_row], attachment_rows=[attachment_row])\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"operations\\\"][0][\\\"op\\\"] == \\\"bind\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"tool_id_with_ref\\\"][\\\"tool_id\\\"] == \\\"existing-tool-id\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"app_ids\\\"] == [\\\"app-add-1\\\", \\\"app-add-2\\\"]\\n\\n    assert provider_data[\\\"operations\\\"][1][\\\"op\\\"] == \\\"unbind\\\"\\n    assert provider_data[\\\"operations\\\"][1][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"existing-tool-id\\\"\\n    assert provider_data[\\\"operations\\\"][1][\\\"app_ids\\\"] == [\\\"app-remove-1\\\"]\\n\\n    assert provider_data[\\\"operations\\\"][2][\\\"op\\\"] == \\\"rename_tool\\\"\\n    assert provider_data[\\\"operations\\\"][2][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"existing-tool-id\\\"\\n    assert provider_data[\\\"operations\\\"][2][\\\"tool_display_name\\\"] == \\\"My Mixed Tool\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_tool_display_name_rename_compatible_with_all_update_operation_families() -> None:\\n    \\\"\\\"\\\"tool_display_name rename should coexist with flow removals, tool upserts/removals, and spec updates.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id_upsert = uuid4()\\n    flow_version_id_remove = uuid4()\\n    project_id = uuid4()\\n\\n    flow_row = SimpleNamespace(\\n        flow_version_id=flow_version_id_upsert,\\n        flow_version_number=1,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=uuid4(),\\n        flow_name=\\\"Flow E\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n        project_id=project_id,\\n    )\\n    attachment_rows = [\\n        SimpleNamespace(\\n            flow_version_id=flow_version_id_upsert,\\n            provider_snapshot_id=\\\"existing-tool-upsert\\\",\\n        ),\\n        SimpleNamespace(\\n            flow_version_id=flow_version_id_remove,\\n            provider_snapshot_id=\\\"existing-tool-remove\\\",\\n        ),\\n    ]\\n\\n    payload = DeploymentUpdateRequest(\\n        description=\\\"updated-description\\\",\\n        provider_data={\\n            \\\"display_name\\\": \\\"updated-name\\\",\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"upsert_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id_upsert),\\n                    \\\"add_app_ids\\\": [\\\"app-add\\\"],\\n                    \\\"remove_app_ids\\\": [\\\"app-remove\\\"],\\n                    \\\"tool_display_name\\\": \\\"My Combined Tool\\\",\\n                }\\n            ],\\n            \\\"remove_flows\\\": [str(flow_version_id_remove)],\\n            \\\"upsert_tools\\\": [\\n                {\\n                    \\\"tool_id\\\": \\\"external-tool-upsert\\\",\\n                    \\\"add_app_ids\\\": [\\\"external-app-add\\\"],\\n                    \\\"remove_app_ids\\\": [],\\n                }\\n            ],\\n            \\\"remove_tools\\\": [\\\"external-tool-remove\\\"],\\n        },\\n    )\\n\\n    db = _MultiQueryFakeDb(flow_rows=[flow_row], attachment_rows=attachment_rows)\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert resolved.spec is not None\\n    assert \\\"name\\\" not in resolved.spec.model_fields_set\\n    assert resolved.spec.description == \\\"updated-description\\\"\\n    assert provider_data[\\\"display_name\\\"] == \\\"updated-name\\\"\\n    assert provider_data[\\\"llm\\\"] == TEST_WXO_LLM\\n    assert provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"] is None\\n\\n    ops = provider_data[\\\"operations\\\"]\\n    assert [op[\\\"op\\\"] for op in ops] == [\\\"bind\\\", \\\"unbind\\\", \\\"rename_tool\\\", \\\"remove_tool\\\", \\\"bind\\\", \\\"remove_tool\\\"]\\n\\n    assert ops[0][\\\"tool\\\"][\\\"tool_id_with_ref\\\"][\\\"tool_id\\\"] == \\\"existing-tool-upsert\\\"\\n    assert ops[0][\\\"app_ids\\\"] == [\\\"app-add\\\"]\\n\\n    assert ops[1][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"existing-tool-upsert\\\"\\n    assert ops[1][\\\"app_ids\\\"] == [\\\"app-remove\\\"]\\n\\n    assert ops[2][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"existing-tool-upsert\\\"\\n    assert ops[2][\\\"tool_display_name\\\"] == \\\"My Combined Tool\\\"\\n\\n    assert ops[3][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"existing-tool-remove\\\"\\n\\n    assert ops[4][\\\"tool\\\"][\\\"tool_id_with_ref\\\"][\\\"tool_id\\\"] == \\\"external-tool-upsert\\\"\\n    assert ops[4][\\\"app_ids\\\"] == [\\\"external-app-add\\\"]\\n\\n    assert ops[5][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"external-tool-remove\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_tool_display_name_override_generates_valid_technical_name() -> None:\\n    \\\"\\\"\\\"tool_display_name should not be treated as a caller-owned technical name.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n    project_id = uuid4()\\n\\n    flow_row = SimpleNamespace(\\n        flow_version_id=flow_version_id,\\n        flow_version_number=1,\\n        flow_version_data=_valid_wxo_flow_data(),\\n        flow_id=uuid4(),\\n        flow_name=\\\"123 bad flow\\\",\\n        flow_description=\\\"desc\\\",\\n        flow_tags=[\\\"tag\\\"],\\n        project_id=project_id,\\n    )\\n\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"upsert_flows\\\": [\\n                {\\n                    \\\"flow_version_id\\\": str(flow_version_id),\\n                    \\\"add_app_ids\\\": [\\\"app-one\\\"],\\n                    \\\"remove_app_ids\\\": [],\\n                    \\\"tool_display_name\\\": \\\"valid name\\\",\\n                }\\n            ],\\n        }\\n    )\\n\\n    db = _MultiQueryFakeDb(flow_rows=[flow_row], attachment_rows=[])\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"operations\\\"][0][\\\"op\\\"] == \\\"bind\\\"\\n    raw_tool_name = provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"name_of_raw\\\"]\\n    raw_payload = provider_data[\\\"tools\\\"][\\\"raw_payloads\\\"][0]\\n    assert raw_tool_name == raw_payload[\\\"provider_data\\\"][\\\"tool_name\\\"]\\n    assert raw_payload[\\\"provider_data\\\"][\\\"source_ref\\\"] == str(flow_version_id)\\n    assert raw_payload[\\\"provider_data\\\"][\\\"tool_name\\\"].startswith(\\\"langflow_valid_name_\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Tool-id-based operations\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_watsonx_api_payload_accepts_bind_tool_operation() -> None:\\n    \\\"\\\"\\\"bind_tool operation with app_ids is accepted.\\\"\\\"\\\"\\n    WatsonxApiDeploymentUpdatePayload.model_validate(\\n        {\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"upsert_tools\\\": [\\n                {\\n                    \\\"tool_id\\\": \\\"some-tool-id\\\",\\n                    \\\"add_app_ids\\\": [\\\"app-one\\\"],\\n                    \\\"remove_app_ids\\\": [],\\n                }\\n            ],\\n        }\\n    )\\n\\n\\ndef test_watsonx_api_payload_accepts_bind_tool_with_empty_app_ids() -> None:\\n    \\\"\\\"\\\"bind_tool with empty app_ids (attach-only) is accepted.\\\"\\\"\\\"\\n    WatsonxApiDeploymentUpdatePayload.model_validate(\\n        {\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"upsert_tools\\\": [\\n                {\\n                    \\\"tool_id\\\": \\\"some-tool-id\\\",\\n                    \\\"add_app_ids\\\": [],\\n                    \\\"remove_app_ids\\\": [],\\n                }\\n            ],\\n        }\\n    )\\n\\n\\ndef test_watsonx_api_payload_accepts_unbind_tool_operation() -> None:\\n    \\\"\\\"\\\"unbind_tool operation is accepted.\\\"\\\"\\\"\\n    WatsonxApiDeploymentUpdatePayload.model_validate(\\n        {\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"upsert_tools\\\": [\\n                {\\n                    \\\"tool_id\\\": \\\"some-tool-id\\\",\\n                    \\\"add_app_ids\\\": [],\\n                    \\\"remove_app_ids\\\": [\\\"app-one\\\"],\\n                }\\n            ],\\n        }\\n    )\\n\\n\\ndef test_watsonx_api_payload_accepts_remove_tool_by_id_operation() -> None:\\n    \\\"\\\"\\\"remove_tool_by_id operation is accepted.\\\"\\\"\\\"\\n    WatsonxApiDeploymentUpdatePayload.model_validate(\\n        {\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"remove_tools\\\": [\\\"some-tool-id\\\"],\\n        }\\n    )\\n\\n\\ndef test_watsonx_api_payload_rejects_conflicting_tool_id_operations() -> None:\\n    \\\"\\\"\\\"remove_tool_by_id + bind_tool for same tool_id is rejected.\\\"\\\"\\\"\\n    with pytest.raises(ValidationError, match=\\\"remove_tools cannot be combined\\\"):\\n        WatsonxApiDeploymentUpdatePayload.model_validate(\\n            {\\n                \\\"llm\\\": TEST_WXO_LLM,\\n                \\\"connections\\\": [],\\n                \\\"upsert_tools\\\": [\\n                    {\\n                        \\\"tool_id\\\": \\\"tid\\\",\\n                        \\\"add_app_ids\\\": [\\\"app-one\\\"],\\n                        \\\"remove_app_ids\\\": [],\\n                    },\\n                ],\\n                \\\"remove_tools\\\": [\\\"tid\\\"],\\n            }\\n        )\\n\\n\\ndef test_watsonx_api_payload_unbind_tool_rejects_connection_app_ids() -> None:\\n    \\\"\\\"\\\"unbind_tool referencing raw connections app_ids should be rejected.\\\"\\\"\\\"\\n    with pytest.raises(ValidationError, match=r\\\"must not reference connections app_ids\\\"):\\n        WatsonxApiDeploymentUpdatePayload.model_validate(\\n            {\\n                \\\"llm\\\": TEST_WXO_LLM,\\n                \\\"connections\\\": [{\\\"app_id\\\": \\\"app-new\\\"}],\\n                \\\"upsert_tools\\\": [\\n                    {\\n                        \\\"tool_id\\\": \\\"tid\\\",\\n                        \\\"add_app_ids\\\": [],\\n                        \\\"remove_app_ids\\\": [\\\"app-new\\\"],\\n                    },\\n                ],\\n            }\\n        )\\n\\n\\ndef test_watsonx_api_payload_rejects_duplicate_credential_keys() -> None:\\n    with pytest.raises(ValidationError, match=\\\"duplicate key values\\\"):\\n        WatsonxApiDeploymentUpdatePayload.model_validate(\\n            {\\n                \\\"llm\\\": TEST_WXO_LLM,\\n                \\\"connections\\\": [\\n                    {\\n                        \\\"app_id\\\": \\\"app-new\\\",\\n                        \\\"credentials\\\": [\\n                            {\\\"key\\\": \\\"TOKEN\\\", \\\"value\\\": \\\"secret-a\\\", \\\"source\\\": \\\"raw\\\"},  # pragma: allowlist secret\\n                            {\\\"key\\\": \\\"TOKEN\\\", \\\"value\\\": \\\"secret-b\\\", \\\"source\\\": \\\"raw\\\"},  # pragma: allowlist secret\\n                        ],\\n                    }\\n                ],\\n                \\\"upsert_tools\\\": [\\n                    {\\n                        \\\"tool_id\\\": \\\"tid\\\",\\n                        \\\"add_app_ids\\\": [\\\"app-new\\\"],\\n                        \\\"remove_app_ids\\\": [],\\n                    },\\n                ],\\n            }\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_translates_bind_tool_into_provider_operations() -> None:\\n    \\\"\\\"\\\"bind_tool should produce tool_id_with_ref bind operation.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"upsert_tools\\\": [\\n                {\\\"tool_id\\\": \\\"external-tool\\\", \\\"add_app_ids\\\": [\\\"app-one\\\"], \\\"remove_app_ids\\\": []},\\n            ],\\n        }\\n    )\\n    db = _FakeDb([])\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"operations\\\"][0][\\\"op\\\"] == \\\"bind\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"tool_id_with_ref\\\"][\\\"tool_id\\\"] == \\\"external-tool\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"tool_id_with_ref\\\"][\\\"source_ref\\\"] == \\\"external-tool\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_translates_unbind_tool_into_provider_operations() -> None:\\n    \\\"\\\"\\\"unbind_tool should produce unbind operation with tool_id as source_ref.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"connections\\\": [],\\n            \\\"upsert_tools\\\": [\\n                {\\\"tool_id\\\": \\\"external-tool\\\", \\\"add_app_ids\\\": [], \\\"remove_app_ids\\\": [\\\"app-one\\\"]},\\n            ],\\n        }\\n    )\\n    db = _FakeDb([])\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"operations\\\"][0][\\\"op\\\"] == \\\"unbind\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"external-tool\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"source_ref\\\"] == \\\"external-tool\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_watsonx_mapper_translates_remove_tool_by_id_into_provider_operations() -> None:\\n    \\\"\\\"\\\"remove_tool_by_id should produce remove_tool operation.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    payload = DeploymentUpdateRequest(\\n        provider_data={\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"remove_tools\\\": [\\\"external-tool\\\"],\\n        }\\n    )\\n    db = _FakeDb([])\\n\\n    resolved = await mapper.resolve_deployment_update(\\n        user_id=uuid4(),\\n        deployment_db_id=uuid4(),\\n        db=db,\\n        payload=payload,\\n    )\\n    provider_data = resolved.provider_data or {}\\n\\n    assert provider_data[\\\"operations\\\"][0][\\\"op\\\"] == \\\"remove_tool\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"tool_id\\\"] == \\\"external-tool\\\"\\n    assert provider_data[\\\"operations\\\"][0][\\\"tool\\\"][\\\"source_ref\\\"] == \\\"external-tool\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# tool_id in WatsonxApiCreatedTool response\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_watsonx_created_tool_includes_tool_id() -> None:\\n    \\\"\\\"\\\"WatsonxApiCreatedTool requires tool_id and non-null flow_version_id.\\\"\\\"\\\"\\n    from langflow.api.v1.mappers.deployments.watsonx_orchestrate.payloads import WatsonxApiCreatedTool\\n\\n    binding = WatsonxApiCreatedTool(\\n        flow_version_id=uuid4(),\\n        tool_id=\\\"tool-123\\\",\\n    )\\n    assert binding.tool_id == \\\"tool-123\\\"\\n    assert binding.flow_version_id is not None\\n\\n    with pytest.raises(ValidationError):\\n        WatsonxApiCreatedTool(tool_id=\\\"tool-456\\\")\\n\\n\\ndef test_watsonx_mapper_shapes_update_response_with_tool_id() -> None:\\n    \\\"\\\"\\\"shape_deployment_update_result should include tool_id in created_tools.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    timestamp = datetime.now(tz=timezone.utc)\\n    deployment_id = uuid4()\\n    provider_account_id = uuid4()\\n    flow_version_id = uuid4()\\n    deployment_row = SimpleNamespace(\\n        id=deployment_id,\\n        deployment_provider_account_id=provider_account_id,\\n        resource_key=\\\"agent-123\\\",\\n        display_name=\\\"WXO Deployment\\\",\\n        description=\\\"test\\\",\\n        deployment_type=DeploymentType.AGENT,\\n        created_at=timestamp,\\n        updated_at=timestamp,\\n    )\\n\\n    from langflow.services.adapters.deployment.watsonx_orchestrate.payloads import (\\n        PAYLOAD_SCHEMAS as WXO_SCHEMAS,\\n    )\\n\\n    result = DeploymentUpdateResult(\\n        id=\\\"agent-1\\\",\\n        provider_result=WXO_SCHEMAS.deployment_update_result.apply(\\n            WatsonxDeploymentUpdateResultData(\\n                name=\\\"agent_technical_name\\\",\\n                display_name=\\\"Provider Label\\\",\\n                created_app_ids=[],\\n                created_snapshot_bindings=[\\n                    {\\\"source_ref\\\": str(flow_version_id), \\\"tool_id\\\": \\\"tool-1\\\", \\\"created\\\": True},\\n                ],\\n            )\\n        ),\\n    )\\n\\n    response = mapper.shape_deployment_update_result(result, deployment_row, provider_key=\\\"watsonx-orchestrate\\\")\\n    assert response.provider_id == provider_account_id\\n    assert response.provider_key == \\\"watsonx-orchestrate\\\"\\n    assert response.resource_key == \\\"agent-123\\\"\\n    bindings = response.provider_data[\\\"created_tools\\\"]\\n    assert len(bindings) == 1\\n    assert bindings[0][\\\"tool_id\\\"] == \\\"tool-1\\\"\\n    assert bindings[0][\\\"flow_version_id\\\"] == str(flow_version_id)\\n\\n\\ndef test_watsonx_mapper_shapes_update_response_with_non_uuid_source_ref() -> None:\\n    \\\"\\\"\\\"Non-UUID source_ref in created_snapshot_bindings should fail.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    timestamp = datetime.now(tz=timezone.utc)\\n    provider_account_id = uuid4()\\n    deployment_row = SimpleNamespace(\\n        id=uuid4(),\\n        deployment_provider_account_id=provider_account_id,\\n        resource_key=\\\"agent-123\\\",\\n        display_name=\\\"WXO Deployment\\\",\\n        description=\\\"test\\\",\\n        deployment_type=DeploymentType.AGENT,\\n        created_at=timestamp,\\n        updated_at=timestamp,\\n    )\\n\\n    from langflow.services.adapters.deployment.watsonx_orchestrate.payloads import (\\n        PAYLOAD_SCHEMAS as WXO_SCHEMAS,\\n    )\\n\\n    result = DeploymentUpdateResult(\\n        id=\\\"agent-1\\\",\\n        provider_result=WXO_SCHEMAS.deployment_update_result.apply(\\n            WatsonxDeploymentUpdateResultData(\\n                name=\\\"agent_technical_name\\\",\\n                display_name=\\\"Provider Label\\\",\\n                created_app_ids=[],\\n                created_snapshot_bindings=[\\n                    {\\\"source_ref\\\": \\\"external-tool-id\\\", \\\"tool_id\\\": \\\"external-tool-id\\\", \\\"created\\\": True},\\n                ],\\n            )\\n        ),\\n    )\\n\\n    with pytest.raises(HTTPException) as exc:\\n        mapper.shape_deployment_update_result(result, deployment_row, provider_key=\\\"watsonx-orchestrate\\\")\\n    assert exc.value.status_code == 500\\n    assert \\\"non-UUID source_ref\\\" in exc.value.detail\\n\\n\\n# ---------------------------------------------------------------------------\\n# util_update_snapshot_bindings filters non-UUID source_refs\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_watsonx_mapper_update_snapshot_bindings_filters_non_uuid_source_refs() -> None:\\n    \\\"\\\"\\\"Non-UUID source_ref bindings are excluded from attachment reconciliation.\\\"\\\"\\\"\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    flow_version_id = uuid4()\\n\\n    from langflow.services.adapters.deployment.watsonx_orchestrate.payloads import (\\n        PAYLOAD_SCHEMAS as WXO_SCHEMAS,\\n    )\\n\\n    result = DeploymentUpdateResult(\\n        id=\\\"agent-1\\\",\\n        provider_result=WXO_SCHEMAS.deployment_update_result.apply(\\n            WatsonxDeploymentUpdateResultData(\\n                name=\\\"agent_technical_name\\\",\\n                display_name=\\\"Provider Label\\\",\\n                created_app_ids=[],\\n                added_snapshot_bindings=[\\n                    {\\\"source_ref\\\": str(flow_version_id), \\\"tool_id\\\": \\\"tool-fv-based\\\", \\\"created\\\": True},\\n                    {\\\"source_ref\\\": \\\"external-tool-id\\\", \\\"tool_id\\\": \\\"external-tool-id\\\", \\\"created\\\": False},\\n                ],\\n            )\\n        ),\\n    )\\n\\n    bindings = mapper.util_update_snapshot_bindings(result=result)\\n    assert len(bindings.snapshot_bindings) == 1\\n    assert bindings.snapshot_bindings[0].source_ref == str(flow_version_id)\\n    assert bindings.snapshot_bindings[0].snapshot_id == \\\"tool-fv-based\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Create payload: upsert_tools\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_watsonx_create_payload_accepts_bind_tool_operation() -> None:\\n    \\\"\\\"\\\"Create payload should accept upsert_tools items.\\\"\\\"\\\"\\n    WatsonxApiDeploymentCreatePayload.model_validate(\\n        {\\n            \\\"display_name\\\": \\\"Create Agent\\\",\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"upsert_tools\\\": [\\n                {\\\"tool_id\\\": \\\"existing-tool\\\", \\\"add_app_ids\\\": []},\\n            ],\\n        }\\n    )\\n\\n\\ndef test_watsonx_create_payload_bind_tool_without_prefix() -> None:\\n    \\\"\\\"\\\"upsert_tools on create accepts minimal payload.\\\"\\\"\\\"\\n    _payload = WatsonxApiDeploymentCreatePayload.model_validate(\\n        {\\n            \\\"display_name\\\": \\\"Create Agent\\\",\\n            \\\"llm\\\": TEST_WXO_LLM,\\n            \\\"upsert_tools\\\": [\\n                {\\\"tool_id\\\": \\\"existing-tool\\\", \\\"add_app_ids\\\": []},\\n            ],\\n        }\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_deployment_route_handlers.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cd619f081d1381e3141342d7a0d8c353b29c2cb18c9fbd24318a1e7d705d41e4\",\"content\":\"\\\"\\\"\\\"Route-handler-level tests for deployment endpoints.\\n\\nCovers the integration behaviour of the FastAPI route handlers:\\n- Rollback on commit failure (create / update)\\n- GET single-deployment synchronization (deployment-level and snapshot-level)\\n- Project-scoped flow-version validation (create / update)\\n- resolve_deployment_adapter edge cases\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom types import SimpleNamespace\\nfrom unittest.mock import ANY, AsyncMock, MagicMock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.api.v1.deployments import DeploymentTelemetryCtx\\nfrom langflow.api.v1.mappers.deployments.contracts import ProviderSnapshotBinding\\nfrom langflow.api.v1.mappers.deployments.watsonx_orchestrate import WatsonxOrchestrateDeploymentMapper\\nfrom langflow.api.v1.schemas.deployments import (\\n    DeploymentCreateRequest,\\n    DeploymentListItem,\\n    DeploymentLlmListResponse,\\n    DeploymentProviderAccountCreateRequest,\\n    DeploymentProviderAccountUpdateRequest,\\n    DeploymentUpdateRequest,\\n    SnapshotUpdateRequest,\\n)\\nfrom langflow.services.database.models.deployment.exceptions import DeploymentGuardError\\nfrom langflow.services.database.models.deployment_provider_account.schemas import DeploymentProviderKey\\nfrom lfx.services.adapters.deployment.exceptions import (\\n    AuthenticationError,\\n    DeploymentNotFoundError,\\n    ResourceConflictError,\\n    ServiceUnavailableError,\\n)\\nfrom lfx.services.adapters.deployment.schema import (\\n    ConfigListItem,\\n    ConfigListResult,\\n    DeploymentCreateResult,\\n    DeploymentGetResult,\\n    DeploymentListParams,\\n    DeploymentListResult,\\n    DeploymentType,\\n    DeploymentUpdateResult,\\n    ItemResult,\\n    SnapshotItem,\\n    SnapshotListResult,\\n)\\nfrom lfx.services.authorization import ResourceVisibilityScope\\n\\nROUTES_MODULE = \\\"langflow.api.v1.deployments\\\"\\nHELPERS_MODULE = \\\"langflow.api.v1.mappers.deployments.helpers\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Shared factories\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _fake_provider_account(\\n    *,\\n    provider_key: str = DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n    provider_url: str = \\\"https://api.us-south.wxo.cloud.ibm.com/instances/tenant-1\\\",\\n    api_key: str = \\\"encrypted-key\\\",\\n    provider_tenant_id: str | None = \\\"tenant-1\\\",\\n    user_id=None,\\n) -> SimpleNamespace:\\n    return SimpleNamespace(\\n        id=uuid4(),\\n        # ``user_id`` is read by ``list_deployment_configs`` to pick the\\n        # provider namespace for adapter calls; default to a random UUID\\n        # so tests that don't care about the owner still pass.\\n        user_id=user_id if user_id is not None else uuid4(),\\n        provider_key=provider_key,\\n        provider_url=provider_url,\\n        api_key=api_key,\\n        provider_tenant_id=provider_tenant_id,\\n    )\\n\\n\\ndef _fake_deployment_row(**overrides) -> SimpleNamespace:\\n    return SimpleNamespace(\\n        id=overrides.get(\\\"id\\\", uuid4()),\\n        # ``user_id`` and ``workspace_id`` are read by ensure_deployment_permission\\n        # on every guarded deployment handler \u2014 keep the fixture in sync with the\\n        # real Deployment model so tests don't trip the authz layer with\\n        # AttributeError. None values are valid (owner override skipped,\\n        # workspace domain falls back to \\\"*\\\").\\n        user_id=overrides.get(\\\"user_id\\\", uuid4()),\\n        workspace_id=overrides.get(\\\"workspace_id\\\"),\\n        resource_key=overrides.get(\\\"resource_key\\\", \\\"rk-1\\\"),\\n        display_name=overrides.get(\\\"display_name\\\", overrides.get(\\\"name\\\", \\\"test-deployment\\\")),\\n        description=overrides.get(\\\"description\\\"),\\n        deployment_type=overrides.get(\\\"deployment_type\\\", \\\"agent\\\"),\\n        deployment_provider_account_id=overrides.get(\\\"deployment_provider_account_id\\\", uuid4()),\\n        project_id=overrides.get(\\\"project_id\\\", uuid4()),\\n        created_at=overrides.get(\\\"created_at\\\"),\\n        updated_at=overrides.get(\\\"updated_at\\\"),\\n    )\\n\\n\\ndef _fake_user() -> SimpleNamespace:\\n    return SimpleNamespace(id=uuid4())\\n\\n\\ndef _fake_telemetry() -> DeploymentTelemetryCtx:\\n    return DeploymentTelemetryCtx()\\n\\n\\ndef _fake_attachment(*, provider_snapshot_id: str | None = None) -> SimpleNamespace:\\n    return SimpleNamespace(\\n        flow_version_id=uuid4(),\\n        provider_snapshot_id=provider_snapshot_id,\\n        deployment_id=uuid4(),\\n    )\\n\\n\\nclass _AsyncNoopSavepoint:\\n    async def __aenter__(self):\\n        return None\\n\\n    async def __aexit__(self, exc_type, exc, tb):\\n        return False\\n\\n\\n# ---------------------------------------------------------------------------\\n# create_deployment: rollback on commit failure\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestCreateDeploymentRollback:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.rollback_provider_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.attach_flow_versions\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_snapshot_map_for_create\\\", return_value={})\\n    @patch(f\\\"{ROUTES_MODULE}.create_deployment_db\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_project_id_for_deployment_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_rollback_called_on_commit_failure(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_resolve_project,\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_create_db,\\n        mock_resolve_snap,  # noqa: ARG002\\n        mock_attach,  # noqa: ARG002\\n        mock_rollback,\\n    ):\\n        \\\"\\\"\\\"When session.commit() fails, rollback_provider_create is called.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import create_deployment\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        create_result = DeploymentCreateResult(\\n            id=\\\"provider-dep-1\\\",\\n            type=DeploymentType.AGENT,\\n            provider_result={\\\"app_ids\\\": [\\\"cfg-1\\\"], \\\"tools_with_refs\\\": [{\\\"tool_id\\\": \\\"tool-1\\\", \\\"source_ref\\\": \\\"fv-1\\\"}]},\\n        )\\n        adapter.create.return_value = create_result\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        mapper.util_create_flow_version_ids.return_value = []\\n        mapper.util_existing_deployment_resource_key_for_create.return_value = None\\n        mapper.resolve_deployment_create = AsyncMock(return_value=MagicMock())\\n        mock_get_mapper.return_value = mapper\\n        mock_resolve_project.return_value = uuid4()\\n        mock_create_db.return_value = _fake_deployment_row()\\n\\n        session = AsyncMock()\\n        session.commit.side_effect = RuntimeError(\\\"DB commit failed\\\")\\n\\n        payload = MagicMock()\\n        payload.provider_id = pa.id\\n        payload.display_name = \\\"test\\\"\\n        payload.type = \\\"agent\\\"\\n        payload.description = None\\n\\n        with pytest.raises(RuntimeError, match=\\\"DB commit failed\\\"):\\n            await create_deployment(\\n                session=session, payload=payload, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        mock_rollback.assert_awaited_once()\\n        assert mock_rollback.call_args.kwargs[\\\"resource_id\\\"] == create_result.id\\n        assert mock_rollback.call_args.kwargs[\\\"provider_result\\\"] == create_result.provider_result\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.rollback_provider_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.attach_flow_versions\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_snapshot_map_for_create\\\", return_value={})\\n    @patch(f\\\"{ROUTES_MODULE}.create_deployment_db\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_project_id_for_deployment_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_no_rollback_on_success(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_resolve_project,\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_create_db,\\n        mock_resolve_snap,  # noqa: ARG002\\n        mock_attach,  # noqa: ARG002\\n        mock_rollback,\\n    ):\\n        \\\"\\\"\\\"On successful commit, rollback is NOT called.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import create_deployment\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        create_result = DeploymentCreateResult(id=\\\"provider-dep-1\\\", type=DeploymentType.AGENT)\\n        adapter.create.return_value = create_result\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        mapper.util_create_flow_version_ids.return_value = []\\n        mapper.util_existing_deployment_resource_key_for_create.return_value = None\\n        mapper.resolve_deployment_create = AsyncMock(return_value=MagicMock())\\n        mock_get_mapper.return_value = mapper\\n        mock_resolve_project.return_value = uuid4()\\n        dep_row = _fake_deployment_row()\\n        mock_create_db.return_value = dep_row\\n\\n        session = AsyncMock()\\n        session.commit.return_value = None\\n\\n        payload = MagicMock()\\n        payload.provider_id = pa.id\\n        payload.display_name = \\\"test\\\"\\n        payload.type = \\\"agent\\\"\\n        payload.description = None\\n\\n        mapper.shape_deployment_create_result.return_value = MagicMock()\\n        await create_deployment(\\n            session=session, payload=payload, current_user=_fake_user(), telemetry=_fake_telemetry()\\n        )\\n\\n        mock_rollback.assert_not_awaited()\\n\\n\\n# ---------------------------------------------------------------------------\\n# create_deployment: existing_agent_id behavior\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestCreateDeploymentExistingAgent:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.attach_flow_versions\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.create_deployment_db\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_project_id_for_deployment_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_by_resource_key\\\", new_callable=AsyncMock, return_value=None)\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_existing_agent_without_mutation_skips_provider_calls(\\n        self,\\n        mock_get_pa,\\n        mock_get_by_resource_key,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_resolve_project,\\n        mock_validate_fv,\\n        mock_create_db,\\n        mock_attach,\\n    ):\\n        from langflow.api.v1.deployments import create_deployment\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        adapter.get.return_value = DeploymentGetResult(\\n            id=\\\"existing-agent-1\\\",\\n            name=\\\"agent_technical_name\\\",\\n            type=\\\"agent\\\",\\n        )\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        mapper.util_existing_deployment_resource_key_for_create.return_value = \\\"existing-agent-1\\\"\\n        mapper.util_create_flow_version_ids.return_value = []\\n        mapper.util_create_result_from_existing_resource.return_value = DeploymentCreateResult(\\n            id=\\\"existing-agent-1\\\",\\n            type=DeploymentType.AGENT,\\n        )\\n        deployment_to_create = SimpleNamespace(resource_key=\\\"existing-agent-1\\\")\\n        mapper.resolve_deployment_model_from_existing_resource_for_create.return_value = deployment_to_create\\n        mock_get_mapper.return_value = mapper\\n        mock_resolve_project.return_value = uuid4()\\n        dep_row = _fake_deployment_row(resource_key=\\\"existing-agent-1\\\")\\n        mock_create_db.return_value = dep_row\\n\\n        session = AsyncMock()\\n        session.commit.return_value = None\\n\\n        payload = MagicMock()\\n        payload.provider_id = pa.id\\n        payload.display_name = \\\"existing\\\"\\n        payload.type = \\\"agent\\\"\\n        payload.description = None\\n\\n        mapper.shape_deployment_create_result.return_value = MagicMock()\\n        await create_deployment(\\n            session=session, payload=payload, current_user=_fake_user(), telemetry=_fake_telemetry()\\n        )\\n\\n        _ = (mock_get_by_resource_key, mock_validate_fv, mock_attach)\\n        adapter.create.assert_not_awaited()\\n        adapter.update.assert_not_awaited()\\n        adapter.get.assert_awaited_once_with(\\n            deployment_id=\\\"existing-agent-1\\\",\\n            deployment_type=payload.type,\\n            user_id=ANY,\\n            db=session,\\n        )\\n        mapper.util_create_result_from_existing_resource.assert_called_once_with(\\n            existing_resource=adapter.get.return_value,\\n        )\\n        assert mock_create_db.call_args.kwargs[\\\"deployment\\\"] is deployment_to_create\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.create_deployment_db\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_project_id_for_deployment_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_existing_agent_with_extra_provider_field_rejected_before_provider_lookup(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_resolve_project,\\n        mock_validate_fv,\\n        mock_create_db,\\n    ):\\n        from langflow.api.v1.deployments import create_deployment\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        mock_resolve_adapter.return_value = adapter\\n        mock_get_mapper.return_value = WatsonxOrchestrateDeploymentMapper()\\n        mock_resolve_project.return_value = uuid4()\\n        payload = DeploymentCreateRequest(\\n            provider_id=pa.id,\\n            type=\\\"agent\\\",\\n            provider_data={\\n                \\\"existing_agent_id\\\": \\\"21b2b5a4-ef72-4697-8731-132163669a46\\\",\\n                \\\"connections\\\": [],\\n            },\\n        )\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await create_deployment(\\n                session=AsyncMock(), payload=payload, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        assert exc_info.value.status_code == 422\\n        assert \\\"cannot include fields that update the wxO agent\\\" in str(exc_info.value.detail)\\n        adapter.get.assert_not_awaited()\\n        adapter.create.assert_not_awaited()\\n        adapter.update.assert_not_awaited()\\n        mock_validate_fv.assert_not_awaited()\\n        mock_create_db.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_flow_deploy_for_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_project_id_for_deployment_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.create_deployment_db\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_by_resource_key\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_existing_agent_conflict_when_resource_key_already_persisted(\\n        self,\\n        mock_get_pa,\\n        mock_get_by_resource_key,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_create_db,\\n        mock_resolve_project,\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_ensure_deploy,  # noqa: ARG002\\n    ):\\n        from langflow.api.v1.deployments import create_deployment\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        mock_get_by_resource_key.return_value = _fake_deployment_row(resource_key=\\\"existing-agent-1\\\")\\n        adapter = AsyncMock()\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        mapper.util_existing_deployment_resource_key_for_create.return_value = \\\"existing-agent-1\\\"\\n        mapper.util_create_flow_version_ids.return_value = []\\n        mock_get_mapper.return_value = mapper\\n        mock_resolve_project.return_value = uuid4()\\n\\n        payload = MagicMock()\\n        payload.provider_id = pa.id\\n        payload.display_name = \\\"existing\\\"\\n        payload.type = \\\"agent\\\"\\n        payload.description = None\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await create_deployment(\\n                session=AsyncMock(), payload=payload, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        assert exc_info.value.status_code == 409\\n        mock_create_db.assert_not_awaited()\\n        adapter.create.assert_not_awaited()\\n        adapter.update.assert_not_awaited()\\n        adapter.get.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_flow_deploy_for_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_deployment_permission\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_project_id_for_deployment_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_by_resource_key\\\", new_callable=AsyncMock, return_value=None)\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_create_denied_before_provider_get(\\n        self,\\n        mock_get_pa,\\n        mock_get_by_resource_key,  # noqa: ARG002\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_resolve_project,\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_ensure_create,\\n        mock_ensure_deploy,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"CREATE denial must not probe the provider (existing-resource onboarding).\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import create_deployment\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        mapper.util_existing_deployment_resource_key_for_create.return_value = \\\"existing-agent-1\\\"\\n        mapper.util_create_flow_version_ids.return_value = []\\n        mock_get_mapper.return_value = mapper\\n        mock_resolve_project.return_value = uuid4()\\n        mock_ensure_create.side_effect = HTTPException(status_code=403, detail=\\\"denied\\\")\\n\\n        payload = MagicMock()\\n        payload.provider_id = pa.id\\n        payload.display_name = \\\"existing\\\"\\n        payload.type = \\\"agent\\\"\\n        payload.description = None\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await create_deployment(\\n                session=AsyncMock(), payload=payload, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        assert exc_info.value.status_code == 403\\n        adapter.get.assert_not_awaited()\\n        adapter.create.assert_not_awaited()\\n        mapper.util_existing_deployment_resource_key_for_create.assert_not_called()\\n\\n\\n# ---------------------------------------------------------------------------\\n# list_deployments: provider passthrough mode\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestListDeploymentsLoadFromProvider:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_load_from_provider_bypasses_db_view(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_list_synced,\\n    ):\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        adapter.list.return_value = DeploymentListResult(\\n            deployments=[ItemResult(id=\\\"agent-1\\\", name=\\\"Agent 1\\\", type=\\\"agent\\\")]\\n        )\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        expected = MagicMock()\\n        resolved_params = DeploymentListParams(provider_params={\\\"environment\\\": \\\"draft\\\"})\\n        mapper.resolve_deployment_list_adapter_params = AsyncMock(return_value=resolved_params)\\n        mapper.shape_deployment_list_result.return_value = expected\\n        mapper.resolve_load_from_provider_deployment_list_params.return_value = {\\\"environment\\\": \\\"draft\\\"}\\n        mock_get_mapper.return_value = mapper\\n\\n        result = await list_deployments(\\n            provider_id=pa.id,\\n            session=AsyncMock(),\\n            current_user=_fake_user(),\\n            params=SimpleNamespace(page=2, size=50),\\n            deployment_type=None,\\n            load_from_provider=True,\\n            flow_version_ids=None,\\n        )\\n\\n        assert result is expected\\n        mock_list_synced.assert_not_awaited()\\n        # The route handler must forward the mapper-supplied provider_params\\n        # (e.g. WXO's `{\\\"environment\\\": \\\"draft\\\"}`) into resolve_deployment_list_adapter_params,\\n        # otherwise the load_from_provider filter is silently dropped.\\n        mapper.resolve_deployment_list_adapter_params.assert_awaited_once()\\n        resolve_kwargs = mapper.resolve_deployment_list_adapter_params.await_args.kwargs\\n        assert resolve_kwargs[\\\"provider_params\\\"] == {\\\"environment\\\": \\\"draft\\\"}\\n        adapter.list.assert_awaited_once()\\n        list_call_kwargs = adapter.list.await_args.kwargs\\n        assert list_call_kwargs[\\\"params\\\"] is resolved_params\\n        mapper.shape_deployment_list_result.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_load_from_provider_rejects_flow_version_filters(self):\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await list_deployments(\\n                provider_id=uuid4(),\\n                session=AsyncMock(),\\n                current_user=_fake_user(),\\n                params=SimpleNamespace(page=1, size=20),\\n                deployment_type=None,\\n                load_from_provider=True,\\n                flow_version_ids=[str(uuid4())],\\n            )\\n        assert exc_info.value.status_code == 422\\n\\n    @pytest.mark.asyncio\\n    async def test_load_from_provider_rejects_flow_ids_filter(self):\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await list_deployments(\\n                provider_id=uuid4(),\\n                session=AsyncMock(),\\n                current_user=_fake_user(),\\n                params=SimpleNamespace(page=1, size=20),\\n                deployment_type=None,\\n                load_from_provider=True,\\n                flow_ids=[str(uuid4())],\\n            )\\n        assert exc_info.value.status_code == 422\\n\\n\\n# ---------------------------------------------------------------------------\\n# list_deployments: flow_ids filter\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestListDeploymentsFlowIdsFilter:\\n    @pytest.mark.asyncio\\n    async def test_flow_ids_and_flow_version_ids_mutually_exclusive(self):\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await list_deployments(\\n                provider_id=uuid4(),\\n                session=AsyncMock(),\\n                current_user=_fake_user(),\\n                params=SimpleNamespace(page=1, size=20),\\n                deployment_type=None,\\n                load_from_provider=False,\\n                flow_version_ids=[str(uuid4())],\\n                flow_ids=[str(uuid4())],\\n            )\\n        assert exc_info.value.status_code == 422\\n        assert \\\"mutually exclusive\\\" in exc_info.value.detail\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.flow_version_ids_for_flows\\\", new_callable=AsyncMock, return_value=[])\\n    async def test_flow_ids_no_versions_returns_empty(self, mock_fv_for_flows):\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        result = await list_deployments(\\n            provider_id=uuid4(),\\n            session=AsyncMock(),\\n            current_user=_fake_user(),\\n            params=SimpleNamespace(page=1, size=20),\\n            deployment_type=None,\\n            load_from_provider=False,\\n            flow_ids=[str(uuid4())],\\n        )\\n\\n        assert result.deployments == []\\n        assert result.total == 0\\n        mock_fv_for_flows.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.flow_version_ids_for_flows\\\", new_callable=AsyncMock)\\n    async def test_flow_ids_resolves_to_flow_version_ids(\\n        self,\\n        mock_fv_for_flows,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_list_synced,\\n    ):\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        fv_id = uuid4()\\n        mock_fv_for_flows.return_value = [fv_id]\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        mock_resolve_adapter.return_value = AsyncMock()\\n\\n        mapper = MagicMock()\\n        mapper.shape_deployment_list_items.return_value = []\\n        mock_get_mapper.return_value = mapper\\n\\n        mock_list_synced.return_value = ([], 0, {})\\n\\n        await list_deployments(\\n            provider_id=pa.id,\\n            session=AsyncMock(),\\n            current_user=_fake_user(),\\n            params=SimpleNamespace(page=1, size=20),\\n            deployment_type=None,\\n            load_from_provider=False,\\n            flow_ids=[str(uuid4())],\\n        )\\n\\n        mock_list_synced.assert_awaited_once()\\n        call_kwargs = mock_list_synced.call_args.kwargs\\n        assert call_kwargs[\\\"flow_version_ids\\\"] == [fv_id]\\n\\n\\n# ---------------------------------------------------------------------------\\n# list_deployments: project_id filter\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestListDeploymentsProjectIdFilter:\\n    @pytest.mark.asyncio\\n    async def test_load_from_provider_rejects_project_id(self):\\n        \\\"\\\"\\\"project_id filtering is not supported when load_from_provider=true.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await list_deployments(\\n                provider_id=uuid4(),\\n                session=AsyncMock(),\\n                current_user=_fake_user(),\\n                params=SimpleNamespace(page=1, size=20),\\n                deployment_type=None,\\n                load_from_provider=True,\\n                project_id=uuid4(),\\n            )\\n        assert exc_info.value.status_code == 422\\n        assert \\\"project_id\\\" in exc_info.value.detail\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_project_id_threaded_to_synced(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_list_synced,\\n    ):\\n        \\\"\\\"\\\"When project_id is supplied it is forwarded to list_deployments_synced.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        mock_resolve_adapter.return_value = MagicMock()\\n        mapper = MagicMock()\\n        mapper.shape_deployment_list_items.return_value = []\\n        mock_get_mapper.return_value = mapper\\n        mock_list_synced.return_value = ([], 0, {})\\n\\n        pid = uuid4()\\n        await list_deployments(\\n            provider_id=pa.id,\\n            session=AsyncMock(),\\n            current_user=_fake_user(),\\n            params=SimpleNamespace(page=1, size=20),\\n            deployment_type=None,\\n            load_from_provider=False,\\n            project_id=pid,\\n        )\\n\\n        mock_list_synced.assert_awaited_once()\\n        assert mock_list_synced.call_args.kwargs[\\\"project_id\\\"] == pid\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_project_id_none_when_omitted(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_list_synced,\\n    ):\\n        \\\"\\\"\\\"When project_id is not supplied, None is forwarded (no filter).\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        mock_resolve_adapter.return_value = MagicMock()\\n        mapper = MagicMock()\\n        mapper.shape_deployment_list_items.return_value = []\\n        mock_get_mapper.return_value = mapper\\n        mock_list_synced.return_value = ([], 0, {})\\n\\n        await list_deployments(\\n            provider_id=pa.id,\\n            session=AsyncMock(),\\n            current_user=_fake_user(),\\n            params=SimpleNamespace(page=1, size=20),\\n            deployment_type=None,\\n            load_from_provider=False,\\n        )\\n\\n        mock_list_synced.assert_awaited_once()\\n        assert mock_list_synced.call_args.kwargs[\\\"project_id\\\"] is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# list_deployments: provider metadata sync\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestListDeploymentsMetadataSync:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{HELPERS_MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{HELPERS_MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{HELPERS_MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{HELPERS_MODULE}.update_deployment_metadata_batch\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{HELPERS_MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{HELPERS_MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_provider_description_passed_and_display_name_stays_in_provider_data(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_list_page,\\n        mock_fetch_keys,\\n        mock_update_metadata_batch,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,\\n    ):\\n        from langflow.api.v1.deployments import list_deployments\\n        from langflow.api.v1.mappers.deployments.base import BaseDeploymentMapper\\n\\n        class _Mapper(BaseDeploymentMapper):\\n            def extract_snapshot_bindings(self, provider_view):\\n                _ = provider_view\\n                return []\\n\\n            def extract_list_item_provider_data(self, provider_view):\\n                return {str(item.id): dict(item.provider_data) for item in provider_view.deployments}\\n\\n            def extract_metadata_for_list(self, provider_view):\\n                return {\\n                    str(item.id): {\\n                        \\\"display_name\\\": item.provider_data[\\\"display_name\\\"],\\n                        \\\"description\\\": item.provider_data[\\\"description\\\"],\\n                    }\\n                    for item in provider_view.deployments\\n                }\\n\\n            def shape_deployment_list_items(\\n                self,\\n                *,\\n                rows_with_counts,\\n                has_flow_filter=False,\\n                provider_key,\\n                provider_data_by_resource_key=None,\\n            ):\\n                _ = has_flow_filter\\n                return [\\n                    DeploymentListItem(\\n                        id=row.id,\\n                        provider_id=row.deployment_provider_account_id,\\n                        provider_key=provider_key,\\n                        resource_key=row.resource_key,\\n                        type=row.deployment_type,\\n                        description=row.description,\\n                        attached_count=attached_count,\\n                        provider_data=provider_data_by_resource_key[row.resource_key],\\n                    )\\n                    for row, attached_count, _matched in rows_with_counts\\n                ]\\n\\n        pa = _fake_provider_account()\\n        row = _fake_deployment_row(resource_key=\\\"agent-1\\\", description=\\\"old\\\")\\n        long_description = \\\"x\\\" * 501\\n        provider_view = SimpleNamespace(\\n            deployments=[\\n                SimpleNamespace(\\n                    id=\\\"agent-1\\\",\\n                    provider_data={\\n                        \\\"display_name\\\": \\\"Provider Label\\\",\\n                        \\\"description\\\": long_description,\\n                    },\\n                )\\n            ]\\n        )\\n\\n        def _apply_metadata_batch(*_args, **kwargs):\\n            update = kwargs[\\\"deployment_updates\\\"][0]\\n            update.langflow_db_row.display_name = update.display_name\\n            update.langflow_db_row.description = update.description\\n\\n        mock_get_pa.return_value = pa\\n        mock_resolve_adapter.return_value = AsyncMock()\\n        mock_get_mapper.return_value = _Mapper()\\n        mock_list_page.return_value = [(row, 0, [])]\\n        mock_fetch_keys.return_value = ({\\\"agent-1\\\"}, provider_view)\\n        mock_count_attachments.return_value = {row.id: 0}\\n        mock_update_metadata_batch.side_effect = _apply_metadata_batch\\n\\n        result = await list_deployments(\\n            provider_id=pa.id,\\n            session=MagicMock(begin_nested=MagicMock(return_value=_AsyncNoopSavepoint())),\\n            current_user=_fake_user(),\\n            params=SimpleNamespace(page=1, size=20),\\n            deployment_type=None,\\n        )\\n\\n        assert result.deployments[0].description == long_description\\n        assert result.deployments[0].provider_data[\\\"display_name\\\"] == \\\"Provider Label\\\"\\n        assert not hasattr(result.deployments[0], \\\"display_name\\\")\\n        mock_update_metadata_batch.assert_awaited_once()\\n        mock_delete_unbound.assert_awaited_once()\\n        mock_count.assert_awaited_once()\\n\\n\\n# ---------------------------------------------------------------------------\\n# list_deployments: cross-user shared listing (authz prefilter relaxes the gate)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestListDeploymentsSharedPrefilter:\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_deployment_permission\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.has_visible_deployment_for_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_shared_listing_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.visible_scope_prefilter\\\", new_callable=AsyncMock)\\n    async def test_cross_user_provider_permission_deny_is_masked_as_not_found(\\n        self,\\n        mock_prefilter,\\n        mock_get_owned_pa,\\n        mock_get_shared_pa,\\n        mock_has_visible_deployment,\\n        mock_ensure_permission,\\n        mock_resolve_adapter,\\n    ):\\n        \\\"\\\"\\\"A relaxed provider lookup must not reveal whether a foreign UUID exists.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        provider_account = _fake_provider_account()\\n        mock_prefilter.return_value = ResourceVisibilityScope(include_unassigned_workspace=True)\\n        mock_has_visible_deployment.return_value = True\\n        mock_get_shared_pa.return_value = provider_account\\n        mock_ensure_permission.side_effect = HTTPException(status_code=403, detail=\\\"Not authorized\\\")\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await list_deployments(\\n                provider_id=provider_account.id,\\n                session=MagicMock(),\\n                current_user=_fake_user(),\\n                params=SimpleNamespace(page=1, size=20),\\n                deployment_type=None,\\n            )\\n\\n        assert exc_info.value.status_code == 404\\n        assert exc_info.value.detail == \\\"Deployment provider account not found.\\\"\\n        mock_get_owned_pa.assert_not_awaited()\\n        mock_get_shared_pa.assert_awaited_once()\\n        mock_resolve_adapter.assert_not_called()\\n\\n    @patch(f\\\"{ROUTES_MODULE}.has_visible_deployment_for_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_shared_listing_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.visible_scope_prefilter\\\", new_callable=AsyncMock)\\n    async def test_unrelated_foreign_provider_never_reaches_unscoped_lookup(\\n        self,\\n        mock_prefilter,\\n        mock_get_owned_pa,\\n        mock_get_shared_pa,\\n        mock_has_visible_deployment,\\n    ):\\n        \\\"\\\"\\\"A coarse scope cannot reveal a provider with no deployment visible in that scope.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        provider_id = uuid4()\\n        mock_prefilter.return_value = ResourceVisibilityScope(workspace_ids=(uuid4(),))\\n        mock_has_visible_deployment.return_value = False\\n        mock_get_owned_pa.side_effect = HTTPException(\\n            status_code=404,\\n            detail=\\\"Deployment provider account not found.\\\",\\n        )\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await list_deployments(\\n                provider_id=provider_id,\\n                session=MagicMock(),\\n                current_user=_fake_user(),\\n                params=SimpleNamespace(page=1, size=20),\\n                deployment_type=None,\\n            )\\n\\n        assert exc_info.value.status_code == 404\\n        assert exc_info.value.detail == \\\"Deployment provider account not found.\\\"\\n        mock_has_visible_deployment.assert_awaited_once()\\n        mock_get_owned_pa.assert_awaited_once()\\n        mock_get_shared_pa.assert_not_awaited()\\n\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_shared_listing_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.has_visible_deployment_for_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.visible_scope_prefilter\\\", new_callable=AsyncMock)\\n    async def test_concrete_prefilter_relaxes_provider_gate_and_threads_visibility_scope(\\n        self,\\n        mock_prefilter,\\n        mock_has_visible_deployment,\\n        mock_get_owned_pa,\\n        mock_get_shared_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_synced,\\n    ):\\n        \\\"\\\"\\\"A concrete prefilter list resolves the provider account by id alone.\\n\\n        Regression for the cross-user shared-deployment listing gap: a caller\\n        granted READ on a deployment under *another user's* provider account\\n        used to 404 on the strict owner gate before the visibility union could\\n        surface the row. When ``visible_scope_prefilter`` returns a concrete\\n        scope, the strict owner gate must be skipped, the relaxed (id-only) gate\\n        must run, and the prefilter ids must be threaded into\\n        ``list_deployments_synced`` so the row is actually listed.\\n        \\\"\\\"\\\"\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        shared_id = uuid4()\\n        pa = _fake_provider_account()\\n        row = _fake_deployment_row(deployment_provider_account_id=pa.id, id=shared_id)\\n\\n        scope = ResourceVisibilityScope(resource_ids=(shared_id,))\\n        mock_prefilter.return_value = scope\\n        mock_has_visible_deployment.return_value = True\\n        mock_get_shared_pa.return_value = pa\\n        mock_resolve_adapter.return_value = AsyncMock()\\n        mapper = MagicMock()\\n        mapper.shape_deployment_list_items.return_value = [\\n            DeploymentListItem(\\n                id=row.id,\\n                provider_id=pa.id,\\n                provider_key=pa.provider_key,\\n                resource_key=row.resource_key,\\n                type=row.deployment_type,\\n                description=row.description,\\n                attached_count=0,\\n                provider_data={},\\n            )\\n        ]\\n        mock_get_mapper.return_value = mapper\\n        mock_synced.return_value = ([(row, 0, [])], 1, {})\\n        actor = _fake_user()\\n        result = await list_deployments(\\n            provider_id=pa.id,\\n            session=MagicMock(),\\n            current_user=actor,\\n            params=SimpleNamespace(page=1, size=20),\\n            deployment_type=None,\\n        )\\n\\n        # The strict owner gate must be skipped (it would 404 the cross-user\\n        # reader); the relaxed id-only gate resolves the foreign provider account.\\n        mock_get_owned_pa.assert_not_awaited()\\n        mock_get_shared_pa.assert_awaited_once()\\n        # The prefilter scope is threaded into the synced query so\\n        # the (owner \u2295 visible) union actually constrains the page + total.\\n        assert mock_synced.await_args.kwargs[\\\"visibility_scope\\\"] == scope\\n        # Shared listing: user_id is the actor; row_owner_id is the provider-account\\n        # owner (credentials + attachments) \u2014 otherwise Watsonx lookup fails.\\n        assert mock_synced.await_args.kwargs[\\\"user_id\\\"] == actor.id\\n        assert mock_synced.await_args.kwargs[\\\"row_owner_id\\\"] == pa.user_id\\n        assert result.total == 1\\n        assert result.deployments[0].id == shared_id\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_shared_listing_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.visible_scope_prefilter\\\", new_callable=AsyncMock)\\n    async def test_none_prefilter_keeps_strict_owner_gate(\\n        self,\\n        mock_prefilter,\\n        mock_get_owned_pa,\\n        mock_get_shared_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_synced,\\n    ):\\n        \\\"\\\"\\\"OSS / no-plugin path (prefilter declines \u2192 None) keeps the owner gate.\\n\\n        The relaxed id-only fetch must never run, and ``visibility_scope`` stays\\n        ``None`` so the listing remains owner-scoped exactly as before.\\n        \\\"\\\"\\\"\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        pa = _fake_provider_account()\\n\\n        mock_prefilter.return_value = None\\n        mock_get_owned_pa.return_value = pa\\n        mock_resolve_adapter.return_value = AsyncMock()\\n        mapper = MagicMock()\\n        mapper.shape_deployment_list_items.return_value = []\\n        mock_get_mapper.return_value = mapper\\n        mock_synced.return_value = ([], 0, {})\\n\\n        await list_deployments(\\n            provider_id=pa.id,\\n            session=MagicMock(),\\n            current_user=_fake_user(),\\n            params=SimpleNamespace(page=1, size=20),\\n            deployment_type=None,\\n        )\\n\\n        mock_get_owned_pa.assert_awaited_once()\\n        mock_get_shared_pa.assert_not_awaited()\\n        assert mock_synced.await_args.kwargs[\\\"visibility_scope\\\"] is None\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_shared_listing_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.visible_scope_prefilter\\\", new_callable=AsyncMock)\\n    async def test_empty_prefilter_keeps_strict_owner_gate(\\n        self,\\n        mock_prefilter,\\n        mock_get_owned_pa,\\n        mock_get_shared_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_synced,\\n    ):\\n        \\\"\\\"\\\"An empty prefilter list (plugin engaged, no extra visibility) keeps the gate.\\n\\n        An empty list means the caller has no cross-user visibility, so there is\\n        nothing to surface under a provider they don't own \u2014 the strict owner gate\\n        must stay (preserving its 404) rather than relax to the id-only fetch.\\n        \\\"\\\"\\\"\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        pa = _fake_provider_account()\\n\\n        scope = ResourceVisibilityScope()\\n        mock_prefilter.return_value = scope\\n        mock_get_owned_pa.return_value = pa\\n        mock_resolve_adapter.return_value = AsyncMock()\\n        mapper = MagicMock()\\n        mapper.shape_deployment_list_items.return_value = []\\n        mock_get_mapper.return_value = mapper\\n        mock_synced.return_value = ([], 0, {})\\n\\n        await list_deployments(\\n            provider_id=pa.id,\\n            session=MagicMock(),\\n            current_user=_fake_user(),\\n            params=SimpleNamespace(page=1, size=20),\\n            deployment_type=None,\\n        )\\n\\n        mock_get_owned_pa.assert_awaited_once()\\n        mock_get_shared_pa.assert_not_awaited()\\n        # The (empty) prefilter is still threaded through as visibility_scope so the\\n        # union stays authoritative and the per-row in-memory filter is skipped.\\n        assert mock_synced.await_args.kwargs[\\\"visibility_scope\\\"] == scope\\n\\n\\n# ---------------------------------------------------------------------------\\n# config/snapshot passthrough listing routes\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestConfigAndSnapshotListRoutes:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_list_configs_global_scope_uses_provider_id(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n    ):\\n        from langflow.api.v1.deployments import list_deployment_configs\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        adapter.list_configs.return_value = ConfigListResult(\\n            configs=[\\n                ConfigListItem(id=\\\"cfg-1\\\", name=\\\"Config 1\\\"),\\n                ConfigListItem(id=\\\"cfg-2\\\", name=\\\"Config 2\\\"),\\n            ],\\n            provider_result={},\\n        )\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        adapter_params = MagicMock()\\n        expected_response = MagicMock()\\n        mapper.resolve_config_list_adapter_params = AsyncMock(return_value=adapter_params)\\n        mapper.shape_config_list_result.return_value = expected_response\\n        mock_get_mapper.return_value = mapper\\n\\n        result = await list_deployment_configs(\\n            provider_id=pa.id,\\n            deployment_id=None,\\n            page=1,\\n            size=10,\\n            session=AsyncMock(),\\n            current_user=_fake_user(),\\n        )\\n\\n        assert result is expected_response\\n        mapper.resolve_config_list_adapter_params.assert_awaited_once_with(\\n            deployment_resource_key=None,\\n            provider_params=None,\\n        )\\n        call_params = adapter.list_configs.call_args.kwargs[\\\"params\\\"]\\n        assert call_params is adapter_params\\n        mapper.shape_config_list_result.assert_called_once_with(\\n            adapter.list_configs.return_value,\\n            page=1,\\n            size=10,\\n        )\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_row_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_list_snapshots_deployment_scope_resolves_provider_from_deployment(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_get_deployment,\\n    ):\\n        from langflow.api.v1.deployments import list_deployment_snapshots\\n\\n        pa = _fake_provider_account()\\n        deployment = _fake_deployment_row(resource_key=\\\"dep-key\\\")\\n        deployment.deployment_provider_account_id = pa.id\\n        mock_get_deployment.return_value = deployment\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        adapter.list_snapshots.return_value = SnapshotListResult(\\n            snapshots=[\\n                SnapshotItem(id=\\\"tool-1\\\", name=\\\"Tool 1\\\"),\\n                SnapshotItem(id=\\\"tool-2\\\", name=\\\"Tool 2\\\"),\\n            ],\\n            provider_result={\\\"deployment_id\\\": \\\"dep-1\\\"},\\n        )\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        adapter_params = MagicMock()\\n        expected_response = MagicMock()\\n        mapper.resolve_snapshot_list_adapter_params = AsyncMock(return_value=adapter_params)\\n        mapper.shape_snapshot_list_result.return_value = expected_response\\n        mock_get_mapper.return_value = mapper\\n\\n        owner_id = uuid4()\\n        actor = _fake_user()\\n        deployment.user_id = owner_id\\n        result = await list_deployment_snapshots(\\n            provider_id=pa.id,\\n            deployment_id=deployment.id,\\n            page=1,\\n            size=10,\\n            session=AsyncMock(),\\n            current_user=actor,\\n        )\\n\\n        assert result is expected_response\\n        mock_get_pa.assert_awaited_once_with(\\n            provider_id=pa.id,\\n            user_id=owner_id,\\n            db=ANY,\\n        )\\n        mapper.resolve_snapshot_list_adapter_params.assert_awaited_once_with(\\n            deployment_resource_key=\\\"dep-key\\\",\\n            provider_params=None,\\n        )\\n        call_params = adapter.list_snapshots.call_args.kwargs[\\\"params\\\"]\\n        assert call_params is adapter_params\\n        mapper.shape_snapshot_list_result.assert_called_once_with(\\n            adapter.list_snapshots.return_value,\\n            page=1,\\n            size=10,\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# update_snapshot\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestUpdateSnapshotRoute:\\n    @pytest.fixture(autouse=True)\\n    def _mock_flow_deploy(self):\\n        with patch(f\\\"{ROUTES_MODULE}.ensure_flow_deploy_for_version_ids\\\", new_callable=AsyncMock):\\n            yield\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.services.database.models.flow_version.crud.get_flow_version_entry\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.services.database.models.deployment.crud.get_deployment\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.update_flow_version_by_provider_snapshot_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_attachments_by_provider_snapshot_id\\\", new_callable=AsyncMock)\\n    async def test_updates_all_attachment_rows_for_snapshot(\\n        self,\\n        mock_list_attachments,\\n        mock_validate_fv,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_update_rows,\\n        mock_get_deployment_row,\\n        mock_get_flow_version,\\n    ):\\n        from langflow.api.v1.deployments import update_snapshot\\n\\n        user = _fake_user()\\n        flow_id = uuid4()\\n        target_flow_version_id = uuid4()\\n        # ``update_snapshot`` filters the candidate set to attachments owned\\n        # by the actor when share-aware fetch is off. Pin the owner to the\\n        # actor's id so the OSS pass-through path keeps the row.\\n        deployment = _fake_deployment_row(\\n            user_id=user.id,\\n            deployment_provider_account_id=uuid4(),\\n        )\\n        attachment = SimpleNamespace(\\n            flow_version_id=uuid4(),\\n            deployment_id=deployment.id,\\n            provider_snapshot_id=\\\"tool-1\\\",\\n            user_id=user.id,\\n        )\\n        provider_account = _fake_provider_account()\\n        provider_account.id = deployment.deployment_provider_account_id\\n\\n        mock_list_attachments.return_value = [attachment]\\n        mock_get_deployment_row.return_value = deployment\\n        mock_get_flow_version.return_value = SimpleNamespace(id=target_flow_version_id, flow_id=flow_id, data={})\\n        mock_get_pa.return_value = provider_account\\n        adapter = AsyncMock()\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        mapper.resolve_snapshot_update_artifact.return_value = {\\\"artifact\\\": \\\"payload\\\"}\\n        mock_get_mapper.return_value = mapper\\n        mock_update_rows.return_value = 2\\n\\n        session = AsyncMock()\\n        session.get.return_value = SimpleNamespace(id=flow_id)\\n\\n        response = await update_snapshot(\\n            provider_snapshot_id=\\\" tool-1 \\\",\\n            body=SnapshotUpdateRequest(flow_version_id=target_flow_version_id),\\n            session=session,\\n            current_user=user,\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        assert response.flow_version_id == target_flow_version_id\\n        assert response.provider_snapshot_id == \\\"tool-1\\\"\\n        mock_list_attachments.assert_awaited_once_with(\\n            session,\\n            provider_snapshot_id=\\\"tool-1\\\",\\n        )\\n        mock_validate_fv.assert_awaited_once_with(\\n            flow_version_ids=[target_flow_version_id],\\n            user_id=user.id,\\n            project_id=deployment.project_id,\\n            db=session,\\n        )\\n        mock_update_rows.assert_awaited_once_with(\\n            session,\\n            user_id=user.id,\\n            provider_snapshot_id=\\\"tool-1\\\",\\n            flow_version_id=target_flow_version_id,\\n        )\\n        session.commit.assert_awaited_once()\\n        session.rollback.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.services.database.models.flow_version.crud.get_flow_version_entry\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.services.database.models.deployment.crud.get_deployment\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.update_flow_version_by_provider_snapshot_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_attachments_by_provider_snapshot_id\\\", new_callable=AsyncMock)\\n    async def test_commit_failure_attempts_provider_compensation(\\n        self,\\n        mock_list_attachments,\\n        mock_validate_fv,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_update_rows,\\n        mock_get_deployment_row,\\n        mock_get_flow_version,\\n    ):\\n        from langflow.api.v1.deployments import update_snapshot\\n\\n        user = _fake_user()\\n        flow_id = uuid4()\\n        previous_flow_version_id = uuid4()\\n        target_flow_version_id = uuid4()\\n        deployment = _fake_deployment_row(\\n            user_id=user.id,\\n            deployment_provider_account_id=uuid4(),\\n        )\\n        attachment = SimpleNamespace(\\n            flow_version_id=previous_flow_version_id,\\n            deployment_id=deployment.id,\\n            provider_snapshot_id=\\\"tool-1\\\",\\n            user_id=user.id,\\n        )\\n        provider_account = _fake_provider_account()\\n        provider_account.id = deployment.deployment_provider_account_id\\n\\n        target_version = SimpleNamespace(id=target_flow_version_id, flow_id=flow_id, data={\\\"nodes\\\": []})\\n        previous_version = SimpleNamespace(id=previous_flow_version_id, flow_id=flow_id, data={\\\"nodes\\\": []})\\n        mock_get_flow_version.side_effect = [target_version, previous_version]\\n        mock_list_attachments.return_value = [attachment]\\n        mock_get_deployment_row.return_value = deployment\\n        mock_get_pa.return_value = provider_account\\n        adapter = AsyncMock()\\n        adapter.update_snapshot.return_value = None\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        mapper.resolve_snapshot_update_artifact.side_effect = [{\\\"artifact\\\": \\\"new\\\"}, {\\\"artifact\\\": \\\"previous\\\"}]\\n        mock_get_mapper.return_value = mapper\\n        mock_update_rows.return_value = 2\\n\\n        session = AsyncMock()\\n        session.get.return_value = SimpleNamespace(id=flow_id)\\n        session.commit.side_effect = RuntimeError(\\\"commit failed\\\")\\n\\n        with pytest.raises(RuntimeError, match=\\\"commit failed\\\"):\\n            await update_snapshot(\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                body=SnapshotUpdateRequest(flow_version_id=target_flow_version_id),\\n                session=session,\\n                current_user=user,\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n        session.commit.assert_awaited_once()\\n        session.rollback.assert_awaited_once()\\n        mock_validate_fv.assert_awaited_once_with(\\n            flow_version_ids=[target_flow_version_id],\\n            user_id=user.id,\\n            project_id=deployment.project_id,\\n            db=session,\\n        )\\n        assert adapter.update_snapshot.await_count == 2\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.services.database.models.flow_version.crud.get_flow_version_entry\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.services.database.models.deployment.crud.get_deployment\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_attachments_by_provider_snapshot_id\\\", new_callable=AsyncMock)\\n    async def test_project_scope_validation_runs_before_provider_update(\\n        self,\\n        mock_list_attachments,\\n        mock_validate_fv,\\n        mock_get_pa,\\n        mock_resolve_adapter,\\n        mock_get_deployment_row,\\n        mock_get_flow_version,\\n    ):\\n        from langflow.api.v1.deployments import update_snapshot\\n\\n        user = _fake_user()\\n        target_flow_version_id = uuid4()\\n        attachment = SimpleNamespace(\\n            flow_version_id=uuid4(),\\n            deployment_id=uuid4(),\\n            provider_snapshot_id=\\\"tool-1\\\",\\n            user_id=user.id,\\n        )\\n        deployment = _fake_deployment_row(id=attachment.deployment_id, user_id=user.id)\\n        mock_list_attachments.return_value = [attachment]\\n        mock_get_deployment_row.return_value = deployment\\n        mock_get_flow_version.return_value = SimpleNamespace(id=target_flow_version_id, flow_id=uuid4(), data={})\\n        mock_validate_fv.side_effect = HTTPException(status_code=404, detail=\\\"out of project\\\")\\n\\n        session = AsyncMock()\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await update_snapshot(\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                body=SnapshotUpdateRequest(flow_version_id=target_flow_version_id),\\n                session=session,\\n                current_user=user,\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n        assert exc_info.value.status_code == 404\\n        mock_validate_fv.assert_awaited_once_with(\\n            flow_version_ids=[target_flow_version_id],\\n            user_id=user.id,\\n            project_id=deployment.project_id,\\n            db=session,\\n        )\\n        mock_get_pa.assert_not_awaited()\\n        mock_resolve_adapter.assert_not_called()\\n\\n    # ----- Share-aware / owner-group branches ----- #\\n    #\\n    # ``update_snapshot`` now groups candidate attachments by owner,\\n    # authorizes each owner's full set, and decides between 404 / success /\\n    # 409 based on how many owner groups authorize. These tests pin each\\n    # branch so a regression in the authorization walk surfaces here.\\n\\n    @staticmethod\\n    def _share_aware_authz() -> MagicMock:\\n        \\\"\\\"\\\"Stub authorization service that opts into cross-user fetch.\\\"\\\"\\\"\\n        stub = MagicMock()\\n        stub.supports_cross_user_fetch = AsyncMock(return_value=True)\\n        stub.is_enabled = AsyncMock(return_value=True)\\n        return stub\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_deployment_permission\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_authorization_service\\\")\\n    @patch(\\\"langflow.services.database.models.deployment.crud.get_deployment\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_attachments_by_provider_snapshot_id\\\", new_callable=AsyncMock)\\n    async def test_share_aware_zero_authorized_groups_returns_404(\\n        self,\\n        mock_list_attachments,\\n        mock_get_deployment_row,\\n        mock_get_authz,\\n        mock_ensure_perm,\\n    ):\\n        \\\"\\\"\\\"Share-aware: candidates from two owners; neither authorizes \u2192 404 (no info leak).\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_snapshot\\n\\n        user = _fake_user()\\n        alice_id = uuid4()\\n        bob_id = uuid4()\\n        alice_dep = _fake_deployment_row(user_id=alice_id)\\n        bob_dep = _fake_deployment_row(user_id=bob_id)\\n        mock_list_attachments.return_value = [\\n            SimpleNamespace(\\n                flow_version_id=uuid4(),\\n                deployment_id=alice_dep.id,\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                user_id=alice_id,\\n            ),\\n            SimpleNamespace(\\n                flow_version_id=uuid4(),\\n                deployment_id=bob_dep.id,\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                user_id=bob_id,\\n            ),\\n        ]\\n        deps_by_id = {alice_dep.id: alice_dep, bob_dep.id: bob_dep}\\n\\n        async def _resolve(_session, *, user_id, deployment_id):  # noqa: ARG001\\n            return deps_by_id.get(deployment_id)\\n\\n        mock_get_deployment_row.side_effect = _resolve\\n        mock_get_authz.return_value = self._share_aware_authz()\\n        # Every authorization attempt denies \u2014 every owner group fails.\\n        mock_ensure_perm.side_effect = HTTPException(status_code=403, detail=\\\"denied\\\")\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await update_snapshot(\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                body=SnapshotUpdateRequest(flow_version_id=uuid4()),\\n                session=AsyncMock(),\\n                current_user=user,\\n                telemetry=_fake_telemetry(),\\n            )\\n        assert exc_info.value.status_code == 404\\n        # UUID-privacy: the response must NOT distinguish \\\"no such snapshot\\\"\\n        # from \\\"snapshot exists but owners other than you have it\\\".\\n        assert \\\"tool-1\\\" in exc_info.value.detail\\n        assert \\\"owner\\\" not in exc_info.value.detail.lower()\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.services.database.models.flow_version.crud.get_flow_version_entry\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.update_flow_version_by_provider_snapshot_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_deployment_permission\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_authorization_service\\\")\\n    @patch(\\\"langflow.services.database.models.deployment.crud.get_deployment\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_attachments_by_provider_snapshot_id\\\", new_callable=AsyncMock)\\n    async def test_share_aware_one_authorized_group_ignores_unauthorized_collision(\\n        self,\\n        mock_list_attachments,\\n        mock_get_deployment_row,\\n        mock_get_authz,\\n        mock_ensure_perm,\\n        mock_validate_fv,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_update_rows,\\n        mock_get_flow_version,\\n    ):\\n        \\\"\\\"\\\"An unrelated owner with the same snapshot id must NOT block a legitimate share-holder.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_snapshot\\n\\n        user = _fake_user()\\n        target_flow_version_id = uuid4()\\n        # Alice \u2014 the actor has WRITE on her deployment via a share grant.\\n        alice_id = uuid4()\\n        alice_dep = _fake_deployment_row(user_id=alice_id)\\n        # Bob \u2014 also has snapshot id \\\"tool-1\\\", but actor has no access.\\n        bob_id = uuid4()\\n        bob_dep = _fake_deployment_row(user_id=bob_id)\\n\\n        mock_list_attachments.return_value = [\\n            SimpleNamespace(\\n                flow_version_id=uuid4(),\\n                deployment_id=alice_dep.id,\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                user_id=alice_id,\\n            ),\\n            SimpleNamespace(\\n                flow_version_id=uuid4(),\\n                deployment_id=bob_dep.id,\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                user_id=bob_id,\\n            ),\\n        ]\\n        deps_by_id = {alice_dep.id: alice_dep, bob_dep.id: bob_dep}\\n\\n        async def _resolve(_session, *, user_id, deployment_id):  # noqa: ARG001\\n            return deps_by_id.get(deployment_id)\\n\\n        mock_get_deployment_row.side_effect = _resolve\\n        mock_get_authz.return_value = self._share_aware_authz()\\n\\n        # Allow only Alice's deployment; deny Bob's.\\n        async def _maybe_authorize(*_args, **kwargs):\\n            if kwargs[\\\"deployment_user_id\\\"] == alice_id:\\n                return\\n            raise HTTPException(status_code=403, detail=\\\"denied\\\")\\n\\n        mock_ensure_perm.side_effect = _maybe_authorize\\n\\n        provider_account = _fake_provider_account(user_id=alice_id)\\n        provider_account.id = alice_dep.deployment_provider_account_id\\n        mock_get_pa.return_value = provider_account\\n        adapter = AsyncMock()\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        mapper.resolve_snapshot_update_artifact.return_value = {\\\"artifact\\\": \\\"payload\\\"}\\n        mock_get_mapper.return_value = mapper\\n        mock_update_rows.return_value = 1\\n        mock_get_flow_version.return_value = SimpleNamespace(id=target_flow_version_id, flow_id=uuid4(), data={})\\n        session = AsyncMock()\\n        session.get.return_value = SimpleNamespace(id=uuid4())\\n\\n        response = await update_snapshot(\\n            provider_snapshot_id=\\\"tool-1\\\",\\n            body=SnapshotUpdateRequest(flow_version_id=target_flow_version_id),\\n            session=session,\\n            current_user=user,\\n            telemetry=_fake_telemetry(),\\n        )\\n        assert response.provider_snapshot_id == \\\"tool-1\\\"\\n        # Mutation must run inside the OWNER's namespace (Alice's), not the actor's.\\n        mock_update_rows.assert_awaited_once_with(\\n            session,\\n            user_id=alice_id,\\n            provider_snapshot_id=\\\"tool-1\\\",\\n            flow_version_id=target_flow_version_id,\\n        )\\n        mock_validate_fv.assert_awaited_once_with(\\n            flow_version_ids=[target_flow_version_id],\\n            user_id=alice_id,\\n            project_id=alice_dep.project_id,\\n            db=session,\\n        )\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_deployment_permission\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_authorization_service\\\")\\n    @patch(\\\"langflow.services.database.models.deployment.crud.get_deployment\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_attachments_by_provider_snapshot_id\\\", new_callable=AsyncMock)\\n    async def test_share_aware_multiple_authorized_groups_returns_409(\\n        self,\\n        mock_list_attachments,\\n        mock_get_deployment_row,\\n        mock_get_authz,\\n        mock_ensure_perm,\\n    ):\\n        \\\"\\\"\\\"Actor has WRITE on two unrelated owners' snapshots \u2014 route must refuse with 409.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_snapshot\\n\\n        user = _fake_user()\\n        alice_id = uuid4()\\n        carol_id = uuid4()\\n        alice_dep = _fake_deployment_row(user_id=alice_id)\\n        carol_dep = _fake_deployment_row(user_id=carol_id)\\n        mock_list_attachments.return_value = [\\n            SimpleNamespace(\\n                flow_version_id=uuid4(),\\n                deployment_id=alice_dep.id,\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                user_id=alice_id,\\n            ),\\n            SimpleNamespace(\\n                flow_version_id=uuid4(),\\n                deployment_id=carol_dep.id,\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                user_id=carol_id,\\n            ),\\n        ]\\n        deps_by_id = {alice_dep.id: alice_dep, carol_dep.id: carol_dep}\\n\\n        async def _resolve(_session, *, user_id, deployment_id):  # noqa: ARG001\\n            return deps_by_id.get(deployment_id)\\n\\n        mock_get_deployment_row.side_effect = _resolve\\n        mock_get_authz.return_value = self._share_aware_authz()\\n        # Allow both groups.\\n        mock_ensure_perm.return_value = None\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await update_snapshot(\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                body=SnapshotUpdateRequest(flow_version_id=uuid4()),\\n                session=AsyncMock(),\\n                current_user=user,\\n                telemetry=_fake_telemetry(),\\n            )\\n        assert exc_info.value.status_code == 409\\n        assert \\\"multiple owners\\\" in exc_info.value.detail.lower()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_deployment_permission\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_authorization_service\\\")\\n    @patch(\\\"langflow.services.database.models.deployment.crud.get_deployment\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_attachments_by_provider_snapshot_id\\\", new_callable=AsyncMock)\\n    async def test_one_owner_spanning_multiple_provider_accounts_returns_409(\\n        self,\\n        mock_list_attachments,\\n        mock_get_deployment_row,\\n        mock_get_authz,\\n        mock_ensure_perm,\\n    ):\\n        \\\"\\\"\\\"Single owner across two provider accounts must 409.\\n\\n        The external snapshot update can only run against one adapter, but the DB\\n        rewrite would otherwise corrupt rows tied to the second provider account.\\n        \\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_snapshot\\n\\n        user = _fake_user()\\n        owner_id = user.id  # actor is the owner (OSS-path-compatible)\\n        provider_a = uuid4()\\n        provider_b = uuid4()\\n        dep_a = _fake_deployment_row(user_id=owner_id, deployment_provider_account_id=provider_a)\\n        dep_b = _fake_deployment_row(user_id=owner_id, deployment_provider_account_id=provider_b)\\n        mock_list_attachments.return_value = [\\n            SimpleNamespace(\\n                flow_version_id=uuid4(),\\n                deployment_id=dep_a.id,\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                user_id=owner_id,\\n            ),\\n            SimpleNamespace(\\n                flow_version_id=uuid4(),\\n                deployment_id=dep_b.id,\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                user_id=owner_id,\\n            ),\\n        ]\\n        deps_by_id = {dep_a.id: dep_a, dep_b.id: dep_b}\\n\\n        async def _resolve(_session, *, user_id, deployment_id):  # noqa: ARG001\\n            return deps_by_id.get(deployment_id)\\n\\n        mock_get_deployment_row.side_effect = _resolve\\n        # Either share-aware or OSS works; the multi-provider check fires\\n        # after the owner group is selected so the result is the same.\\n        mock_get_authz.return_value = self._share_aware_authz()\\n        mock_ensure_perm.return_value = None\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await update_snapshot(\\n                provider_snapshot_id=\\\"tool-1\\\",\\n                body=SnapshotUpdateRequest(flow_version_id=uuid4()),\\n                session=AsyncMock(),\\n                current_user=user,\\n                telemetry=_fake_telemetry(),\\n            )\\n        assert exc_info.value.status_code == 409\\n        assert \\\"provider accounts\\\" in exc_info.value.detail.lower()\\n\\n\\n# ---------------------------------------------------------------------------\\n# list_deployment_flow_versions\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestListDeploymentFlowVersionsRoute:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployment_flow_versions_synced\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_returns_paginated_flow_versions(\\n        self,\\n        mock_resolve,\\n        mock_list_flow_versions_synced,\\n    ):\\n        from langflow.api.v1.deployments import list_deployment_flow_versions\\n\\n        deployment_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        rows = [(SimpleNamespace(provider_snapshot_id=\\\"tool-1\\\", created_at=None), SimpleNamespace())]\\n        snapshot_result = SnapshotListResult(\\n            snapshots=[\\n                SnapshotItem(\\n                    id=\\\"tool-1\\\",\\n                    name=\\\"Tool 1\\\",\\n                    provider_data={\\\"connections\\\": {\\\"cfg-1\\\": \\\"conn-1\\\"}},\\n                )\\n            ]\\n        )\\n        mock_resolve.return_value = (deployment_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        mock_list_flow_versions_synced.return_value = (rows, 7, snapshot_result)\\n        mapper.shape_flow_version_list_result.return_value = SimpleNamespace(\\n            page=2,\\n            size=5,\\n            total=7,\\n            flow_versions=[\\n                SimpleNamespace(\\n                    provider_snapshot_id=\\\"tool-1\\\",\\n                    provider_data={\\\"app_ids\\\": [\\\"cfg-1\\\"]},\\n                )\\n            ],\\n        )\\n\\n        flow_id = uuid4()\\n        response = await list_deployment_flow_versions(\\n            deployment_id=deployment_row.id,\\n            session=AsyncMock(),\\n            current_user=_fake_user(),\\n            page=2,\\n            size=5,\\n            flow_ids=[flow_id],\\n        )\\n\\n        assert response.page == 2\\n        assert response.size == 5\\n        assert response.total == 7\\n        assert len(response.flow_versions) == 1\\n        assert response.flow_versions[0].provider_snapshot_id == \\\"tool-1\\\"\\n        assert response.flow_versions[0].provider_data == {\\\"app_ids\\\": [\\\"cfg-1\\\"]}\\n\\n        mock_list_flow_versions_synced.assert_awaited_once()\\n        helper_kwargs = mock_list_flow_versions_synced.call_args.kwargs\\n        assert helper_kwargs[\\\"provider_id\\\"] == deployment_row.deployment_provider_account_id\\n        assert helper_kwargs[\\\"deployment_id\\\"] == deployment_row.id\\n        assert helper_kwargs[\\\"page\\\"] == 2\\n        assert helper_kwargs[\\\"size\\\"] == 5\\n        assert helper_kwargs[\\\"flow_ids\\\"] == [flow_id]\\n        mapper.shape_flow_version_list_result.assert_called_once_with(\\n            rows=rows,\\n            snapshot_result=snapshot_result,\\n            page=2,\\n            size=5,\\n            total=7,\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# provider account routes\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestProviderAccountRoutes:\\n    @pytest.mark.asyncio\\n    async def test_provider_account_guards_precede_all_route_side_effects(self, monkeypatch):\\n        \\\"\\\"\\\"Every provider-account route stops before external I/O or mutation when revoked.\\\"\\\"\\\"\\n        from langflow.api.v1 import deployments as routes\\n\\n        user = _fake_user()\\n        account = _fake_provider_account(user_id=user.id)\\n        denied_guard = AsyncMock(side_effect=HTTPException(status_code=403, detail=\\\"denied\\\"))\\n        mapper = MagicMock()\\n        adapter = MagicMock()\\n        create_row = AsyncMock()\\n        list_rows = AsyncMock()\\n        count_rows = AsyncMock()\\n        fetch_row = AsyncMock(return_value=account)\\n        fetch_owned = AsyncMock(return_value=account)\\n        update_row = AsyncMock()\\n        delete_row = AsyncMock()\\n        reconcile = AsyncMock()\\n\\n        monkeypatch.setattr(routes, \\\"ensure_provider_account_permission\\\", denied_guard)\\n        monkeypatch.setattr(routes, \\\"get_deployment_mapper\\\", mapper)\\n        monkeypatch.setattr(routes, \\\"resolve_deployment_adapter\\\", adapter)\\n        monkeypatch.setattr(routes, \\\"create_provider_account_row\\\", create_row)\\n        monkeypatch.setattr(routes, \\\"list_provider_account_rows\\\", list_rows)\\n        monkeypatch.setattr(routes, \\\"count_provider_account_rows\\\", count_rows)\\n        monkeypatch.setattr(routes, \\\"get_provider_account_row_by_id\\\", fetch_row)\\n        monkeypatch.setattr(routes, \\\"get_owned_provider_account_or_404\\\", fetch_owned)\\n        monkeypatch.setattr(routes, \\\"update_provider_account_row\\\", update_row)\\n        monkeypatch.setattr(routes, \\\"delete_provider_account_row\\\", delete_row)\\n        monkeypatch.setattr(routes, \\\"_count_provider_deployments_after_reconciliation\\\", reconcile)\\n\\n        with pytest.raises(HTTPException) as create_error:\\n            await routes.create_provider_account(\\n                session=AsyncMock(),\\n                payload=SimpleNamespace(provider_key=\\\"test-provider\\\"),\\n                current_user=user,\\n                telemetry=_fake_telemetry(),\\n            )\\n        assert create_error.value.status_code == 403\\n        mapper.assert_not_called()\\n        adapter.assert_not_called()\\n        create_row.assert_not_awaited()\\n\\n        denied_guard.reset_mock(side_effect=True)\\n        denied_guard.side_effect = HTTPException(status_code=403, detail=\\\"denied\\\")\\n        with pytest.raises(HTTPException) as list_error:\\n            await routes.list_provider_accounts(\\n                session=AsyncMock(),\\n                current_user=user,\\n                page=1,\\n                size=20,\\n            )\\n        assert list_error.value.status_code == 403\\n        list_rows.assert_not_awaited()\\n        count_rows.assert_not_awaited()\\n\\n        denied_guard.reset_mock(side_effect=True)\\n        denied_guard.side_effect = HTTPException(status_code=403, detail=\\\"denied\\\")\\n        with pytest.raises(HTTPException) as get_error:\\n            await routes.get_provider_account(\\n                provider_id=account.id,\\n                session=AsyncMock(),\\n                current_user=user,\\n            )\\n        assert get_error.value.status_code == 404\\n        mapper.assert_not_called()\\n\\n        denied_guard.reset_mock(side_effect=True)\\n        denied_guard.side_effect = HTTPException(status_code=403, detail=\\\"denied\\\")\\n        with pytest.raises(HTTPException) as update_error:\\n            await routes.update_provider_account(\\n                provider_id=account.id,\\n                session=AsyncMock(),\\n                payload=DeploymentProviderAccountUpdateRequest(name=\\\"renamed\\\"),\\n                current_user=user,\\n                telemetry=_fake_telemetry(),\\n            )\\n        assert update_error.value.status_code == 404\\n        mapper.assert_not_called()\\n        adapter.assert_not_called()\\n        update_row.assert_not_awaited()\\n\\n        denied_guard.reset_mock(side_effect=True)\\n        denied_guard.side_effect = HTTPException(status_code=403, detail=\\\"denied\\\")\\n        with pytest.raises(HTTPException) as delete_error:\\n            await routes.delete_provider_account(\\n                provider_id=account.id,\\n                session=AsyncMock(),\\n                current_user=user,\\n                telemetry=_fake_telemetry(),\\n            )\\n        assert delete_error.value.status_code == 404\\n        reconcile.assert_not_awaited()\\n        delete_row.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.update_provider_account_row\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_update_provider_account_name_only_skips_credential_verification(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_update_provider_account,\\n    ):\\n        \\\"\\\"\\\"PATCH skips credential verification when only name changes.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_provider_account\\n\\n        existing_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = existing_account\\n        mapper = MagicMock()\\n        mapper.resolve_provider_account_update.return_value = {\\\"name\\\": \\\"renamed\\\"}\\n        mock_get_mapper.return_value = mapper\\n        mock_update_provider_account.return_value = existing_account\\n\\n        session = AsyncMock()\\n        await update_provider_account(\\n            provider_id=existing_account.id,\\n            session=session,\\n            payload=DeploymentProviderAccountUpdateRequest(name=\\\"renamed\\\"),\\n            current_user=_fake_user(),\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        mapper.resolve_verify_credentials_for_update.assert_not_called()\\n        mock_resolve_adapter.assert_not_called()\\n        mock_update_provider_account.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.update_provider_account_row\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_update_provider_account_verify_failure_returns_401(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_update_provider_account,\\n    ):\\n        \\\"\\\"\\\"PATCH verifies new credentials before persisting them.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_provider_account\\n\\n        existing_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = existing_account\\n\\n        mapper = MagicMock()\\n        mapper.resolve_verify_credentials_for_update.return_value = MagicMock()\\n        mock_get_mapper.return_value = mapper\\n\\n        adapter = AsyncMock()\\n        adapter.verify_credentials.side_effect = AuthenticationError(\\n            message=\\\"bad creds\\\",\\n            error_code=\\\"authentication_error\\\",\\n        )\\n        mock_resolve_adapter.return_value = adapter\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await update_provider_account(\\n                provider_id=existing_account.id,\\n                session=AsyncMock(),\\n                payload=DeploymentProviderAccountUpdateRequest(provider_data={\\\"api_key\\\": \\\"new-api-key\\\"}),\\n                current_user=_fake_user(),\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n        assert exc_info.value.status_code == 401\\n        mock_update_provider_account.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.create_provider_account_row\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    async def test_create_provider_account_conflict_returns_409(\\n        self,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_create_provider_account,\\n    ):\\n        \\\"\\\"\\\"POST converts duplicate provider-account conflicts into 409 responses.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import create_provider_account\\n\\n        mapper = MagicMock()\\n        mapper.resolve_verify_credentials_for_create.return_value = MagicMock()\\n        mapper.resolve_provider_account_create.return_value = MagicMock()\\n        mock_get_mapper.return_value = mapper\\n\\n        adapter = AsyncMock()\\n        mock_resolve_adapter.return_value = adapter\\n        mock_create_provider_account.side_effect = ValueError(\\\"Provider account already exists\\\")\\n\\n        payload = DeploymentProviderAccountCreateRequest(\\n            name=\\\"prod\\\",\\n            provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            provider_data={\\n                \\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com/instances/tenant-1\\\",\\n                \\\"api_key\\\": \\\"api-key\\\",  # pragma: allowlist secret\\n            },\\n        )\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await create_provider_account(\\n                session=AsyncMock(),\\n                payload=payload,\\n                current_user=_fake_user(),\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n        assert exc_info.value.status_code == 409\\n        assert exc_info.value.detail == \\\"Provider account is already tracked by user.\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.update_provider_account_row\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_update_provider_account_conflict_returns_409(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_update_provider_account,\\n    ):\\n        \\\"\\\"\\\"PATCH converts duplicate provider-account conflicts into 409 responses.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_provider_account\\n\\n        existing_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = existing_account\\n\\n        mapper = MagicMock()\\n        mapper.resolve_verify_credentials_for_update.return_value = None\\n        mapper.resolve_provider_account_update.return_value = {\\\"name\\\": \\\"prod\\\"}\\n        mock_get_mapper.return_value = mapper\\n        mock_resolve_adapter.return_value = AsyncMock()\\n        mock_update_provider_account.side_effect = ValueError(\\n            \\\"Provider account update conflicts with an existing record\\\"\\n        )\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await update_provider_account(\\n                provider_id=existing_account.id,\\n                session=AsyncMock(),\\n                payload=DeploymentProviderAccountUpdateRequest(name=\\\"prod\\\"),\\n                current_user=_fake_user(),\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n        assert exc_info.value.status_code == 409\\n        assert exc_info.value.detail == \\\"Provider account is already tracked by user.\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.update_provider_account_row\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_update_provider_account_raw_guard_exception_propagates(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_update_provider_account,\\n    ):\\n        \\\"\\\"\\\"PATCH preserves raw guard-shaped DB exceptions without rewriting them.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_provider_account\\n\\n        existing_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = existing_account\\n\\n        mapper = MagicMock()\\n        mapper.resolve_verify_credentials_for_update.return_value = None\\n        mapper.resolve_provider_account_update.return_value = {\\\"provider_data\\\": {\\\"tenant_id\\\": \\\"tenant-renamed\\\"}}\\n        mock_get_mapper.return_value = mapper\\n        mock_resolve_adapter.return_value = AsyncMock()\\n        mock_update_provider_account.side_effect = Exception(\\n            \\\"DEPLOYMENT_GUARD:DEPLOYMENT_PROVIDER_ACCOUNT_IDENTITY_UPDATE:\\\"\\n            \\\"Cannot modify provider key, provider tenant id, or provider URL \\\"\\n            \\\"on an existing deployment provider account. \\\"\\n            \\\"Re-create the account instead.\\\"\\n        )\\n\\n        with pytest.raises(\\n            Exception,\\n            match=\\\"DEPLOYMENT_GUARD:DEPLOYMENT_PROVIDER_ACCOUNT_IDENTITY_UPDATE\\\",\\n        ):\\n            await update_provider_account(\\n                provider_id=existing_account.id,\\n                session=AsyncMock(),\\n                payload=DeploymentProviderAccountUpdateRequest(provider_data={\\\"tenant_id\\\": \\\"tenant-renamed\\\"}),\\n                current_user=_fake_user(),\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.update_provider_account_row\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_update_provider_account_propagates_deployment_guard_error_instance(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_update_provider_account,\\n    ):\\n        \\\"\\\"\\\"PATCH preserves ORM-raised DeploymentGuardError exceptions.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_provider_account\\n\\n        existing_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = existing_account\\n\\n        mapper = MagicMock()\\n        mapper.resolve_verify_credentials_for_update.return_value = None\\n        mapper.resolve_provider_account_update.return_value = {\\\"provider_data\\\": {\\\"tenant_id\\\": \\\"tenant-renamed\\\"}}\\n        mock_get_mapper.return_value = mapper\\n        mock_resolve_adapter.return_value = AsyncMock()\\n        mock_update_provider_account.side_effect = DeploymentGuardError(\\n            code=\\\"DEPLOYMENT_PROVIDER_ACCOUNT_IDENTITY_UPDATE\\\",\\n            technical_detail=\\\"Cannot modify provider key, provider tenant id, or provider URL.\\\",\\n            detail=\\\"Cannot modify provider key, provider tenant id, or provider URL.\\\",\\n        )\\n\\n        with pytest.raises(\\n            DeploymentGuardError,\\n            match=\\\"Cannot modify provider key, provider tenant id, or provider URL\\\",\\n        ):\\n            await update_provider_account(\\n                provider_id=existing_account.id,\\n                session=AsyncMock(),\\n                payload=DeploymentProviderAccountUpdateRequest(provider_data={\\\"tenant_id\\\": \\\"tenant-renamed\\\"}),\\n                current_user=_fake_user(),\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_provider_account_row\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock, return_value=([], 1, {}))\\n    @patch(f\\\"{ROUTES_MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_delete_provider_account_rejects_when_deployments_exist(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_count_deployments,\\n        mock_list_synced,\\n        mock_delete_provider_account,\\n    ):\\n        \\\"\\\"\\\"DELETE refuses to remove provider accounts that still own deployments.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_provider_account\\n\\n        existing_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = existing_account\\n        mock_get_mapper.return_value = MagicMock()\\n        mock_resolve_adapter.return_value = AsyncMock()\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await delete_provider_account(\\n                provider_id=existing_account.id,\\n                session=AsyncMock(),\\n                current_user=_fake_user(),\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n        assert exc_info.value.status_code == 409\\n        mock_count_deployments.assert_awaited_once()\\n        mock_list_synced.assert_awaited_once()\\n        mock_delete_provider_account.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_provider_account_row\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock, return_value=([], 0, {}))\\n    @patch(f\\\"{ROUTES_MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_delete_provider_account_prunes_stale_rows_before_delete(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_count_deployments,\\n        mock_list_synced,\\n        mock_delete_provider_account,\\n    ):\\n        \\\"\\\"\\\"DELETE can proceed when reconciliation shows only stale local deployments remain.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_provider_account\\n\\n        existing_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = existing_account\\n        mock_get_mapper.return_value = MagicMock()\\n        mock_resolve_adapter.return_value = AsyncMock()\\n        session = AsyncMock()\\n\\n        response = await delete_provider_account(\\n            provider_id=existing_account.id,\\n            session=session,\\n            current_user=_fake_user(),\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        assert response.status_code == 204\\n        mock_count_deployments.assert_awaited_once()\\n        mock_list_synced.assert_awaited_once()\\n        mock_delete_provider_account.assert_awaited_once_with(\\n            session,\\n            provider_account=existing_account,\\n        )\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_provider_account_row\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock, return_value=([], 0, {}))\\n    @patch(f\\\"{ROUTES_MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_delete_provider_account_sets_deployment_provider_scope_for_reconciliation(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_count_deployments,  # noqa: ARG002\\n        mock_list_synced,\\n        mock_delete_provider_account,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"Reconciliation must run inside ``deployment_provider_scope`` so adapters can resolve credentials.\\n\\n        Regression test: without the scope, the WxO adapter raises\\n        ``CredentialResolutionError(\\\"Deployment account context is not available...\\\")``\\n        with status 401, the reconciliation is silently dropped, and the stale local\\n        count blocks every provider-account delete with a 409.\\n        \\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_provider_account\\n        from langflow.services.adapters.deployment.context import DeploymentProviderIDContext\\n\\n        existing_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = existing_account\\n        mock_get_mapper.return_value = MagicMock()\\n        mock_resolve_adapter.return_value = AsyncMock()\\n\\n        observed_provider_ids: list[object] = []\\n\\n        async def capture_scope(*_args, **_kwargs):\\n            current = DeploymentProviderIDContext.get_current()\\n            observed_provider_ids.append(None if current is None else current.provider_id)\\n            return ([], 0, {})\\n\\n        mock_list_synced.side_effect = capture_scope\\n\\n        response = await delete_provider_account(\\n            provider_id=existing_account.id,\\n            session=AsyncMock(),\\n            current_user=_fake_user(),\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        assert response.status_code == 204\\n        assert observed_provider_ids == [existing_account.id], (\\n            \\\"list_deployments_synced must run inside deployment_provider_scope(provider_account.id) \\\"\\n            \\\"so the adapter can resolve credentials from DeploymentProviderIDContext.\\\"\\n        )\\n        # And the scope must not leak after the handler returns.\\n        assert DeploymentProviderIDContext.get_current() is None\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_provider_account_row\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_delete_provider_account_falls_back_to_local_count_when_reconciliation_raises(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_count_deployments,\\n        mock_list_synced,\\n        mock_delete_provider_account,\\n    ):\\n        \\\"\\\"\\\"If reconciliation fails (e.g. adapter credential error), fall back to the local count.\\n\\n        The handler must surface the safe 409 (rather than crash) and must NOT delete the\\n        provider account row while local deployments are still tracked.\\n        \\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_provider_account\\n        from lfx.services.adapters.deployment.exceptions import CredentialResolutionError\\n\\n        existing_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = existing_account\\n        mock_get_mapper.return_value = MagicMock()\\n        mock_resolve_adapter.return_value = AsyncMock()\\n        mock_list_synced.side_effect = CredentialResolutionError(\\n            message=\\\"Deployment account context is not available for adapter resolution.\\\"\\n        )\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await delete_provider_account(\\n                provider_id=existing_account.id,\\n                session=AsyncMock(),\\n                current_user=_fake_user(),\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n        assert exc_info.value.status_code == 409\\n        mock_count_deployments.assert_awaited_once()\\n        mock_list_synced.assert_awaited_once()\\n        mock_delete_provider_account.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_provider_account_row\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_delete_provider_account_skips_reconciliation_when_no_local_deployments(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,  # noqa: ARG002\\n        mock_resolve_adapter,  # noqa: ARG002\\n        mock_count_deployments,\\n        mock_list_synced,\\n        mock_delete_provider_account,\\n    ):\\n        \\\"\\\"\\\"When the local count is 0 we must not hit the provider; just delete the row.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_provider_account\\n\\n        existing_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = existing_account\\n        session = AsyncMock()\\n\\n        response = await delete_provider_account(\\n            provider_id=existing_account.id,\\n            session=session,\\n            current_user=_fake_user(),\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        assert response.status_code == 204\\n        mock_count_deployments.assert_awaited_once()\\n        mock_list_synced.assert_not_awaited()\\n        mock_delete_provider_account.assert_awaited_once_with(\\n            session,\\n            provider_account=existing_account,\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# update_deployment: rollback on commit failure\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestUpdateDeploymentRollback:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.rollback_provider_update\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.update_deployment_db\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.apply_flow_version_patch_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_added_snapshot_bindings_for_update\\\", return_value=[])\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_flow_version_patch_for_update\\\", return_value=([], []))\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_rollback_called_on_commit_failure(\\n        self,\\n        mock_resolve_amm,\\n        mock_resolve_fvp,  # noqa: ARG002\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_resolve_snap,  # noqa: ARG002\\n        mock_apply_patch,  # noqa: ARG002\\n        mock_update_db,  # noqa: ARG002\\n        mock_rollback,\\n    ):\\n        \\\"\\\"\\\"When session.commit() fails, rollback_provider_update is called.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        update_result = DeploymentUpdateResult(id=\\\"provider-dep-1\\\")\\n        adapter.update.return_value = update_result\\n        mapper.resolve_deployment_update = AsyncMock(return_value=MagicMock())\\n        mapper.resolve_kwargs_for_metadata_update.return_value = {\\\"description\\\": None}\\n        mapper.shape_deployment_update_result.return_value = MagicMock()\\n        mock_resolve_amm.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        session = AsyncMock()\\n        session.commit.side_effect = RuntimeError(\\\"DB commit failed\\\")\\n\\n        payload = MagicMock()\\n        payload.display_name = None\\n        payload.description = None\\n\\n        with pytest.raises(RuntimeError, match=\\\"DB commit failed\\\"):\\n            await update_deployment(\\n                deployment_id=dep_row.id,\\n                session=session,\\n                payload=payload,\\n                current_user=_fake_user(),\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n        mock_rollback.assert_awaited_once()\\n        assert mock_rollback.call_args.kwargs[\\\"deployment_db_id\\\"] == dep_row.id\\n        assert mock_rollback.call_args.kwargs[\\\"deployment_resource_key\\\"] == dep_row.resource_key\\n        assert (\\n            mock_rollback.call_args.kwargs[\\\"deployment_provider_account_id\\\"] == dep_row.deployment_provider_account_id\\n        )\\n        assert mock_rollback.call_args.kwargs[\\\"user_id\\\"] == dep_row.user_id\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.rollback_provider_update\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.update_deployment_db\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.apply_flow_version_patch_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_added_snapshot_bindings_for_update\\\", return_value=[])\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_flow_version_patch_for_update\\\", return_value=([], []))\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_rollback_uses_owner_namespace_for_non_owner_actor(\\n        self,\\n        mock_resolve_amm,\\n        mock_resolve_fvp,  # noqa: ARG002\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_resolve_snap,  # noqa: ARG002\\n        mock_apply_patch,  # noqa: ARG002\\n        mock_update_db,  # noqa: ARG002\\n        mock_rollback,\\n    ):\\n        \\\"\\\"\\\"Shared-update rollback must stay in the deployment owner's namespace.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_deployment\\n\\n        owner_id = uuid4()\\n        actor = _fake_user()\\n        dep_row = _fake_deployment_row(user_id=owner_id)\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        update_result = DeploymentUpdateResult(id=\\\"provider-dep-1\\\")\\n        adapter.update.return_value = update_result\\n        mapper.resolve_deployment_update = AsyncMock(return_value=MagicMock())\\n        mapper.resolve_kwargs_for_metadata_update.return_value = {\\\"description\\\": None}\\n        mapper.shape_deployment_update_result.return_value = MagicMock()\\n        mock_resolve_amm.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        session = AsyncMock()\\n        session.commit.side_effect = RuntimeError(\\\"DB commit failed\\\")\\n\\n        payload = MagicMock()\\n        payload.display_name = None\\n        payload.description = None\\n\\n        with pytest.raises(RuntimeError, match=\\\"DB commit failed\\\"):\\n            await update_deployment(\\n                deployment_id=dep_row.id,\\n                session=session,\\n                payload=payload,\\n                current_user=actor,\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n        assert actor.id != owner_id\\n        assert mock_rollback.call_args.kwargs[\\\"user_id\\\"] == owner_id\\n        assert adapter.update.await_args.kwargs[\\\"user_id\\\"] == owner_id\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.rollback_provider_update\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.update_deployment_db\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.apply_flow_version_patch_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_added_snapshot_bindings_for_update\\\", return_value=[])\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_flow_version_patch_for_update\\\", return_value=([], []))\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_no_rollback_on_success(\\n        self,\\n        mock_resolve_amm,\\n        mock_resolve_fvp,  # noqa: ARG002\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_resolve_snap,  # noqa: ARG002\\n        mock_apply_patch,  # noqa: ARG002\\n        mock_update_db,  # noqa: ARG002\\n        mock_rollback,\\n    ):\\n        \\\"\\\"\\\"On successful commit, rollback is NOT called.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        update_result = DeploymentUpdateResult(id=\\\"provider-dep-1\\\")\\n        adapter.update.return_value = update_result\\n        mapper.resolve_deployment_update = AsyncMock(return_value=MagicMock())\\n        mapper.resolve_kwargs_for_metadata_update.return_value = {\\\"description\\\": None}\\n        mapper.shape_deployment_update_result.return_value = MagicMock()\\n        mock_resolve_amm.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        session = AsyncMock()\\n        session.commit.return_value = None\\n\\n        payload = MagicMock()\\n        payload.display_name = None\\n        payload.description = None\\n\\n        await update_deployment(\\n            deployment_id=dep_row.id,\\n            session=session,\\n            payload=payload,\\n            current_user=_fake_user(),\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        mock_rollback.assert_not_awaited()\\n\\n\\nclass TestUpdateDeploymentAlreadyAttachedFiltering:\\n    \\\"\\\"\\\"Bind operations for flow versions that already have DB attachments.\\n\\n    These should not be passed to resolve_added_snapshot_bindings_for_update,\\n    since the adapter does not return new snapshot bindings for reused tools.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.apply_flow_version_patch_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_added_snapshot_bindings_for_update\\\", return_value=[])\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployment_attachments_for_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_flow_deploy_for_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_flow_version_patch_for_update\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_already_attached_flow_versions_excluded_from_snapshot_resolution(\\n        self,\\n        mock_resolve_amm,\\n        mock_resolve_fvp,\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_ensure_deploy,  # noqa: ARG002\\n        mock_list_attachments,\\n        mock_resolve_snap,\\n        mock_apply_patch,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"Only truly new flow version IDs are passed to snapshot resolution.\\n\\n        When some bind flow version IDs already have DB attachments, only the\\n        truly new ones are passed to resolve_added_snapshot_bindings_for_update.\\n        \\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        update_result = DeploymentUpdateResult(id=\\\"provider-dep-1\\\")\\n        adapter.update.return_value = update_result\\n        mapper.resolve_deployment_update = AsyncMock(return_value=MagicMock())\\n        mapper.resolve_kwargs_for_metadata_update.return_value = {\\\"description\\\": None}\\n        mapper.shape_deployment_update_result.return_value = MagicMock()\\n        mock_resolve_amm.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        reused_fv_id = uuid4()\\n        new_fv_id = uuid4()\\n        mock_resolve_fvp.return_value = ([reused_fv_id, new_fv_id], [])\\n\\n        mock_list_attachments.return_value = [\\n            SimpleNamespace(flow_version_id=reused_fv_id, provider_snapshot_id=\\\"existing-tool-1\\\"),\\n        ]\\n\\n        session = AsyncMock()\\n        session.commit.return_value = None\\n\\n        payload = MagicMock()\\n        payload.display_name = None\\n        payload.description = None\\n\\n        await update_deployment(\\n            deployment_id=dep_row.id,\\n            session=session,\\n            payload=payload,\\n            current_user=_fake_user(),\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        mock_resolve_snap.assert_called_once()\\n        resolved_fv_ids = mock_resolve_snap.call_args.kwargs[\\\"added_flow_version_ids\\\"]\\n        assert resolved_fv_ids == [new_fv_id]\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.apply_flow_version_patch_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_added_snapshot_bindings_for_update\\\", return_value=[])\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployment_attachments_for_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_flow_deploy_for_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_flow_version_patch_for_update\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_all_flow_versions_already_attached_passes_empty_list(\\n        self,\\n        mock_resolve_amm,\\n        mock_resolve_fvp,\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_ensure_deploy,  # noqa: ARG002\\n        mock_list_attachments,\\n        mock_resolve_snap,\\n        mock_apply_patch,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"An empty list is passed when all flow versions are already attached.\\n\\n        When all bind flow versions already have attachments, an empty list\\n        is passed to resolve_added_snapshot_bindings_for_update.\\n        \\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        update_result = DeploymentUpdateResult(id=\\\"provider-dep-1\\\")\\n        adapter.update.return_value = update_result\\n        mapper.resolve_deployment_update = AsyncMock(return_value=MagicMock())\\n        mapper.resolve_kwargs_for_metadata_update.return_value = {\\\"description\\\": None}\\n        mapper.shape_deployment_update_result.return_value = MagicMock()\\n        mock_resolve_amm.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        fv_id_1 = uuid4()\\n        fv_id_2 = uuid4()\\n        mock_resolve_fvp.return_value = ([fv_id_1, fv_id_2], [])\\n\\n        mock_list_attachments.return_value = [\\n            SimpleNamespace(flow_version_id=fv_id_1, provider_snapshot_id=\\\"tool-1\\\"),\\n            SimpleNamespace(flow_version_id=fv_id_2, provider_snapshot_id=\\\"tool-2\\\"),\\n        ]\\n\\n        session = AsyncMock()\\n        session.commit.return_value = None\\n\\n        payload = MagicMock()\\n        payload.display_name = None\\n        payload.description = None\\n\\n        await update_deployment(\\n            deployment_id=dep_row.id,\\n            session=session,\\n            payload=payload,\\n            current_user=_fake_user(),\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        resolved_fv_ids = mock_resolve_snap.call_args.kwargs[\\\"added_flow_version_ids\\\"]\\n        assert resolved_fv_ids == []\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.apply_flow_version_patch_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_added_snapshot_bindings_for_update\\\", return_value=[])\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployment_attachments_for_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_flow_deploy_for_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_flow_version_patch_for_update\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_no_existing_attachments_passes_all_flow_versions(\\n        self,\\n        mock_resolve_amm,\\n        mock_resolve_fvp,\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_ensure_deploy,  # noqa: ARG002\\n        mock_list_attachments,\\n        mock_resolve_snap,\\n        mock_apply_patch,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"When no bind flow versions have existing attachments, all are passed through.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        update_result = DeploymentUpdateResult(id=\\\"provider-dep-1\\\")\\n        adapter.update.return_value = update_result\\n        mapper.resolve_deployment_update = AsyncMock(return_value=MagicMock())\\n        mapper.resolve_kwargs_for_metadata_update.return_value = {}\\n        mapper.shape_deployment_update_result.return_value = MagicMock()\\n        mock_resolve_amm.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        fv_id_1 = uuid4()\\n        fv_id_2 = uuid4()\\n        mock_resolve_fvp.return_value = ([fv_id_1, fv_id_2], [])\\n\\n        mock_list_attachments.return_value = []\\n\\n        session = AsyncMock()\\n        session.commit.return_value = None\\n\\n        payload = MagicMock()\\n        payload.display_name = None\\n        payload.description = None\\n\\n        await update_deployment(\\n            deployment_id=dep_row.id,\\n            session=session,\\n            payload=payload,\\n            current_user=_fake_user(),\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        resolved_fv_ids = mock_resolve_snap.call_args.kwargs[\\\"added_flow_version_ids\\\"]\\n        assert resolved_fv_ids == [fv_id_1, fv_id_2]\\n\\n\\nclass TestUpdateDeploymentMetadataPersistence:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.update_deployment_db\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.apply_flow_version_patch_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_added_snapshot_bindings_for_update\\\", return_value=[])\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_flow_version_patch_for_update\\\", return_value=([], []))\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_provider_update_metadata_is_persisted_from_adapter_result(\\n        self,\\n        mock_resolve_amm,\\n        mock_resolve_fvp,  # noqa: ARG002\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_resolve_snap,  # noqa: ARG002\\n        mock_apply_patch,  # noqa: ARG002\\n        mock_update_db,\\n    ):\\n        \\\"\\\"\\\"PATCH should persist provider-returned metadata, even when the DB row is stale.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_deployment\\n\\n        dep_row = _fake_deployment_row(display_name=\\\"old-name\\\", description=\\\"old-description\\\")\\n        updated_row = _fake_deployment_row(\\n            id=dep_row.id,\\n            resource_key=dep_row.resource_key,\\n            display_name=\\\"provider-renamed\\\",\\n            description=\\\"provider-description\\\",\\n            deployment_provider_account_id=dep_row.deployment_provider_account_id,\\n            project_id=dep_row.project_id,\\n        )\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        update_result = DeploymentUpdateResult(id=\\\"provider-dep-1\\\")\\n        adapter.update.return_value = update_result\\n        mapper.resolve_deployment_update = AsyncMock(return_value=MagicMock())\\n        mapper.shape_deployment_update_result.return_value = MagicMock()\\n        mapper.resolve_kwargs_for_metadata_update.return_value = {\\n            \\\"display_name\\\": \\\"provider-renamed\\\",\\n            \\\"description\\\": \\\"provider-description\\\",\\n        }\\n        mock_resolve_amm.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        mock_update_db.return_value = updated_row\\n\\n        session = AsyncMock()\\n        session.commit.return_value = None\\n\\n        payload = DeploymentUpdateRequest.model_validate(\\n            {\\n                \\\"provider_data\\\": {\\\"display_name\\\": \\\"renamed\\\"},\\n                \\\"description\\\": None,\\n            }\\n        )\\n\\n        await update_deployment(\\n            deployment_id=dep_row.id,\\n            session=session,\\n            payload=payload,\\n            current_user=_fake_user(),\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        mock_update_db.assert_awaited_once()\\n        update_kwargs = mock_update_db.call_args.kwargs\\n        assert update_kwargs[\\\"display_name\\\"] == \\\"provider-renamed\\\"\\n        assert update_kwargs[\\\"description\\\"] == \\\"provider-description\\\"\\n        mapper.resolve_kwargs_for_metadata_update.assert_called_once_with(update_result)\\n\\n\\n# ---------------------------------------------------------------------------\\n# get_deployment: deployment-level sync\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestGetDeploymentSync:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{HELPERS_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_stale_row_deleted_when_provider_returns_not_found(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"When the provider raises DeploymentNotFoundError, the DB row is deleted and 404 returned.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import get_deployment\\n        from langflow.api.v1.mappers.deployments.base import BaseDeploymentMapper\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        adapter.get.side_effect = DeploymentNotFoundError(message=\\\"gone\\\")\\n        mock_resolve.return_value = (dep_row, adapter, BaseDeploymentMapper(), \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        user = _fake_user()\\n        session = AsyncMock()\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await get_deployment(deployment_id=dep_row.id, session=session, current_user=user)\\n\\n        assert exc_info.value.status_code == 404\\n        # Stale-row delete now runs in the deployment owner's namespace so\\n        # a non-owner with a share grant can still prune the owner's stale\\n        # row. ``current_user`` is only the actor for audit.\\n        mock_delete_row.assert_awaited_once_with(session, user_id=dep_row.user_id, deployment_id=dep_row.id)\\n        session.commit.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{HELPERS_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_non_404_adapter_error_does_not_delete_row(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"When adapter.get() raises a non-404 DeploymentServiceError, the DB row is kept.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import get_deployment\\n        from langflow.api.v1.mappers.deployments.base import BaseDeploymentMapper\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        adapter.get.side_effect = AuthenticationError(message=\\\"bad creds\\\", error_code=\\\"authentication_error\\\")\\n        mock_resolve.return_value = (dep_row, adapter, BaseDeploymentMapper(), \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        session = AsyncMock()\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await get_deployment(deployment_id=dep_row.id, session=session, current_user=_fake_user())\\n\\n        assert exc_info.value.status_code == 401\\n        mock_delete_row.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{HELPERS_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_service_unavailable_returns_503(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"When adapter.get() raises ServiceUnavailableError, 503 is returned and row is kept.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import get_deployment\\n        from langflow.api.v1.mappers.deployments.base import BaseDeploymentMapper\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        adapter.get.side_effect = ServiceUnavailableError(message=\\\"provider down\\\")\\n        mock_resolve.return_value = (dep_row, adapter, BaseDeploymentMapper(), \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        session = AsyncMock()\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await get_deployment(deployment_id=dep_row.id, session=session, current_user=_fake_user())\\n\\n        assert exc_info.value.status_code == 503\\n        mock_delete_row.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{HELPERS_MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{HELPERS_MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_get_deployment_does_not_inject_resource_key_into_provider_data(\\n        self,\\n        mock_resolve,\\n        mock_count_att,  # noqa: ARG002\\n        mock_delete_unbound,  # noqa: ARG002\\n    ):\\n        from langflow.api.v1.deployments import get_deployment\\n        from langflow.api.v1.mappers.deployments.base import BaseDeploymentMapper\\n\\n        class _MapperForGet(BaseDeploymentMapper):\\n            def shape_deployment_get_data(self, provider_data, *, name=None):  # noqa: ARG002\\n                if provider_data is None:\\n                    return None\\n                sanitized_provider_data = dict(provider_data)\\n                sanitized_provider_data.pop(\\\"tool_ids\\\", None)\\n                return sanitized_provider_data or None\\n\\n            def extract_metadata_for_get(self, get_result):\\n                _ = get_result\\n                return {\\\"display_name\\\": dep_row.display_name, \\\"description\\\": dep_row.description}\\n\\n            def extract_snapshot_bindings_for_get(self, get_result, *, resource_key: str):\\n                return [\\n                    ProviderSnapshotBinding(resource_key=resource_key, snapshot_id=snapshot_id)\\n                    for snapshot_id in get_result.model_dump()[\\\"provider_data\\\"][\\\"tool_ids\\\"]\\n                ]\\n\\n        created_at = datetime(2026, 1, 2, 3, 4, 5, tzinfo=timezone.utc)\\n        updated_at = datetime(2026, 1, 3, 4, 5, 6, tzinfo=timezone.utc)\\n        dep_row = _fake_deployment_row(\\n            resource_key=\\\"provider-rk-1\\\",\\n            display_name=\\\"db-owned-name\\\",\\n            description=\\\"db-owned-description\\\",\\n            deployment_type=\\\"agent\\\",\\n            created_at=created_at,\\n            updated_at=updated_at,\\n        )\\n        adapter = AsyncMock()\\n        provider_deployment = MagicMock()\\n        provider_deployment.name = \\\"provider-owned-name\\\"\\n        provider_deployment.description = \\\"provider-owned-description\\\"\\n        provider_deployment.type = \\\"worker\\\"\\n        provider_deployment.created_at = None\\n        provider_deployment.updated_at = None\\n        provider_deployment.model_dump.return_value = {\\n            \\\"provider_data\\\": {\\n                \\\"llm\\\": \\\"virtual-model/bedrock/openai.gpt-oss-120b-1:0\\\",\\n                \\\"tool_ids\\\": [\\\"tool-1\\\", \\\"tool-2\\\"],\\n            }\\n        }\\n        adapter.get.return_value = provider_deployment\\n        mock_resolve.return_value = (dep_row, adapter, _MapperForGet(), \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        session = AsyncMock()\\n        session.begin_nested = MagicMock(return_value=_AsyncNoopSavepoint())\\n        result = await get_deployment(deployment_id=dep_row.id, session=session, current_user=_fake_user())\\n\\n        assert result.resource_key == \\\"provider-rk-1\\\"\\n        assert result.description == \\\"db-owned-description\\\"\\n        assert result.type == \\\"agent\\\"\\n        assert result.created_at == created_at\\n        assert result.updated_at == updated_at\\n        assert \\\"tool_ids\\\" not in result.provider_data\\n        assert result.provider_data == {\\\"llm\\\": \\\"virtual-model/bedrock/openai.gpt-oss-120b-1:0\\\"}\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{HELPERS_MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{HELPERS_MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{HELPERS_MODULE}.update_deployment_metadata\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_get_sync_passes_provider_description_and_keeps_display_name_in_provider_data(\\n        self,\\n        mock_resolve,\\n        mock_update_metadata,\\n        mock_count_att,  # noqa: ARG002\\n        mock_delete_unbound,  # noqa: ARG002\\n    ):\\n        from langflow.api.v1.deployments import get_deployment\\n        from langflow.api.v1.mappers.deployments.base import BaseDeploymentMapper\\n\\n        class _MapperForGet(BaseDeploymentMapper):\\n            def shape_deployment_get_data(self, provider_data, *, name=None):  # noqa: ARG002\\n                return dict(provider_data) if provider_data is not None else None\\n\\n            def extract_metadata_for_get(self, get_result):\\n                data = get_result.model_dump()[\\\"provider_data\\\"]\\n                return {\\n                    \\\"display_name\\\": data[\\\"display_name\\\"],\\n                    \\\"description\\\": data[\\\"description\\\"],\\n                }\\n\\n            def extract_snapshot_bindings_for_get(self, get_result, *, resource_key: str):\\n                _ = (get_result, resource_key)\\n                return []\\n\\n        dep_row = _fake_deployment_row(\\n            resource_key=\\\"provider-rk-1\\\",\\n            display_name=\\\"old label\\\",\\n            description=\\\"old description\\\",\\n            deployment_type=\\\"agent\\\",\\n        )\\n        long_description = \\\"x\\\" * 501\\n        adapter = AsyncMock()\\n        adapter.get.return_value = DeploymentGetResult(\\n            id=\\\"provider-rk-1\\\",\\n            name=\\\"agent_technical_name\\\",\\n            type=\\\"agent\\\",\\n            provider_data={\\n                \\\"display_name\\\": \\\"Provider Label\\\",\\n                \\\"description\\\": long_description,\\n            },\\n        )\\n\\n        def _apply_metadata(*_args, **kwargs):\\n            dep_row.display_name = kwargs[\\\"display_name\\\"]\\n            dep_row.description = kwargs[\\\"description\\\"]\\n            return dep_row\\n\\n        mock_update_metadata.side_effect = _apply_metadata\\n        mock_resolve.return_value = (dep_row, adapter, _MapperForGet(), \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        session = AsyncMock()\\n        session.begin_nested = MagicMock(return_value=_AsyncNoopSavepoint())\\n        result = await get_deployment(deployment_id=dep_row.id, session=session, current_user=_fake_user())\\n\\n        assert result.description == long_description\\n        assert result.provider_data[\\\"display_name\\\"] == \\\"Provider Label\\\"\\n        assert not hasattr(result, \\\"display_name\\\")\\n        mock_update_metadata.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{HELPERS_MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{HELPERS_MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_snapshot_sync_corrects_attached_count(\\n        self,\\n        mock_resolve,\\n        mock_count_att,\\n        mock_delete_unbound,\\n    ):\\n        \\\"\\\"\\\"Binding-aware sync corrects attached_count in the response.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import get_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        provider_deployment = MagicMock()\\n        provider_deployment.name = \\\"deployed-agent\\\"\\n        provider_deployment.description = \\\"desc\\\"\\n        provider_deployment.type = \\\"agent\\\"\\n        provider_deployment.created_at = None\\n        provider_deployment.updated_at = None\\n        provider_deployment.model_dump.return_value = {}\\n        adapter.get.return_value = provider_deployment\\n        mapper.extract_snapshot_bindings_for_get.return_value = [\\n            ProviderSnapshotBinding(resource_key=dep_row.resource_key, snapshot_id=\\\"snap-1\\\")\\n        ]\\n        mapper.extract_metadata_for_get.return_value = {\\n            \\\"display_name\\\": dep_row.display_name,\\n            \\\"description\\\": dep_row.description,\\n        }\\n        mapper.shape_deployment_get_data.return_value = None\\n        mock_resolve.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        mock_count_att.return_value = 1\\n\\n        session = AsyncMock()\\n        session.begin_nested = MagicMock(return_value=_AsyncNoopSavepoint())\\n        result = await get_deployment(deployment_id=dep_row.id, session=session, current_user=_fake_user())\\n\\n        assert result.attached_count == 1\\n        mock_delete_unbound.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{HELPERS_MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{HELPERS_MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_unsupported_provider_get_sync_raises(\\n        self,\\n        mock_resolve,\\n        mock_count_att,\\n        mock_delete_unbound,\\n    ):\\n        \\\"\\\"\\\"NotImplemented mapper GET sync fails because binding-aware sync is required.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import get_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        provider_deployment = MagicMock()\\n        provider_deployment.name = \\\"deployed-agent\\\"\\n        provider_deployment.description = \\\"desc\\\"\\n        provider_deployment.type = \\\"agent\\\"\\n        provider_deployment.created_at = None\\n        provider_deployment.updated_at = None\\n        provider_deployment.model_dump.return_value = {}\\n        adapter.get.return_value = provider_deployment\\n        mapper.extract_snapshot_bindings_for_get.side_effect = NotImplementedError(\\\"not supported\\\")\\n        mapper.extract_metadata_for_get.return_value = {\\n            \\\"display_name\\\": dep_row.display_name,\\n            \\\"description\\\": dep_row.description,\\n        }\\n        mapper.shape_deployment_get_data.return_value = None\\n        mock_resolve.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        session = AsyncMock()\\n        with pytest.raises(HTTPException) as exc_info:\\n            await get_deployment(deployment_id=dep_row.id, session=session, current_user=_fake_user())\\n\\n        assert exc_info.value.status_code == 500\\n        assert \\\"does not support binding-aware GET sync\\\" in str(exc_info.value.detail)\\n        session.rollback.assert_not_awaited()\\n        mock_count_att.assert_not_awaited()\\n        mock_delete_unbound.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{HELPERS_MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{HELPERS_MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_binding_aware_sync_error_falls_back_to_unverified_count(\\n        self,\\n        mock_resolve,\\n        mock_count_att,\\n        mock_delete_unbound,\\n    ):\\n        \\\"\\\"\\\"When binding-aware sync raises, response uses unverified attachment count.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import get_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        provider_deployment = MagicMock()\\n        provider_deployment.name = \\\"deployed-agent\\\"\\n        provider_deployment.description = \\\"desc\\\"\\n        provider_deployment.type = \\\"agent\\\"\\n        provider_deployment.created_at = None\\n        provider_deployment.updated_at = None\\n        provider_deployment.model_dump.return_value = {}\\n        adapter.get.return_value = provider_deployment\\n        mapper.extract_snapshot_bindings_for_get.return_value = [\\n            ProviderSnapshotBinding(resource_key=dep_row.resource_key, snapshot_id=\\\"snap-1\\\")\\n        ]\\n        mapper.extract_metadata_for_get.return_value = {\\n            \\\"display_name\\\": dep_row.display_name,\\n            \\\"description\\\": dep_row.description,\\n        }\\n        mapper.shape_deployment_get_data.return_value = None\\n        mock_resolve.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        mock_count_att.return_value = 2\\n        mock_delete_unbound.side_effect = RuntimeError(\\\"provider down\\\")\\n\\n        session = AsyncMock()\\n        session.begin_nested = MagicMock(return_value=_AsyncNoopSavepoint())\\n        result = await get_deployment(deployment_id=dep_row.id, session=session, current_user=_fake_user())\\n\\n        assert result.attached_count == 2\\n        session.rollback.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{HELPERS_MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{HELPERS_MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_binding_aware_sync_and_fallback_count_failure_raises(\\n        self,\\n        mock_resolve,\\n        mock_count_att,\\n        mock_delete_unbound,\\n    ):\\n        \\\"\\\"\\\"When sync and fallback count both fail, return an explicit count error.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import get_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        provider_deployment = MagicMock()\\n        provider_deployment.name = \\\"deployed-agent\\\"\\n        provider_deployment.description = \\\"desc\\\"\\n        provider_deployment.type = \\\"agent\\\"\\n        provider_deployment.created_at = None\\n        provider_deployment.updated_at = None\\n        provider_deployment.model_dump.return_value = {}\\n        adapter.get.return_value = provider_deployment\\n        mapper.extract_snapshot_bindings_for_get.return_value = [\\n            ProviderSnapshotBinding(resource_key=dep_row.resource_key, snapshot_id=\\\"snap-1\\\")\\n        ]\\n        mapper.extract_metadata_for_get.return_value = {\\n            \\\"display_name\\\": dep_row.display_name,\\n            \\\"description\\\": dep_row.description,\\n        }\\n        mapper.shape_deployment_get_data.return_value = None\\n        mock_resolve.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        mock_delete_unbound.side_effect = RuntimeError(\\\"sync failed\\\")\\n        mock_count_att.side_effect = RuntimeError(\\\"count failed\\\")\\n\\n        session = AsyncMock()\\n        session.begin_nested = MagicMock(return_value=_AsyncNoopSavepoint())\\n        with pytest.raises(HTTPException) as exc_info:\\n            await get_deployment(deployment_id=dep_row.id, session=session, current_user=_fake_user())\\n\\n        assert exc_info.value.status_code == 500\\n        assert str(dep_row.id) in str(exc_info.value.detail)\\n        assert \\\"Failed to retrieve the number of flows attached\\\" in str(exc_info.value.detail)\\n        session.rollback.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{HELPERS_MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{HELPERS_MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_binding_aware_sync_prunes_detached_attachments(\\n        self,\\n        mock_resolve,\\n        mock_count_att,\\n        mock_delete_unbound,\\n    ):\\n        \\\"\\\"\\\"Binding-aware sync sends authoritative bindings and returns corrected count.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import get_deployment\\n\\n        dep_row = _fake_deployment_row(resource_key=\\\"agent-rk-1\\\")\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        provider_deployment = MagicMock()\\n        provider_deployment.model_dump.return_value = {}\\n        adapter.get.return_value = provider_deployment\\n        mapper.extract_snapshot_bindings_for_get.return_value = [\\n            ProviderSnapshotBinding(resource_key=\\\"agent-rk-1\\\", snapshot_id=\\\"snap-1\\\")\\n        ]\\n        mapper.extract_metadata_for_get.return_value = {\\n            \\\"display_name\\\": dep_row.display_name,\\n            \\\"description\\\": dep_row.description,\\n        }\\n        mapper.shape_deployment_get_data.return_value = None\\n        mock_resolve.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        mock_count_att.return_value = 1\\n\\n        session = AsyncMock()\\n        session.begin_nested = MagicMock(return_value=_AsyncNoopSavepoint())\\n        result = await get_deployment(deployment_id=dep_row.id, session=session, current_user=_fake_user())\\n\\n        assert result.attached_count == 1\\n        mock_delete_unbound.assert_awaited_once_with(\\n            db=session,\\n            user_id=ANY,\\n            provider_account_id=dep_row.deployment_provider_account_id,\\n            deployment_ids=[dep_row.id],\\n            bindings=[ProviderSnapshotBinding(resource_key=\\\"agent-rk-1\\\", snapshot_id=\\\"snap-1\\\")],\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# delete_deployment: stale-row cleanup + commit retry\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestDeleteDeployment:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_provider_not_found_still_deletes_local_row(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"Delete is idempotent when the provider agent is already gone.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_deployment\\n\\n        mock_delete_row.return_value = 1\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        adapter.delete.side_effect = DeploymentNotFoundError(message=\\\"gone\\\")\\n        mock_resolve.return_value = (dep_row, adapter, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        user = _fake_user()\\n        session = AsyncMock()\\n\\n        response = await delete_deployment(\\n            deployment_id=dep_row.id, session=session, current_user=user, telemetry=_fake_telemetry()\\n        )\\n\\n        assert response.status_code == 204\\n        mock_delete_row.assert_awaited_once_with(session, user_id=dep_row.user_id, deployment_id=dep_row.id)\\n        session.commit.assert_awaited_once()\\n        session.rollback.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_non_404_provider_error_does_not_delete_local_row(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"Delete keeps the DB row when the provider call fails for non-404 reasons.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        adapter.delete.side_effect = AuthenticationError(message=\\\"bad creds\\\", error_code=\\\"authentication_error\\\")\\n        mock_resolve.return_value = (dep_row, adapter, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        session = AsyncMock()\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await delete_deployment(\\n                deployment_id=dep_row.id, session=session, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        assert exc_info.value.status_code == 401\\n        mock_delete_row.assert_not_awaited()\\n        session.commit.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_commit_failure_retries_local_cleanup_once(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"A failed local commit after provider delete triggers one cleanup retry.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mock_resolve.return_value = (dep_row, adapter, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        user = _fake_user()\\n        session = AsyncMock()\\n        session.commit.side_effect = [RuntimeError(\\\"commit failed\\\"), None]\\n        mock_delete_row.return_value = 1\\n\\n        response = await delete_deployment(\\n            deployment_id=dep_row.id, session=session, current_user=user, telemetry=_fake_telemetry()\\n        )\\n\\n        assert response.status_code == 204\\n        assert mock_delete_row.await_count == 2\\n        session.rollback.assert_awaited_once()\\n        assert session.commit.await_count == 2\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_repeated_local_cleanup_failure_returns_500(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"If cleanup still fails after retry, the route surfaces a 500.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mock_resolve.return_value = (dep_row, adapter, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        session = AsyncMock()\\n        session.commit.side_effect = [RuntimeError(\\\"commit failed\\\"), RuntimeError(\\\"still failing\\\")]\\n        mock_delete_row.return_value = 1\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await delete_deployment(\\n                deployment_id=dep_row.id, session=session, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        assert exc_info.value.status_code == 500\\n        assert mock_delete_row.await_count == 2\\n        assert session.rollback.await_count == 2\\n        assert session.commit.await_count == 2\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_include_provider_true_calls_adapter_delete(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"include_provider=True (default) calls adapter.delete to remove provider resources.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_deployment\\n\\n        mock_delete_row.return_value = 1\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mock_resolve.return_value = (dep_row, adapter, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        user = _fake_user()\\n        session = AsyncMock()\\n\\n        response = await delete_deployment(\\n            deployment_id=dep_row.id,\\n            session=session,\\n            current_user=user,\\n            include_provider=True,\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        assert response.status_code == 204\\n        adapter.delete.assert_awaited_once()\\n        mock_delete_row.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_include_provider_false_skips_adapter_delete(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"include_provider=False skips the adapter entirely \u2014 only the DB row is removed.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_deployment\\n\\n        mock_delete_row.return_value = 1\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mock_resolve.return_value = (dep_row, adapter, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        user = _fake_user()\\n        session = AsyncMock()\\n\\n        response = await delete_deployment(\\n            deployment_id=dep_row.id,\\n            session=session,\\n            current_user=user,\\n            include_provider=False,\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        assert response.status_code == 204\\n        adapter.delete.assert_not_awaited()\\n        mock_delete_row.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_shared_delete_uses_deployment_owner_for_local_cleanup(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"Non-owner delete cleans up the owner's DB row, not the actor's namespace.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_deployment\\n\\n        mock_delete_row.return_value = 1\\n        owner_id = uuid4()\\n        actor = _fake_user()\\n        dep_row = _fake_deployment_row(user_id=owner_id)\\n        adapter = AsyncMock()\\n        mock_resolve.return_value = (dep_row, adapter, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        session = AsyncMock()\\n        response = await delete_deployment(\\n            deployment_id=dep_row.id, session=session, current_user=actor, telemetry=_fake_telemetry()\\n        )\\n\\n        assert response.status_code == 204\\n        assert actor.id != owner_id\\n        mock_delete_row.assert_awaited_once_with(session, user_id=owner_id, deployment_id=dep_row.id)\\n        adapter.delete.assert_awaited_once()\\n        assert adapter.delete.await_args.kwargs[\\\"user_id\\\"] == owner_id\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_zero_row_local_delete_returns_404(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"Local delete must remove exactly one row; zero rows means the deployment is gone.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_deployment\\n\\n        mock_delete_row.return_value = 0\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mock_resolve.return_value = (dep_row, adapter, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        session = AsyncMock()\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await delete_deployment(\\n                deployment_id=dep_row.id, session=session, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        assert exc_info.value.status_code == 404\\n        mock_delete_row.assert_awaited_once()\\n        session.commit.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_unconfirmed_local_delete_rowcount_returns_500(\\n        self,\\n        mock_resolve,\\n        mock_delete_row,\\n    ):\\n        \\\"\\\"\\\"Unknown DELETE rowcount must not be treated as success or as 404.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import delete_deployment\\n        from langflow.services.database.models.deployment.crud import UNCONFIRMED_DELETE_ROWCOUNT\\n\\n        mock_delete_row.return_value = UNCONFIRMED_DELETE_ROWCOUNT\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mock_resolve.return_value = (dep_row, adapter, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n        session = AsyncMock()\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await delete_deployment(\\n                deployment_id=dep_row.id, session=session, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        assert exc_info.value.status_code == 500\\n        mock_delete_row.assert_awaited_once()\\n        session.commit.assert_not_awaited()\\n\\n\\n# ---------------------------------------------------------------------------\\n# create_deployment: duplicate name returns 409\\n# ---------------------------------------------------------------------------\\n\\n\\n# ---------------------------------------------------------------------------\\n# create_deployment: project-scoped flow version validation\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestCreateDeploymentProjectValidation:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_project_id_for_deployment_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_validation_called_before_adapter(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_resolve_project,\\n        mock_validate_fv,\\n    ):\\n        \\\"\\\"\\\"validate_project_scoped_flow_version_ids is called before the adapter create.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import create_deployment\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        fv_ids = [uuid4(), uuid4()]\\n        mapper.util_create_flow_version_ids.return_value = fv_ids\\n        mapper.util_existing_deployment_resource_key_for_create.return_value = None\\n        mock_get_mapper.return_value = mapper\\n        project_id = uuid4()\\n        mock_resolve_project.return_value = project_id\\n\\n        mock_validate_fv.side_effect = HTTPException(status_code=404, detail=\\\"invalid\\\")\\n\\n        payload = MagicMock()\\n        payload.provider_id = pa.id\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await create_deployment(\\n                session=AsyncMock(), payload=payload, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        assert exc_info.value.status_code == 404\\n        mock_validate_fv.assert_awaited_once()\\n        call_kwargs = mock_validate_fv.call_args.kwargs\\n        assert call_kwargs[\\\"flow_version_ids\\\"] == fv_ids\\n        assert call_kwargs[\\\"project_id\\\"] == project_id\\n        adapter.create.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_project_id_for_deployment_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_empty_flow_version_ids_skips_validation(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_resolve_project,\\n        mock_validate_fv,\\n    ):\\n        \\\"\\\"\\\"When the mapper returns no flow_version_ids, validation still runs (it short-circuits internally).\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import create_deployment\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        create_result = DeploymentCreateResult(id=\\\"prov-1\\\", type=DeploymentType.AGENT)\\n        adapter.create.return_value = create_result\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        mapper.util_create_flow_version_ids.return_value = []\\n        mapper.util_existing_deployment_resource_key_for_create.return_value = None\\n        mapper.resolve_deployment_create = AsyncMock(return_value=MagicMock())\\n        mock_get_mapper.return_value = mapper\\n        mock_resolve_project.return_value = uuid4()\\n\\n        payload = MagicMock()\\n        payload.provider_id = pa.id\\n        payload.display_name = \\\"test\\\"\\n        payload.type = \\\"agent\\\"\\n        payload.description = None\\n\\n        session = AsyncMock()\\n        session.commit.return_value = None\\n\\n        with (\\n            patch(f\\\"{ROUTES_MODULE}.create_deployment_db\\\", new_callable=AsyncMock, return_value=_fake_deployment_row()),\\n            patch(f\\\"{ROUTES_MODULE}.attach_flow_versions\\\", new_callable=AsyncMock),\\n        ):\\n            mapper.shape_deployment_create_result.return_value = MagicMock()\\n            await create_deployment(\\n                session=session, payload=payload, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        mock_validate_fv.assert_awaited_once()\\n        assert mock_validate_fv.call_args.kwargs[\\\"flow_version_ids\\\"] == []\\n\\n\\nclass TestCreateDeploymentSchemaValidation:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_flow_deploy_for_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_project_id_for_deployment_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_mapper_schema_validation_error_surfaces_422(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_resolve_project,\\n        mock_validate_fv,\\n        mock_ensure_flow_deploy,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"Mapper-level schema failures on create surface as HTTP 422.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import create_deployment\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        mapper.util_create_flow_version_ids.return_value = [uuid4()]\\n        mapper.util_existing_deployment_resource_key_for_create.return_value = None\\n        mapper.resolve_deployment_create = AsyncMock(\\n            side_effect=HTTPException(\\n                status_code=422,\\n                detail=\\\"Invalid provider_data payload: simulated adapter validation failure\\\",\\n            )\\n        )\\n        mock_get_mapper.return_value = mapper\\n        mock_resolve_project.return_value = uuid4()\\n\\n        payload = MagicMock()\\n        payload.provider_id = pa.id\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await create_deployment(\\n                session=AsyncMock(), payload=payload, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        assert exc_info.value.status_code == 422\\n        mock_validate_fv.assert_awaited_once()\\n        adapter.create.assert_not_awaited()\\n\\n\\n# ---------------------------------------------------------------------------\\n# update_deployment: project-scoped flow version validation\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestUpdateDeploymentProjectValidation:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_flow_version_patch_for_update\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_validation_called_before_adapter(\\n        self,\\n        mock_resolve_amm,\\n        mock_resolve_fvp,\\n        mock_validate_fv,\\n    ):\\n        \\\"\\\"\\\"validate_project_scoped_flow_version_ids is called before the adapter update.\\\"\\\"\\\"\\n        from langflow.api.v1.deployments import update_deployment\\n\\n        dep_row = _fake_deployment_row()\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        mapper.resolve_deployment_update = AsyncMock(return_value=MagicMock())\\n        mock_resolve_amm.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        add_ids = [uuid4()]\\n        remove_ids = [uuid4()]\\n        mock_resolve_fvp.return_value = (add_ids, remove_ids)\\n\\n        mock_validate_fv.side_effect = HTTPException(status_code=404, detail=\\\"out of project\\\")\\n\\n        payload = MagicMock()\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await update_deployment(\\n                deployment_id=dep_row.id,\\n                session=AsyncMock(),\\n                payload=payload,\\n                current_user=_fake_user(),\\n                telemetry=_fake_telemetry(),\\n            )\\n\\n        assert exc_info.value.status_code == 404\\n        mock_validate_fv.assert_awaited_once()\\n        assert mock_validate_fv.call_args.kwargs[\\\"project_id\\\"] == dep_row.project_id\\n        adapter.update.assert_not_awaited()\\n\\n\\n# ---------------------------------------------------------------------------\\n# list_deployment_llms\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestListDeploymentLlms:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_list_llms_returns_shaped_response(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n    ):\\n        from langflow.api.v1.deployments import list_deployment_llms\\n\\n        provider_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = provider_account\\n\\n        adapter = AsyncMock()\\n        llm_result = SimpleNamespace(\\n            provider_result={\\\"models\\\": [{\\\"model_name\\\": \\\"model-a\\\"}, {\\\"model_name\\\": \\\"model-b\\\"}]},\\n        )\\n        adapter.list_llms.return_value = llm_result\\n        mock_resolve_adapter.return_value = adapter\\n\\n        mapper = MagicMock()\\n        mapper.shape_llm_list_result.return_value = DeploymentLlmListResponse(\\n            provider_data={\\\"models\\\": [{\\\"model_name\\\": \\\"model-a\\\"}, {\\\"model_name\\\": \\\"model-b\\\"}]}\\n        )\\n        mock_get_mapper.return_value = mapper\\n\\n        response = await list_deployment_llms(\\n            provider_id=provider_account.id,\\n            session=AsyncMock(),\\n            current_user=_fake_user(),\\n        )\\n\\n        assert response == DeploymentLlmListResponse(\\n            provider_data={\\\"models\\\": [{\\\"model_name\\\": \\\"model-a\\\"}, {\\\"model_name\\\": \\\"model-b\\\"}]}\\n        )\\n        adapter.list_llms.assert_awaited_once()\\n        mapper.shape_llm_list_result.assert_called_once_with(llm_result)\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_list_llms_maps_adapter_error(\\n        self,\\n        mock_get_provider_account,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n    ):\\n        from langflow.api.v1.deployments import list_deployment_llms\\n\\n        provider_account = _fake_provider_account()\\n        mock_get_provider_account.return_value = provider_account\\n\\n        adapter = AsyncMock()\\n        adapter.list_llms.side_effect = ServiceUnavailableError(message=\\\"provider down\\\")\\n        mock_resolve_adapter.return_value = adapter\\n\\n        mapper = MagicMock()\\n        mock_get_mapper.return_value = mapper\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await list_deployment_llms(\\n                provider_id=provider_account.id,\\n                session=AsyncMock(),\\n                current_user=_fake_user(),\\n            )\\n\\n        assert exc_info.value.status_code == 503\\n        mapper.shape_llm_list_result.assert_not_called()\\n\\n\\n# ---------------------------------------------------------------------------\\n# resolve_deployment_adapter\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestResolveDeploymentAdapter:\\n    def test_empty_provider_key_raises_400(self):\\n        from langflow.api.v1.mappers.deployments.helpers import resolve_deployment_adapter\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            resolve_deployment_adapter(\\\"\\\")\\n\\n        assert exc_info.value.status_code == 400\\n        assert \\\"provider_key\\\" in exc_info.value.detail.lower()\\n\\n    def test_whitespace_only_provider_key_raises_400(self):\\n        from langflow.api.v1.mappers.deployments.helpers import resolve_deployment_adapter\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            resolve_deployment_adapter(\\\"   \\\")\\n\\n        assert exc_info.value.status_code == 400\\n\\n    @patch(f\\\"{HELPERS_MODULE}.get_deployment_adapter\\\", return_value=None)\\n    def test_unknown_provider_key_raises_503(self, _mock_get):  # noqa: PT019\\n        from langflow.api.v1.mappers.deployments.helpers import resolve_deployment_adapter\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            resolve_deployment_adapter(\\\"nonexistent_provider\\\")\\n\\n        assert exc_info.value.status_code == 503\\n        assert \\\"nonexistent_provider\\\" in exc_info.value.detail\\n\\n    @patch(f\\\"{HELPERS_MODULE}.get_deployment_adapter\\\", side_effect=RuntimeError(\\\"registry boom\\\"))\\n    def test_adapter_lookup_error_raises_500(self, _mock_get):  # noqa: PT019\\n        from langflow.api.v1.mappers.deployments.helpers import resolve_deployment_adapter\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            resolve_deployment_adapter(\\\"bad_key\\\")\\n\\n        assert exc_info.value.status_code == 500\\n\\n    @patch(f\\\"{HELPERS_MODULE}.get_deployment_adapter\\\")\\n    def test_valid_provider_key_returns_adapter(self, mock_get):\\n        from langflow.api.v1.mappers.deployments.helpers import resolve_deployment_adapter\\n\\n        sentinel = MagicMock()\\n        mock_get.return_value = sentinel\\n\\n        result = resolve_deployment_adapter(\\\"watsonx_orchestrate\\\")\\n\\n        assert result is sentinel\\n        mock_get.assert_called_once_with(\\\"watsonx_orchestrate\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# handle_adapter_errors: context manager integration\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestHandleAdapterErrors:\\n    def test_maps_authentication_error_to_401(self):\\n        from langflow.api.v1.mappers.deployments.helpers import handle_adapter_errors\\n\\n        with pytest.raises(HTTPException) as exc_info, handle_adapter_errors():\\n            raise AuthenticationError(message=\\\"bad creds\\\", error_code=\\\"authentication_error\\\")\\n\\n        assert exc_info.value.status_code == 401\\n        assert \\\"bad creds\\\" in exc_info.value.detail\\n\\n    def test_maps_service_unavailable_to_503(self):\\n        from langflow.api.v1.mappers.deployments.helpers import handle_adapter_errors\\n\\n        with pytest.raises(HTTPException) as exc_info, handle_adapter_errors():\\n            raise ServiceUnavailableError(message=\\\"provider down\\\")\\n\\n        assert exc_info.value.status_code == 503\\n\\n    def test_maps_not_found_to_404(self):\\n        from langflow.api.v1.mappers.deployments.helpers import handle_adapter_errors\\n\\n        with pytest.raises(HTTPException) as exc_info, handle_adapter_errors():\\n            raise DeploymentNotFoundError(message=\\\"gone\\\")\\n\\n        assert exc_info.value.status_code == 404\\n\\n    def test_maps_conflict_with_mapper_formatter(self):\\n        from langflow.api.v1.mappers.deployments.helpers import handle_adapter_errors\\n\\n        deployment_mapper = MagicMock()\\n        deployment_mapper.format_conflict_detail.return_value = \\\"friendly detail\\\"\\n\\n        with pytest.raises(HTTPException) as exc_info, handle_adapter_errors(mapper=deployment_mapper):\\n            raise ResourceConflictError(message=\\\"raw provider conflict\\\")\\n\\n        assert exc_info.value.status_code == 409\\n        assert exc_info.value.detail == \\\"friendly detail\\\"\\n        deployment_mapper.format_conflict_detail.assert_called_once_with(\\n            \\\"raw provider conflict\\\",\\n            resource=None,\\n            resource_name=None,\\n        )\\n\\n    def test_maps_conflict_passes_structured_resource_to_mapper_formatter(self):\\n        from langflow.api.v1.mappers.deployments.helpers import handle_adapter_errors\\n\\n        deployment_mapper = MagicMock()\\n        deployment_mapper.format_conflict_detail.return_value = \\\"friendly detail\\\"\\n\\n        with pytest.raises(HTTPException) as exc_info, handle_adapter_errors(mapper=deployment_mapper):\\n            raise ResourceConflictError(message=\\\"raw provider conflict\\\", resource=\\\"tool\\\")\\n\\n        assert exc_info.value.status_code == 409\\n        assert exc_info.value.detail == \\\"friendly detail\\\"\\n        deployment_mapper.format_conflict_detail.assert_called_once_with(\\n            \\\"raw provider conflict\\\",\\n            resource=\\\"tool\\\",\\n            resource_name=None,\\n        )\\n\\n    def test_maps_conflict_passes_structured_resource_name_to_mapper_formatter(self):\\n        from langflow.api.v1.mappers.deployments.helpers import handle_adapter_errors\\n\\n        deployment_mapper = MagicMock()\\n        deployment_mapper.format_conflict_detail.return_value = \\\"friendly detail\\\"\\n\\n        with pytest.raises(HTTPException) as exc_info, handle_adapter_errors(mapper=deployment_mapper):\\n            raise ResourceConflictError(\\n                message=\\\"raw provider conflict\\\",\\n                resource=\\\"tool\\\",\\n                resource_name=\\\"Simple_Agent\\\",\\n            )\\n\\n        assert exc_info.value.status_code == 409\\n        assert exc_info.value.detail == \\\"friendly detail\\\"\\n        deployment_mapper.format_conflict_detail.assert_called_once_with(\\n            \\\"raw provider conflict\\\",\\n            resource=\\\"tool\\\",\\n            resource_name=\\\"Simple_Agent\\\",\\n        )\\n\\n    def test_maps_conflict_without_mapper_passthrough(self):\\n        from langflow.api.v1.mappers.deployments.helpers import handle_adapter_errors\\n\\n        with pytest.raises(HTTPException) as exc_info, handle_adapter_errors():\\n            raise ResourceConflictError(message=\\\"raw provider conflict\\\")\\n\\n        assert exc_info.value.status_code == 409\\n        assert exc_info.value.detail == \\\"raw provider conflict\\\"\\n\\n    def test_passes_through_http_exception(self):\\n        from langflow.api.v1.mappers.deployments.helpers import handle_adapter_errors\\n\\n        with pytest.raises(HTTPException) as exc_info, handle_adapter_errors():\\n            raise HTTPException(status_code=418, detail=\\\"teapot\\\")\\n\\n        assert exc_info.value.status_code == 418\\n\\n    def test_maps_not_implemented_to_501(self):\\n        from langflow.api.v1.mappers.deployments.helpers import handle_adapter_errors\\n\\n        msg = \\\"nope\\\"\\n        with pytest.raises(HTTPException) as exc_info, handle_adapter_errors():\\n            raise NotImplementedError(msg)\\n\\n        assert exc_info.value.status_code == 501\\n\\n\\n# ---------------------------------------------------------------------------\\n# RBAC audit repairs: flow:deploy + scoped-key list prefilter\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestCreateDeploymentFlowDeploy:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.rollback_provider_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.attach_flow_versions\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_snapshot_map_for_create\\\", return_value={})\\n    @patch(f\\\"{ROUTES_MODULE}.create_deployment_db\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_flow_deploy_for_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_project_id_for_deployment_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_create_authorizes_flow_deploy_before_provider_create(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_resolve_project,\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_ensure_deploy,\\n        mock_create_db,\\n        mock_resolve_snap,  # noqa: ARG002\\n        mock_attach,  # noqa: ARG002\\n        mock_rollback,  # noqa: ARG002\\n    ):\\n        from langflow.api.v1.deployments import create_deployment\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        call_order: list[str] = []\\n\\n        async def _track_deploy(**_kwargs):\\n            call_order.append(\\\"flow_deploy\\\")\\n\\n        async def _track_create(**_kwargs):\\n            call_order.append(\\\"provider_create\\\")\\n            return DeploymentCreateResult(id=\\\"provider-dep-1\\\", type=DeploymentType.AGENT)\\n\\n        mock_ensure_deploy.side_effect = _track_deploy\\n        adapter = AsyncMock()\\n        adapter.create.side_effect = _track_create\\n        mock_resolve_adapter.return_value = adapter\\n        fv_ids = [uuid4(), uuid4()]\\n        mapper = MagicMock()\\n        mapper.util_create_flow_version_ids.return_value = fv_ids\\n        mapper.util_existing_deployment_resource_key_for_create.return_value = None\\n        mapper.resolve_deployment_create = AsyncMock(return_value=MagicMock())\\n        mapper.resolve_deployment_model_for_create.return_value = MagicMock()\\n        mapper.shape_deployment_create_result.return_value = MagicMock()\\n        mock_get_mapper.return_value = mapper\\n        project_id = uuid4()\\n        mock_resolve_project.return_value = project_id\\n        mock_create_db.return_value = _fake_deployment_row()\\n\\n        user = _fake_user()\\n        session = AsyncMock()\\n        session.commit.return_value = None\\n        payload = MagicMock()\\n        payload.provider_id = pa.id\\n        payload.display_name = \\\"test\\\"\\n        payload.type = \\\"agent\\\"\\n        payload.description = None\\n\\n        await create_deployment(session=session, payload=payload, current_user=user, telemetry=_fake_telemetry())\\n\\n        mock_ensure_deploy.assert_awaited_once_with(\\n            user=user,\\n            flow_version_ids=fv_ids,\\n            owner_id=user.id,\\n            db=session,\\n            project_id=project_id,\\n        )\\n        assert call_order == [\\\"flow_deploy\\\", \\\"provider_create\\\"]\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_flow_deploy_for_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_project_id_for_deployment_create\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    async def test_flow_deploy_deny_skips_provider_create(\\n        self,\\n        mock_get_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_resolve_project,\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_ensure_deploy,\\n    ):\\n        from langflow.api.v1.deployments import create_deployment\\n\\n        pa = _fake_provider_account()\\n        mock_get_pa.return_value = pa\\n        adapter = AsyncMock()\\n        mock_resolve_adapter.return_value = adapter\\n        mapper = MagicMock()\\n        mapper.util_create_flow_version_ids.return_value = [uuid4()]\\n        mapper.util_existing_deployment_resource_key_for_create.return_value = None\\n        mock_get_mapper.return_value = mapper\\n        mock_resolve_project.return_value = uuid4()\\n        mock_ensure_deploy.side_effect = HTTPException(status_code=403, detail=\\\"flow deploy denied\\\")\\n\\n        payload = MagicMock()\\n        payload.provider_id = pa.id\\n        payload.display_name = \\\"test\\\"\\n        payload.type = \\\"agent\\\"\\n        payload.description = None\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await create_deployment(\\n                session=AsyncMock(), payload=payload, current_user=_fake_user(), telemetry=_fake_telemetry()\\n            )\\n\\n        assert exc_info.value.status_code == 403\\n        adapter.create.assert_not_awaited()\\n        adapter.get.assert_not_awaited()\\n\\n\\nclass TestUpdateDeploymentFlowDeploy:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployment_attachments_for_flow_version_ids\\\", new_callable=AsyncMock, return_value=[])\\n    @patch(f\\\"{ROUTES_MODULE}.apply_flow_version_patch_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_added_snapshot_bindings_for_update\\\", return_value=[])\\n    @patch(f\\\"{ROUTES_MODULE}.ensure_flow_deploy_for_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.validate_project_scoped_flow_version_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_flow_version_patch_for_update\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_adapter_mapper_from_deployment\\\", new_callable=AsyncMock)\\n    async def test_update_authorizes_flow_deploy_for_added_versions_only(\\n        self,\\n        mock_resolve_amm,\\n        mock_resolve_fvp,\\n        mock_validate_fv,  # noqa: ARG002\\n        mock_ensure_deploy,\\n        mock_resolve_snap,  # noqa: ARG002\\n        mock_apply_patch,  # noqa: ARG002\\n        mock_list_attachments,  # noqa: ARG002\\n    ):\\n        from langflow.api.v1.deployments import update_deployment\\n\\n        owner_id = uuid4()\\n        actor = _fake_user()\\n        dep_row = _fake_deployment_row(user_id=owner_id)\\n        added = [uuid4()]\\n        removed = [uuid4()]\\n        mock_resolve_fvp.return_value = (added, removed)\\n        adapter = AsyncMock()\\n        mapper = MagicMock()\\n        adapter.update.return_value = DeploymentUpdateResult(id=\\\"provider-dep-1\\\")\\n        mapper.resolve_deployment_update = AsyncMock(return_value=MagicMock())\\n        mapper.resolve_kwargs_for_metadata_update.return_value = {}\\n        mapper.shape_deployment_update_result.return_value = MagicMock()\\n        mock_resolve_amm.return_value = (dep_row, adapter, mapper, \\\"watsonx-orchestrate\\\", \\\"tenant-1\\\")\\n\\n        session = AsyncMock()\\n        session.commit.return_value = None\\n        payload = MagicMock()\\n        payload.display_name = None\\n        payload.description = None\\n\\n        await update_deployment(\\n            deployment_id=dep_row.id,\\n            session=session,\\n            payload=payload,\\n            current_user=actor,\\n            telemetry=_fake_telemetry(),\\n        )\\n\\n        mock_ensure_deploy.assert_awaited_once_with(\\n            user=actor,\\n            flow_version_ids=added,\\n            owner_id=owner_id,\\n            db=session,\\n            project_id=dep_row.project_id,\\n            workspace_id=dep_row.workspace_id,\\n        )\\n        assert adapter.update.await_count == 1\\n\\n\\nclass TestListDeploymentsScopedKeyPrefilter:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ROUTES_MODULE}.list_deployments_synced\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.resolve_deployment_adapter\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_deployment_mapper\\\")\\n    @patch(f\\\"{ROUTES_MODULE}.get_shared_listing_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.get_owned_provider_account_or_404\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.has_visible_deployment_for_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{ROUTES_MODULE}.visible_scope_prefilter\\\", new_callable=AsyncMock)\\n    async def test_concrete_prefilter_threads_visibility_scope_without_owner_union_assumption(\\n        self,\\n        mock_prefilter,\\n        mock_has_visible_deployment,\\n        mock_get_owned_pa,\\n        mock_get_shared_pa,\\n        mock_get_mapper,\\n        mock_resolve_adapter,\\n        mock_synced,\\n    ):\\n        \\\"\\\"\\\"Route-level: a concrete prefilter must reach sync as a visibility scope.\\n\\n        Ownership inclusion for scoped API keys is decided in\\n        ``apply_owned_or_visible_scope_prefilter`` (via\\n        ``_scope_to_owner_or_allowed``); this test locks the route contract that\\n        a concrete prefilter is forwarded (not dropped).\\n        \\\"\\\"\\\"\\n        from langflow.api.v1.deployments import list_deployments\\n\\n        visible_only = uuid4()\\n        visibility_scope = ResourceVisibilityScope(resource_ids=(visible_only,))\\n        pa = _fake_provider_account()\\n        mock_prefilter.return_value = visibility_scope\\n        mock_has_visible_deployment.return_value = True\\n        mock_get_shared_pa.return_value = pa\\n        mock_resolve_adapter.return_value = AsyncMock()\\n        mapper = MagicMock()\\n        mapper.shape_deployment_list_items.return_value = []\\n        mock_get_mapper.return_value = mapper\\n        mock_synced.return_value = ([], 0, {})\\n\\n        actor = _fake_user()\\n        await list_deployments(\\n            provider_id=pa.id,\\n            session=MagicMock(),\\n            current_user=actor,\\n            params=SimpleNamespace(page=1, size=20),\\n            deployment_type=None,\\n        )\\n\\n        mock_get_owned_pa.assert_not_awaited()\\n        assert mock_synced.await_args.kwargs[\\\"visibility_scope\\\"] == visibility_scope\\n        assert mock_synced.await_args.kwargs[\\\"user_id\\\"] == actor.id\\n        assert mock_synced.await_args.kwargs[\\\"row_owner_id\\\"] == pa.user_id\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_deployment_schemas.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3fcf826ccc9b0ec8e4d47cba12afb101d95891ffb6e6fc77b8bbeceec7676352\",\"content\":\"\\\"\\\"\\\"Tests for deployment API schemas.\\n\\nSecurity invariants and validation behaviour that must not regress.\\n\\\"\\\"\\\"\\n\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.api.v1.schemas.deployments import (\\n    DeploymentConfigListResponse,\\n    DeploymentCreateRequest,\\n    DeploymentFlowVersionListItem,\\n    DeploymentFlowVersionListResponse,\\n    DeploymentListItem,\\n    DeploymentListResponse,\\n    DeploymentProviderAccountCreateRequest,\\n    DeploymentProviderAccountGetResponse,\\n    DeploymentProviderAccountUpdateRequest,\\n    DeploymentUpdateRequest,\\n    FlowIdsQuery,\\n)\\nfrom langflow.services.database.models.deployment_provider_account.schemas import DeploymentProviderKey\\nfrom pydantic import ValidationError\\n\\nTEST_API_KEY = \\\"key\\\"  # pragma: allowlist secret\\n\\n# ---------------------------------------------------------------------------\\n# Security: credentials must never appear in response schemas\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestCredentialSecurity:\\n    \\\"\\\"\\\"Ensure credentials are excluded from every response model.\\\"\\\"\\\"\\n\\n    def test_provider_account_response_excludes_api_key(self):\\n        \\\"\\\"\\\"DeploymentProviderAccountGetResponse.model_fields must not contain api_key.\\\"\\\"\\\"\\n        assert \\\"api_key\\\" not in DeploymentProviderAccountGetResponse.model_fields\\n\\n    def test_provider_account_response_includes_provider_data(self):\\n        \\\"\\\"\\\"DeploymentProviderAccountGetResponse includes non-sensitive provider metadata.\\\"\\\"\\\"\\n        assert \\\"provider_data\\\" in DeploymentProviderAccountGetResponse.model_fields\\n\\n    def test_provider_account_response_dump_excludes_credentials(self):\\n        \\\"\\\"\\\"model_dump() on a response instance must never contain credential fields.\\\"\\\"\\\"\\n        response = DeploymentProviderAccountGetResponse(\\n            id=uuid4(),\\n            name=\\\"staging\\\",\\n            provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            provider_data={\\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com\\\", \\\"tenant_id\\\": \\\"tenant-1\\\"},\\n        )\\n        dumped = response.model_dump()\\n        assert \\\"api_key\\\" not in dumped\\n        assert dumped[\\\"provider_data\\\"] == {\\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com\\\", \\\"tenant_id\\\": \\\"tenant-1\\\"}\\n        assert \\\"api_key\\\" not in (dumped[\\\"provider_data\\\"] or {})\\n\\n\\n# ---------------------------------------------------------------------------\\n# NonEmptyStr validation\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestProviderAccountName:\\n    def test_create_accepts_valid_name(self):\\n        account = DeploymentProviderAccountCreateRequest(\\n            name=\\\"production\\\",\\n            provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            provider_data={\\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com\\\", \\\"api_key\\\": TEST_API_KEY},\\n        )\\n        assert account.name == \\\"production\\\"\\n\\n    def test_create_strips_name_whitespace(self):\\n        account = DeploymentProviderAccountCreateRequest(\\n            name=\\\"  staging  \\\",\\n            provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            provider_data={\\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com\\\", \\\"api_key\\\": TEST_API_KEY},\\n        )\\n        assert account.name == \\\"staging\\\"\\n\\n    def test_create_rejects_empty_name(self):\\n        with pytest.raises(ValidationError, match=\\\"name\\\"):\\n            DeploymentProviderAccountCreateRequest(\\n                name=\\\"\\\",\\n                provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n                provider_data={\\\"url\\\": \\\"https://example.com\\\", \\\"api_key\\\": TEST_API_KEY},\\n            )\\n\\n    def test_create_rejects_whitespace_only_name(self):\\n        with pytest.raises(ValidationError, match=\\\"name\\\"):\\n            DeploymentProviderAccountCreateRequest(\\n                name=\\\"   \\\",\\n                provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n                provider_data={\\\"url\\\": \\\"https://example.com\\\", \\\"api_key\\\": TEST_API_KEY},\\n            )\\n\\n    def test_create_rejects_missing_name(self):\\n        with pytest.raises(ValidationError):\\n            DeploymentProviderAccountCreateRequest(\\n                provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n                provider_data={\\\"url\\\": \\\"https://example.com\\\", \\\"api_key\\\": TEST_API_KEY},\\n            )\\n\\n    def test_update_accepts_name(self):\\n        update = DeploymentProviderAccountUpdateRequest(name=\\\"new-name\\\")\\n        assert update.name == \\\"new-name\\\"\\n\\n    def test_update_rejects_null_name(self):\\n        with pytest.raises(ValidationError, match=r\\\"name.*cannot be set to null\\\"):\\n            DeploymentProviderAccountUpdateRequest(name=None)\\n\\n    def test_response_includes_name(self):\\n        assert \\\"name\\\" in DeploymentProviderAccountGetResponse.model_fields\\n\\n\\n# ---------------------------------------------------------------------------\\n# Provider-data contract boundary\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestProviderAccountProviderDataBoundary:\\n    \\\"\\\"\\\"Provider-specific fields belong under provider_data at the API boundary.\\\"\\\"\\\"\\n\\n    def test_create_accepts_provider_data_url(self):\\n        account = DeploymentProviderAccountCreateRequest(\\n            name=\\\"staging\\\",\\n            provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            provider_data={\\n                \\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com/v1\\\",\\n                \\\"api_key\\\": TEST_API_KEY,\\n            },\\n        )\\n        assert account.provider_data[\\\"url\\\"] == \\\"https://api.us-south.wxo.cloud.ibm.com/v1\\\"\\n\\n    def test_update_rejects_url_field(self):\\n        with pytest.raises(ValidationError, match=\\\"Extra inputs are not permitted\\\"):\\n            DeploymentProviderAccountUpdateRequest(url=\\\"https://new.example.com/api\\\")\\n\\n    def test_update_rejects_tenant_id_field(self):\\n        with pytest.raises(ValidationError, match=\\\"Extra inputs are not permitted\\\"):\\n            DeploymentProviderAccountUpdateRequest(tenant_id=\\\"tenant-1\\\")\\n\\n    def test_create_rejects_top_level_tenant_id_field(self):\\n        with pytest.raises(ValidationError, match=\\\"Extra inputs are not permitted\\\"):\\n            DeploymentProviderAccountCreateRequest(\\n                name=\\\"staging\\\",\\n                tenant_id=\\\"tenant-1\\\",\\n                provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n                provider_data={\\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com/v1\\\", \\\"api_key\\\": TEST_API_KEY},\\n            )\\n\\n    def test_create_rejects_top_level_url_field(self):\\n        with pytest.raises(ValidationError, match=\\\"Extra inputs are not permitted\\\"):\\n            DeploymentProviderAccountCreateRequest(\\n                name=\\\"staging\\\",\\n                provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n                url=\\\"https://api.us-south.wxo.cloud.ibm.com/v1\\\",\\n                provider_data={\\\"api_key\\\": TEST_API_KEY},\\n            )\\n\\n\\nclass TestProviderKeyEnum:\\n    def test_accepts_valid_enum_value(self):\\n        account = DeploymentProviderAccountCreateRequest(\\n            name=\\\"staging\\\",\\n            provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            provider_data={\\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com\\\", \\\"api_key\\\": TEST_API_KEY},\\n        )\\n        assert account.provider_key == DeploymentProviderKey.WATSONX_ORCHESTRATE\\n\\n    def test_accepts_valid_string_value(self):\\n        account = DeploymentProviderAccountCreateRequest(\\n            name=\\\"staging\\\",\\n            provider_key=\\\"watsonx-orchestrate\\\",\\n            provider_data={\\\"url\\\": \\\"https://api.us-south.wxo.cloud.ibm.com\\\", \\\"api_key\\\": TEST_API_KEY},\\n        )\\n        assert account.provider_key == DeploymentProviderKey.WATSONX_ORCHESTRATE\\n\\n    def test_rejects_invalid_provider_key(self):\\n        with pytest.raises(ValidationError):\\n            DeploymentProviderAccountCreateRequest(\\n                name=\\\"staging\\\",\\n                provider_key=\\\"unknown-provider\\\",\\n                provider_data={\\\"url\\\": \\\"https://example.com\\\", \\\"api_key\\\": TEST_API_KEY},\\n            )\\n\\n    def test_rejects_empty_string(self):\\n        with pytest.raises(ValidationError):\\n            DeploymentProviderAccountCreateRequest(\\n                name=\\\"staging\\\",\\n                provider_key=\\\"\\\",\\n                provider_data={\\\"url\\\": \\\"https://example.com\\\", \\\"api_key\\\": TEST_API_KEY},\\n            )\\n\\n\\nclass TestDeploymentUpdateRequest:\\n    def test_accepts_provider_data_only(self):\\n        payload = DeploymentUpdateRequest(provider_data={\\\"mode\\\": \\\"dry_run\\\"})\\n        assert payload.provider_data == {\\\"mode\\\": \\\"dry_run\\\"}\\n\\n    def test_rejects_empty_payload(self):\\n        with pytest.raises(ValidationError, match=\\\"At least one of\\\"):\\n            DeploymentUpdateRequest()\\n\\n    def test_accepts_explicit_null_description(self):\\n        payload = DeploymentUpdateRequest(description=None)\\n        assert payload.description is None\\n        assert \\\"description\\\" in payload.model_fields_set\\n\\n    def test_accepts_long_description(self):\\n        description = \\\"x\\\" * 501\\n\\n        payload = DeploymentUpdateRequest(description=description)\\n\\n        assert payload.description == description\\n\\n\\nclass TestDeploymentSpecPayloadCompatibility:\\n    def test_create_request_rejects_provider_spec_dict(self):\\n        with pytest.raises(ValidationError, match=\\\"provider_spec\\\"):\\n            DeploymentCreateRequest(\\n                provider_id=uuid4(),\\n                description=\\\"\\\",\\n                type=\\\"agent\\\",\\n                provider_spec={\\\"region\\\": \\\"us-east-1\\\", \\\"size\\\": \\\"small\\\"},\\n            )\\n\\n    def test_create_request_accepts_provider_data_payload(self):\\n        request = DeploymentCreateRequest(\\n            provider_id=uuid4(),\\n            description=\\\"\\\",\\n            type=\\\"agent\\\",\\n            provider_data={\\\"display_name\\\": \\\"deployment\\\", \\\"operations\\\": []},\\n        )\\n        assert request.provider_data == {\\\"display_name\\\": \\\"deployment\\\", \\\"operations\\\": []}\\n\\n    def test_create_request_accepts_long_description(self):\\n        description = \\\"x\\\" * 501\\n\\n        request = DeploymentCreateRequest(\\n            provider_id=uuid4(),\\n            description=description,\\n            type=\\\"agent\\\",\\n            provider_data={\\\"display_name\\\": \\\"deployment\\\", \\\"operations\\\": []},\\n        )\\n\\n        assert request.description == description\\n\\n\\n# ---------------------------------------------------------------------------\\n# DeploymentConfigListResponse / DeploymentSnapshotListResponse\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestDeploymentConfigListResponse:\\n    def test_provider_data_contains_connections(self):\\n        response = DeploymentConfigListResponse(\\n            provider_data={\\n                \\\"connections\\\": [\\n                    {\\\"id\\\": \\\"cfg_1\\\", \\\"name\\\": \\\"Config 1\\\"},\\n                    {\\\"id\\\": \\\"cfg_2\\\", \\\"name\\\": \\\"Config 2\\\"},\\n                ],\\n                \\\"scope\\\": \\\"shared\\\",\\n            },\\n            page=1,\\n            size=20,\\n            total=2,\\n        )\\n        assert len(response.provider_data[\\\"connections\\\"]) == 2\\n        assert response.provider_data[\\\"scope\\\"] == \\\"shared\\\"\\n        assert response.page == 1\\n        assert response.total == 2\\n\\n    def test_allows_null_provider_data(self):\\n        response = DeploymentConfigListResponse()\\n        assert response.provider_data is None\\n        assert response.page is None\\n        assert response.size is None\\n        assert response.total is None\\n\\n    def test_has_provider_data_and_pagination_fields_only(self):\\n        assert set(DeploymentConfigListResponse.model_fields.keys()) == {\\n            \\\"provider_data\\\",\\n            \\\"page\\\",\\n            \\\"size\\\",\\n            \\\"total\\\",\\n        }\\n\\n\\nclass TestDeploymentSnapshotListResponse:\\n    def test_provider_data_contains_tools(self):\\n        from langflow.api.v1.schemas.deployments import DeploymentSnapshotListResponse\\n\\n        response = DeploymentSnapshotListResponse(\\n            provider_data={\\n                \\\"tools\\\": [\\n                    {\\\"id\\\": \\\"tool-1\\\", \\\"name\\\": \\\"Tool 1\\\"},\\n                    {\\\"id\\\": \\\"tool-2\\\", \\\"name\\\": \\\"Tool 2\\\"},\\n                ],\\n                \\\"scope\\\": \\\"shared\\\",\\n            },\\n            page=1,\\n            size=20,\\n            total=2,\\n        )\\n        assert len(response.provider_data[\\\"tools\\\"]) == 2\\n        assert response.page == 1\\n\\n    def test_allows_null_provider_data(self):\\n        from langflow.api.v1.schemas.deployments import DeploymentSnapshotListResponse\\n\\n        response = DeploymentSnapshotListResponse()\\n        assert response.provider_data is None\\n\\n    def test_has_provider_data_and_pagination_fields_only(self):\\n        from langflow.api.v1.schemas.deployments import DeploymentSnapshotListResponse\\n\\n        assert set(DeploymentSnapshotListResponse.model_fields.keys()) == {\\n            \\\"provider_data\\\",\\n            \\\"page\\\",\\n            \\\"size\\\",\\n            \\\"total\\\",\\n        }\\n\\n\\nclass TestDeploymentFlowVersionListSchemas:\\n    def test_flow_version_list_item_uses_attached_at(self):\\n        from datetime import datetime, timezone\\n\\n        now = datetime.now(tz=timezone.utc)\\n        item = DeploymentFlowVersionListItem(\\n            id=uuid4(),\\n            flow_id=uuid4(),\\n            version_number=3,\\n            attached_at=now,\\n            provider_snapshot_id=\\\"tool-1\\\",\\n            provider_data={\\\"app_ids\\\": [\\\"cfg-1\\\"]},\\n        )\\n        assert item.attached_at == now\\n        assert item.provider_snapshot_id == \\\"tool-1\\\"\\n        assert item.provider_data == {\\\"app_ids\\\": [\\\"cfg-1\\\"]}\\n\\n    def test_flow_version_list_item_does_not_expose_description_or_created_at(self):\\n        assert \\\"description\\\" not in DeploymentFlowVersionListItem.model_fields\\n        assert \\\"created_at\\\" not in DeploymentFlowVersionListItem.model_fields\\n\\n    def test_flow_version_list_response_wraps_items_with_pagination(self):\\n        response = DeploymentFlowVersionListResponse(\\n            flow_versions=[\\n                DeploymentFlowVersionListItem(\\n                    id=uuid4(),\\n                    flow_id=uuid4(),\\n                    version_number=1,\\n                    attached_at=None,\\n                    provider_snapshot_id=None,\\n                    provider_data=None,\\n                )\\n            ],\\n            page=2,\\n            size=5,\\n            total=9,\\n        )\\n        assert len(response.flow_versions) == 1\\n        assert response.page == 2\\n        assert response.size == 5\\n        assert response.total == 9\\n\\n\\nclass TestDeploymentListResponse:\\n    def test_allows_provider_only_shape(self):\\n        response = DeploymentListResponse(provider_data={\\\"deployments\\\": []})\\n        assert response.deployments is None\\n        assert response.page is None\\n        assert response.size is None\\n        assert response.total is None\\n        assert response.provider_data == {\\\"deployments\\\": []}\\n\\n\\n# ---------------------------------------------------------------------------\\n# FlowIdsQuery validation\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestFlowIdsQueryValidation:\\n    \\\"\\\"\\\"Validate the FlowIdsQuery annotated type used for the list_deployments filter.\\\"\\\"\\\"\\n\\n    def test_none_passes_through(self):\\n        from pydantic import TypeAdapter\\n\\n        adapter = TypeAdapter(FlowIdsQuery)\\n        assert adapter.validate_python(None) is None\\n\\n    def test_single_valid_uuid(self):\\n        from pydantic import TypeAdapter\\n\\n        uid = uuid4()\\n        adapter = TypeAdapter(FlowIdsQuery)\\n        result = adapter.validate_python([uid])\\n        assert result == [uid]\\n\\n    def test_accepts_string_uuid(self):\\n        from pydantic import TypeAdapter\\n\\n        uid = uuid4()\\n        adapter = TypeAdapter(FlowIdsQuery)\\n        result = adapter.validate_python([str(uid)])\\n        assert result == [uid]\\n\\n    def test_rejects_more_than_one(self):\\n        from pydantic import TypeAdapter, ValidationError\\n\\n        adapter = TypeAdapter(FlowIdsQuery)\\n        with pytest.raises(ValidationError, match=\\\"at most 1\\\"):\\n            adapter.validate_python([uuid4(), uuid4()])\\n\\n    def test_rejects_invalid_uuid(self):\\n        from pydantic import TypeAdapter, ValidationError\\n\\n        adapter = TypeAdapter(FlowIdsQuery)\\n        with pytest.raises(ValidationError):\\n            adapter.validate_python([\\\"not-a-uuid\\\"])\\n\\n    def test_rejects_empty_list(self):\\n        from pydantic import TypeAdapter, ValidationError\\n\\n        adapter = TypeAdapter(FlowIdsQuery)\\n        with pytest.raises(ValidationError, match=\\\"flow_ids\\\"):\\n            adapter.validate_python([])\\n\\n    def test_deduplicates(self):\\n        from pydantic import TypeAdapter\\n\\n        uid = uuid4()\\n        adapter = TypeAdapter(FlowIdsQuery)\\n        result = adapter.validate_python([uid, uid])\\n        assert result == [uid]\\n\\n\\n# ---------------------------------------------------------------------------\\n# DeploymentListItem.flow_version_ids\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestDeploymentListItemFlowVersionIds:\\n    def _make_item(self, **kwargs):\\n        defaults = {\\n            \\\"id\\\": uuid4(),\\n            \\\"provider_id\\\": uuid4(),\\n            \\\"provider_key\\\": DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            \\\"type\\\": \\\"agent\\\",\\n            \\\"resource_key\\\": \\\"rk-1\\\",\\n            \\\"provider_data\\\": {\\\"display_name\\\": \\\"dep\\\"},\\n        }\\n        defaults.update(kwargs)\\n        return DeploymentListItem(**defaults)\\n\\n    def test_defaults_to_none(self):\\n        item = self._make_item()\\n        assert item.flow_version_ids is None\\n\\n    def test_accepts_flow_version_ids_list(self):\\n        fv_id = uuid4()\\n        item = self._make_item(\\n            flow_version_ids=[fv_id],\\n        )\\n        assert item.flow_version_ids == [fv_id]\\n\\n    def test_accepts_empty_list(self):\\n        item = self._make_item(flow_version_ids=[])\\n        assert item.flow_version_ids == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# DeploymentConfigListResponse \u2014 pagination & empty configs\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestDeploymentConfigListResponsePagination:\\n    def test_rejects_page_less_than_one(self):\\n        with pytest.raises(ValidationError):\\n            DeploymentConfigListResponse(page=0, size=10, total=0)\\n\\n    def test_rejects_size_less_than_one(self):\\n        with pytest.raises(ValidationError):\\n            DeploymentConfigListResponse(page=1, size=0, total=0)\\n\\n    def test_rejects_negative_total(self):\\n        with pytest.raises(ValidationError):\\n            DeploymentConfigListResponse(page=1, size=10, total=-1)\\n\\n\\n# ---------------------------------------------------------------------------\\n# ExecutionCreateRequest \u2014 required fields, provider_data validation\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestRunCreateRequest:\\n    def test_rejects_extra_fields(self):\\n        from langflow.api.v1.schemas.deployments import RunCreateRequest\\n\\n        with pytest.raises(ValidationError, match=\\\"Extra inputs are not permitted\\\"):\\n            RunCreateRequest(provider_data={\\\"input\\\": \\\"x\\\"}, unknown_field=\\\"y\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# ExecutionCreateResponse \u2014 all fields including nullable provider_data\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestRunCreateResponse:\\n    def test_required_deployment_id(self):\\n        from langflow.api.v1.schemas.deployments import RunCreateResponse\\n\\n        with pytest.raises(ValidationError, match=\\\"deployment_id\\\"):\\n            RunCreateResponse()\\n\\n\\n# ---------------------------------------------------------------------------\\n# SnapshotUpdateRequest \u2014 required fields\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestSnapshotUpdateRequest:\\n    def test_requires_flow_version_id(self):\\n        from langflow.api.v1.schemas.deployments import SnapshotUpdateRequest\\n\\n        with pytest.raises(ValidationError, match=\\\"flow_version_id\\\"):\\n            SnapshotUpdateRequest()\\n\\n    def test_rejects_extra_fields(self):\\n        from langflow.api.v1.schemas.deployments import SnapshotUpdateRequest\\n\\n        with pytest.raises(ValidationError, match=\\\"Extra inputs are not permitted\\\"):\\n            SnapshotUpdateRequest(flow_version_id=uuid4(), extra_field=\\\"bad\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# SnapshotUpdateResponse \u2014 response fields\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestSnapshotUpdateResponse:\\n    def test_requires_flow_version_id(self):\\n        from langflow.api.v1.schemas.deployments import SnapshotUpdateResponse\\n\\n        with pytest.raises(ValidationError, match=\\\"flow_version_id\\\"):\\n            SnapshotUpdateResponse(provider_snapshot_id=\\\"snap-1\\\")\\n\\n    def test_requires_provider_snapshot_id(self):\\n        from langflow.api.v1.schemas.deployments import SnapshotUpdateResponse\\n\\n        with pytest.raises(ValidationError, match=\\\"provider_snapshot_id\\\"):\\n            SnapshotUpdateResponse(flow_version_id=uuid4())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_deployment_sync.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"490a1217b06b99dca6f19f621c8d6ab44bd62581423ec117ac3cb3e8e4cd9cd2\",\"content\":\"\\\"\\\"\\\"Tests for deployment provider-sync helpers.\\n\\nCovers:\\n- fetch_provider_resource_keys: ID-only matching, error handling\\n- list_deployments_synced: cursor-based sync with inline stale-row deletion\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom typing import TYPE_CHECKING, Any\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.api.v1.mappers.deployments.base import BaseDeploymentMapper\\nfrom langflow.api.v1.mappers.deployments.contracts import (\\n    CreateSnapshotBinding,\\n    CreateSnapshotBindings,\\n    UpdateSnapshotBinding,\\n    UpdateSnapshotBindings,\\n)\\nfrom langflow.api.v1.mappers.deployments.watsonx_orchestrate import WatsonxOrchestrateDeploymentMapper\\nfrom langflow.api.v1.schemas.deployments import DeploymentUpdateRequest\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.flow_version.model import FlowVersion\\nfrom langflow.services.database.models.user.model import User\\nfrom lfx.services.adapters.deployment.exceptions import ServiceUnavailableError\\nfrom lfx.services.adapters.deployment.schema import (\\n    DeploymentCreateResult,\\n    DeploymentGetResult,\\n    DeploymentType,\\n    DeploymentUpdateResult,\\n    SnapshotItem,\\n    SnapshotListResult,\\n)\\n\\nif TYPE_CHECKING:\\n    from sqlalchemy.ext.asyncio import AsyncSession\\n\\nMODULE = \\\"langflow.api.v1.mappers.deployments.helpers\\\"\\nSYNC_MODULE = \\\"langflow.api.v1.mappers.deployments.sync\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _mock_item(*, item_id: str, name: str = \\\"irrelevant\\\") -> SimpleNamespace:\\n    return SimpleNamespace(id=item_id, name=name)\\n\\n\\ndef _mock_provider_view(items: list) -> SimpleNamespace:\\n    return SimpleNamespace(deployments=items)\\n\\n\\ndef _wxo_deployment_provider_data(\\n    *,\\n    tool_ids: list[str],\\n    environments: list[str] | None = None,\\n    display_name: str = \\\"Agent Display\\\",\\n    description: str = \\\"Agent description\\\",\\n    llm: str = \\\"meta-llm\\\",\\n) -> dict[str, Any]:\\n    return {\\n        \\\"display_name\\\": display_name,\\n        \\\"description\\\": description,\\n        \\\"tool_ids\\\": tool_ids,\\n        \\\"llm\\\": llm,\\n        \\\"environments\\\": environments or [],\\n    }\\n\\n\\ndef _mock_deployment_row(\\n    resource_key: str,\\n    deployment_type: str | None = None,\\n    *,\\n    user_id: UUID | None = None,\\n) -> SimpleNamespace:\\n    return SimpleNamespace(\\n        id=uuid4(),\\n        resource_key=resource_key,\\n        display_name=\\\"Deployment\\\",\\n        description=None,\\n        deployment_type=deployment_type,\\n        deployment_provider_account_id=uuid4(),\\n        user_id=user_id or uuid4(),\\n    )\\n\\n\\nclass _NoSnapshotBindingMapper(BaseDeploymentMapper):\\n    def extract_snapshot_bindings(self, provider_view) -> list[Any]:\\n        _ = provider_view\\n        return []\\n\\n    def extract_metadata_for_list(self, provider_view) -> dict[str, dict[str, Any]]:\\n        if provider_view is None:\\n            return {}\\n        return {\\n            str(item.id): {\\n                \\\"display_name\\\": (getattr(item, \\\"provider_data\\\", {}) or {}).get(\\n                    \\\"display_name\\\", getattr(item, \\\"name\\\", str(item.id))\\n                ),\\n                \\\"description\\\": (getattr(item, \\\"provider_data\\\", {}) or {}).get(\\\"description\\\"),\\n            }\\n            for item in provider_view.deployments\\n        }\\n\\n\\nclass _AsyncNoopSavepoint:\\n    async def __aenter__(self):\\n        return None\\n\\n    async def __aexit__(self, exc_type, exc, tb):\\n        return False\\n\\n\\ndef _mock_async_db() -> MagicMock:\\n    db = MagicMock()\\n    db.begin_nested.return_value = _AsyncNoopSavepoint()\\n    db.exec = AsyncMock(return_value=MagicMock(all=MagicMock(return_value=[])))\\n    return db\\n\\n\\n@pytest.mark.asyncio\\n@patch(f\\\"{MODULE}.update_deployment_metadata\\\", new_callable=AsyncMock)\\nasync def test_sync_deployment_display_metadata_passes_provider_metadata(mock_update_metadata):\\n    from langflow.api.v1.mappers.deployments.helpers import sync_deployment_display_metadata\\n\\n    deployment = _mock_deployment_row(\\\"rk-1\\\")\\n    long_description = \\\"x\\\" * 501\\n    mock_update_metadata.return_value = deployment\\n\\n    result = await sync_deployment_display_metadata(\\n        MagicMock(),\\n        deployment=deployment,\\n        provider_metadata={\\n            \\\"display_name\\\": \\\"Provider Name\\\",\\n            \\\"description\\\": long_description,\\n        },\\n        user_id=uuid4(),\\n    )\\n\\n    assert result is deployment\\n    mock_update_metadata.assert_awaited_once()\\n    assert mock_update_metadata.call_args.kwargs[\\\"display_name\\\"] == \\\"Provider Name\\\"\\n    assert mock_update_metadata.call_args.kwargs[\\\"description\\\"] == long_description\\n\\n\\n# ---------------------------------------------------------------------------\\n# fetch_provider_resource_keys\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestFetchProviderResourceKeys:\\n    @pytest.mark.asyncio\\n    async def test_returns_ids_only(self):\\n        \\\"\\\"\\\"Provider items matched by str(item.id), not item.name.\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n        adapter.list.return_value = _mock_provider_view(\\n            [\\n                _mock_item(item_id=\\\"rk-1\\\", name=\\\"deploy-one\\\"),\\n                _mock_item(item_id=\\\"rk-2\\\", name=\\\"deploy-two\\\"),\\n            ]\\n        )\\n\\n        from langflow.api.v1.mappers.deployments.helpers import fetch_provider_resource_keys\\n\\n        known_keys, provider_view = await fetch_provider_resource_keys(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            resource_keys=[\\\"rk-1\\\", \\\"rk-2\\\"],\\n        )\\n\\n        assert known_keys == {\\\"rk-1\\\", \\\"rk-2\\\"}\\n        assert provider_view is adapter.list.return_value\\n\\n    @pytest.mark.asyncio\\n    async def test_does_not_match_by_name(self):\\n        \\\"\\\"\\\"If a name matches a resource_key but the id doesn't, it should NOT be included.\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n        # Provider returns item with id=\\\"different\\\" but name=\\\"rk-1\\\"\\n        adapter.list.return_value = _mock_provider_view(\\n            [\\n                _mock_item(item_id=\\\"different\\\", name=\\\"rk-1\\\"),\\n            ]\\n        )\\n\\n        from langflow.api.v1.mappers.deployments.helpers import fetch_provider_resource_keys\\n\\n        known_keys, provider_view = await fetch_provider_resource_keys(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            resource_keys=[\\\"rk-1\\\"],\\n        )\\n\\n        # \\\"rk-1\\\" is NOT in the result because only id is checked, and id=\\\"different\\\"\\n        assert \\\"rk-1\\\" not in known_keys\\n        assert known_keys == {\\\"different\\\"}\\n        assert provider_view is adapter.list.return_value\\n\\n    @pytest.mark.asyncio\\n    async def test_empty_provider_id_raises_value_error(self):\\n        adapter = AsyncMock()\\n        adapter.list.return_value = _mock_provider_view(\\n            [\\n                _mock_item(item_id=\\\"rk-1\\\"),\\n                _mock_item(item_id=\\\"\\\"),  # falsy id\\n            ]\\n        )\\n\\n        from langflow.api.v1.mappers.deployments.helpers import fetch_provider_resource_keys\\n\\n        with pytest.raises(ValueError, match=\\\"empty id\\\"):\\n            await fetch_provider_resource_keys(\\n                deployment_adapter=adapter,\\n                user_id=uuid4(),\\n                provider_id=uuid4(),\\n                db=AsyncMock(),\\n                resource_keys=[\\\"rk-1\\\"],\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_empty_provider_response(self):\\n        adapter = AsyncMock()\\n        adapter.list.return_value = _mock_provider_view([])\\n\\n        from langflow.api.v1.mappers.deployments.helpers import fetch_provider_resource_keys\\n\\n        known_keys, provider_view = await fetch_provider_resource_keys(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            resource_keys=[\\\"rk-1\\\"],\\n        )\\n\\n        assert known_keys == set()\\n        assert provider_view is adapter.list.return_value\\n\\n    @pytest.mark.asyncio\\n    async def test_provider_error_raises_500_for_unhandled_exception(self):\\n        adapter = AsyncMock()\\n        adapter.list.side_effect = RuntimeError(\\\"provider down\\\")\\n\\n        from langflow.api.v1.mappers.deployments.helpers import fetch_provider_resource_keys\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await fetch_provider_resource_keys(\\n                deployment_adapter=adapter,\\n                user_id=uuid4(),\\n                provider_id=uuid4(),\\n                db=AsyncMock(),\\n                resource_keys=[\\\"rk-1\\\"],\\n            )\\n\\n        assert exc_info.value.status_code == 500\\n\\n    @pytest.mark.asyncio\\n    async def test_provider_deployment_service_error_uses_mapped_http_status(self):\\n        adapter = AsyncMock()\\n        adapter.list.side_effect = ServiceUnavailableError(\\\"provider down\\\")\\n\\n        from langflow.api.v1.mappers.deployments.helpers import fetch_provider_resource_keys\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await fetch_provider_resource_keys(\\n                deployment_adapter=adapter,\\n                user_id=uuid4(),\\n                provider_id=uuid4(),\\n                db=AsyncMock(),\\n                resource_keys=[\\\"rk-1\\\"],\\n            )\\n\\n        assert exc_info.value.status_code == 503\\n        assert exc_info.value.detail == \\\"provider down\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_passes_resource_keys_as_deployment_ids(self):\\n        adapter = AsyncMock()\\n        adapter.list.return_value = _mock_provider_view([])\\n\\n        from langflow.api.v1.mappers.deployments.helpers import fetch_provider_resource_keys\\n\\n        keys = [\\\"rk-1\\\", \\\"rk-2\\\", \\\"rk-3\\\"]\\n        await fetch_provider_resource_keys(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            resource_keys=keys,\\n        )\\n\\n        call_args = adapter.list.call_args\\n        params = call_args.kwargs[\\\"params\\\"]\\n        assert params.deployment_ids == keys\\n        assert params.provider_params is None\\n        assert params.deployment_types is None\\n\\n    @pytest.mark.asyncio\\n    async def test_empty_resource_keys_returns_empty_set(self):\\n        adapter = AsyncMock()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import fetch_provider_resource_keys\\n\\n        known_keys, provider_view = await fetch_provider_resource_keys(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            resource_keys=[],\\n        )\\n\\n        assert known_keys == set()\\n        assert provider_view.deployments == []\\n        adapter.list.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    async def test_passes_deployment_type_filter(self):\\n        \\\"\\\"\\\"When deployment_type is provided, it's forwarded to the provider.\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n        adapter.list.return_value = _mock_provider_view([])\\n\\n        from langflow.api.v1.mappers.deployments.helpers import DeploymentType, fetch_provider_resource_keys\\n\\n       ";
